-- Production provider-conflict notices --------------------------------------
-- Keep this independent from DIAGNOSTICS: a compatibility refusal that makes a
-- selected BC feature disappear must be visible to an ordinary user. Reasons
-- are registered on state.compatibilityNotice so future provider-owned intros
-- or flow systems can use the same one-shot presentation without another HUD.
state.compatibilityNotice.now=function()
  if love and love.timer and type(love.timer.getTime)=="function" then
    local ok,v=pcall(love.timer.getTime)
    if ok and tonumber(v) then return tonumber(v) end
  end
  return os.clock()
end
state.compatibilityNotice.show=function(reason)
  local N=state.compatibilityNotice
  local spec=N.specs and N.specs[reason]
  if type(spec)~="table" then return false end
  N.shown=N.shown or {}
  if N.shown[reason] then return false end
  N.shown[reason]=true
  N.reason=reason
  N.untilTime=N.now()+(tonumber(spec.duration) or 6.0)
  mod.log:warn("[compatibility] %s: %s",tostring(spec.title),tostring(spec.line1))
  return true
end
state.battleOpening.compatibilityNotice=function(reason)
  if reason=="CBE AUTO BATTLE FLOW ON" then
    return state.compatibilityNotice.show("PHENAC_CBE_AUTO_FLOW")
  elseif reason=="CBE BOSS INTRO SELECTED" then
    return state.compatibilityNotice.show("PHENAC_CBE_BOSS_INTRO")
  end
  return false
end
state.compatibilityNotice.draw=function()
  local N=state.compatibilityNotice
  if not N.reason then return end
  local spec=N.specs and N.specs[N.reason]
  if type(spec)~="table" then N.reason=nil return end
  if N.now()>(tonumber(N.untilTime) or 0) then
    N.reason=nil
    return
  end
  if not (love and love.graphics) then return end

  local ok,err=pcall(function()
    local g=love.graphics
    if not N.font then N.font=g.newFont(12) end
    local screenW=(g.getWidth and g.getWidth()) or 1120
    local screenH=(g.getHeight and g.getHeight()) or 630
    local x,y,boxW,boxH,pad
    if spec.pipDefault then
      -- Test80: match the established SMALL / MID RIGHT PiP footprint rather
      -- than introducing another notice location.  This remains independent
      -- of the user's saved custom PiP placement because the message explains
      -- why Secondary View itself has been refused for this doubles battle.
      boxW=math.max(220,math.floor(screenW*0.20))
      boxH=math.min(math.floor(screenH*0.34),math.floor(boxW*9/16))
      x=screenW-boxW-12
      y=math.max(12,math.floor(screenH*0.65-boxH-8))
      pad=10
    else
      x,y=12,12
      boxW=math.min(460,math.max(280,screenW-24))
      boxH=78
      pad=8
    end

    g.push("all")
    g.origin()
    g.setFont(N.font)
    g.setColor(0,0,0,0.86)
    g.rectangle("fill",x,y,boxW,boxH,4,4)
    g.setColor(1,0.80,0.28,0.96)
    g.setLineWidth(1)
    g.rectangle("line",x+0.5,y+0.5,boxW-1,boxH-1,4,4)
    g.setColor(1,1,1,1)
    g.print("BATTLE CINEMATICS",x+pad,y+6)
    g.setColor(1,0.86,0.40,1)
    g.print(spec.title,x+pad,y+22)
    g.setColor(1,1,1,1)
    if spec.pipDefault then
      g.printf(spec.line1,x+pad,y+42,boxW-pad*2,"left")
      g.setColor(0.84,0.84,0.84,1)
      g.printf(spec.line2,x+pad,y+76,boxW-pad*2,"left")
    else
      g.print(spec.line1,x+pad,y+39)
      g.setColor(0.84,0.84,0.84,1)
      g.printf(spec.line2,x+pad,y+55,boxW-pad*2,"left")
    end
    g.pop()
  end)
  if not ok and not N.drawErrorLogged then
    N.drawErrorLogged=true
    mod.log:warn("[compatibility] notice HUD failed: %s",tostring(err))
  end
end

-- Battle Intro applicability -------------------------------------------------
do
-- Gen2 battle.started supplies a BattleState view whose authoritative battle
-- model sits under .battle. Other providers may add another wrapper. Build a
-- bounded list of only the known presentation/model links so classification is
-- correct without traversing arbitrary runtime graphs.
local function battleOpeningLayers(root)
  local out,seen={},{}
  local function add(v)
    if type(v)~="table" or seen[v] or #out>=10 then return end
    seen[v]=true;out[#out+1]=v
  end
  add(root)
  local i=1
  while i<=#out and #out<10 do
    local v=out[i]
    add(v.battle);add(v.model);add(v._model);add(v.view);add(v._view)
    i=i+1
  end
  return out
end

local TOKEN_FIELDS={
  "kind","battleType","type","category","oppClass","trainerClass",
  "class","className","oppName","trainerName","enemyTrainerName",
  "music","musicKind","musicId","bgm","bgmId",
}
local TRAINER_FIELDS={"id","name","classId","class","className","personalName","type","role","title"}

local function battleOpeningTokens(root)
  local out={}
  local function add(v)
    if v~=nil and type(v)~="table" then
      out[#out+1]=tostring(v):upper():gsub("[^%w]+","_")
    end
  end
  local function addFields(t,fields)
    if type(t)~="table" then return end
    for _,k in ipairs(fields) do add(t[k]) end
  end
  local function addTrainer(t)
    if type(t)=="table" then addFields(t,TRAINER_FIELDS) else add(t) end
  end
  for _,v in ipairs(battleOpeningLayers(root)) do
    addFields(v,TOKEN_FIELDS)
    addTrainer(v.trainer);addTrainer(v.enemyTrainer);addTrainer(v.opponent)
    if type(v.encounter)=="table" then addFields(v.encounter,TOKEN_FIELDS) end
    if type(v.data)=="table" then
      addFields(v.data,TOKEN_FIELDS)
      addTrainer(v.data.trainer);addTrainer(v.data.enemyTrainer);addTrainer(v.data.opponent)
    end
  end
  return out
end

local function battleOpeningHasToken(tokens,needles)
  for _,token in ipairs(tokens or {}) do
    for _,needle in ipairs(needles or {}) do
      if token:find(needle,1,true) then return true end
    end
  end
  return false
end

local function battleOpeningGeneration(root)
  for _,v in ipairs(battleOpeningLayers(root)) do
    if tonumber(v.__cbeGeneration) then return tonumber(v.__cbeGeneration) end
  end
  return bcRuntimeGeneration()
end

local function battleOpeningIsWild(root)
  for _,v in ipairs(battleOpeningLayers(root)) do
    local kind=tostring(v.kind or v.battleType or v.category or ""):lower()
    if v.wild==true or v.safari==true or kind=="wild" or kind=="safari" then
      return true
    end
  end
  return false
end

local function battleOpeningHasGymFlag(root)
  for _,v in ipairs(battleOpeningLayers(root)) do
    if v.isGymLeader==true or v.gymLeader==true then return true end
    local tr=v.trainer
    if type(tr)=="table" and (tr.isGymLeader==true or tr.gymLeader==true) then return true end
  end
  return false
end

local function battleOpeningClass(root)
  if battleOpeningIsWild(root) then return "wild" end
  local gen=battleOpeningGeneration(root)
  local tokens=battleOpeningTokens(root)

  -- An explicit host gym flag outranks names/classes. This preserves Giovanni's
  -- non-gym encounters and cleanly recognises every badge-awarding battle.
  if battleOpeningHasGymFlag(root) then return "gym" end

  -- Champion and Rival are separate product classes even when Gen1 uses the
  -- same rival character. OPP_RIVAL3 is the Gen1 Champion; Gen2 Lance is the
  -- Champion, while Gen1 Lance remains Elite Four.
  if battleOpeningHasToken(tokens,{"CHAMPION","OPP_CHAMPION"})
      or (gen==1 and battleOpeningHasToken(tokens,{"OPP_RIVAL3","FINAL_BATTLE","FINALBATTLE","FINAL_MATCH","FINALMATCH","FINAL"}))
      or (gen==2 and battleOpeningHasToken(tokens,{"OPP_LANCE","LANCE","CHAMPION_LANCE","PKMN_CHAMPION_LANCE"})) then
    return "champion"
  end

  if battleOpeningHasToken(tokens,{"ELITE_FOUR","ELITE4","ELITE_4","ELITE_MEMBER"})
      or (gen==1 and battleOpeningHasToken(tokens,{"OPP_LORELEI","LORELEI","OPP_BRUNO","BRUNO","OPP_AGATHA","AGATHA","OPP_LANCE","LANCE"}))
      or (gen==2 and battleOpeningHasToken(tokens,{"OPP_WILL","WILL","OPP_KOGA","KOGA","OPP_BRUNO","BRUNO","OPP_KAREN","KAREN"})) then
    return "elite"
  end

  -- Generic leader metadata plus the complete generation-specific roster.
  -- Gen1 Giovanni still relies on the authoritative flag/class token so his
  -- Rocket encounters are not mislabeled as Gym battles.
  local gymTokens={"GYM_LEADER","GYMLEADER","GYM_BATTLE","GYMBATTLE","TRAINER_CLASS_LEADER","CLASS_LEADER","LEADER"}
  if gen==1 then
    for _,v in ipairs({"OPP_BROCK","OPP_MISTY","OPP_LT_SURGE","OPP_ERIKA","OPP_KOGA","OPP_SABRINA","OPP_BLAINE"}) do
      gymTokens[#gymTokens+1]=v
    end
  else
    for _,v in ipairs({
      "FALKNER","BUGSY","WHITNEY","MORTY","CHUCK","JASMINE","PRYCE","CLAIR",
      "BROCK","MISTY","LT_SURGE","ERIKA","JANINE","SABRINA","BLAINE","BLUE",
    }) do gymTokens[#gymTokens+1]=v end
  end
  if battleOpeningHasToken(tokens,gymTokens) then return "gym" end

  -- Champion was resolved above, so every remaining rival class belongs to the
  -- ordinary Rival assignment, including the Gen2 Silver lineage.
  if battleOpeningHasToken(tokens,{"OPP_RIVAL1","OPP_RIVAL2","OPP_RIVAL3","RIVAL_BATTLE","RIVAL1","RIVAL2","RIVAL3","TRAINER_CLASS_RIVAL","CLASS_RIVAL","RIVAL"}) then
    return "rival"
  end
  return "trainer"
end

local BATTLE_OPENING_SCOPE_KEY={
  wild="battleOpeningScopeWild",
  trainer="battleOpeningScopeTrainer",
  gym="battleOpeningScopeGym",
  elite="battleOpeningScopeElite",
  champion="battleOpeningScopeChampion",
  rival="battleOpeningScopeRival",
}

local function battleOpeningMasterEnabled()
  local v=mod.options:get("battleOpening")
  return v=="on" or v=="colosseum" -- Test29/31 save compatibility.
end

local function battleOpeningAssignedStyle(class)
  local key=BATTLE_OPENING_SCOPE_KEY[class] or BATTLE_OPENING_SCOPE_KEY.trainer
  local v=mod.options:get(key)
  if v=="on" then v="colosseum" end -- Test30/31 save compatibility.
  if v~="colosseum" then return "off" end
  return v
end

local function battleOpeningSelectionFor(root)
  local class=battleOpeningClass(root or state.battle)
  if bcGen2RecompedDramaticPresent() then return "off",class end
  if not battleOpeningMasterEnabled() then return "off",class end
  return battleOpeningAssignedStyle(class),class
end

state.battleOpening.classify=battleOpeningClass
state.battleOpening.optionStyle=function(source)
  if (state.battleOpening.pending or state.battleOpening.active)
      and state.battleOpening.style~=nil then
    return state.battleOpening.style,state.battleOpening.scopeClass
  end
  return battleOpeningSelectionFor(source or state.battle)
end
end
state.battleOpening.enabled=function()
  if state.battleOpening.pending or state.battleOpening.active then
    return state.battleOpening.style~=nil and state.battleOpening.style~="off"
  end
  return state.battleOpening.optionStyle()~="off"
end
state.battleOpening.skipToHold=function(reason)
  if not state.battleOpening.active or state.battleOpening.phase~="swoop" then
    return false
  end
  state.battleOpening.time=tonumber(state.battleOpening.duration) or 13.20
  state.battleOpening.phase="hold"
  state.battleOpening.holdTime=0
  state.battleOpening.safetyLift=0
  state.battleOpening.safetyLiftTarget=0
  -- This is an intentional camera-only CUT to the authored Phenac prompt
  -- composition. The logical B edge is consumed before BattleState sees it,
  -- so the game's encounter text/send-out lifecycle does not advance.
  state.blend=1
  logDiagnostic("battle opening skipped -> Phenac prompt hold ("..tostring(reason or "skip")..")")
  return true
end
state.battleOpening.clear=function()
  state.battleOpening.pending=false
  state.battleOpening.active=false
  state.battleOpening.style=nil
  state.battleOpening.scopeClass=nil
  state.battleOpening.time=0
  state.battleOpening.duration=13.20
  state.battleOpening.phase="idle"
  state.battleOpening.holdTime=0
  state.battleOpening.trainerPromptSeen=false
  state.battleOpening.wildPrompt=false
  state.battleOpening.lastCamera=nil
  state.battleOpening.lastPitch=nil
  state.battleOpening.safetyKey=nil
  state.battleOpening.safetyConstrained=false
  state.battleOpening.safetyReason=nil
  state.battleOpening.safetyLift=0
  state.battleOpening.safetyLiftTarget=0
end
-- Release scope, not a new indoor path planner. Keep Test36 separate until
-- its moving room-fit is accepted. Do not offer a known wall-crossing opening
-- over non-CBE interior maps; ordinary Pokemon Intro remains in charge there.
do
  local B=state.battleOpening
  local function layers(root)
    local out,seen={},{}
    local function add(v) if type(v)=="table" and not seen[v] and #out<10 then seen[v]=true;out[#out+1]=v end end
    add(root)
    local i=1
    while i<=#out and #out<10 do
      local v=out[i];add(v.battle);add(v._model);add(v._view);add(v.model);add(v.view);i=i+1
    end
    return out
  end
  function B.releaseScope(source)
    local list=layers(source)
    local game=mod.game
    for _,v in ipairs(list) do if type(v.game)=="table" then game=v.game;break end end
    local okC,h=pcall(mod.find,"COLOSSEUM_BATTLE_ENVIRONMENTS")
    local combined=false
    if not (okC and h) then
      local okO,o=pcall(mod.find,"COLOSSEUM_OVERHAUL")
      local ov=okO and o and tostring(o.version or (o.exports and o.exports.version)) or ""
      if okO and o and ov=="1.0" then okC,h,combined=true,o,true end
    end
    local p=game and game.save and game.save.colosseumBattle
    if type(p)~="table" then p=nil end
    if okC and h and (not p or p.arenasEnabled~=false) then
      if tostring(h.version or (h.exports and h.exports.version))=="2.0" or combined then
        p=p or {}
        -- PRIORITY resolves the camera in the CBE seam; no saved CBE toggle
        -- needs changing. COOPERATIVE retains CBE's selected native opening.
        if not state.cameraAuthority.priority() and p.cameraEnabled~=false then
          return false,"CBE CAMERA ON"
        end
        if p.bossIntroEnabled==true then return false,"CBE BOSS INTRO SELECTED" end
        if p.autoProgressEnabled~=false and not state.cbeOpeningAutoGate77 then
          return false,"CBE AUTO BATTLE FLOW ON"
        end
        -- DOUBLE BATTLES is permission for CBE to admit an eligible encounter,
        -- not camera ownership of every battle. Do not pre-veto Phenac from the
        -- saved toggle. If CBE actually starts doubles, its live camera seam
        -- reports nativeOwner="CBE DOUBLES"; provider:frame() already clears
        -- any pending/active Phenac gate and yields immediately to that runtime.
      end
      return true,"CBE STAGE"
    end
    -- Test17: direct Stadium2 Importer 0.14.2 on Gold can move the encounter
    -- off the overworld into an explicitly selected self-contained environment
    -- or native Stadium arena before BC decides whether Phenac is safe.  Gen1
    -- already reaches Phenac on these stages; Gold previously ignored the live
    -- scene selection here and fell through to overworld indoor/map safety.
    -- Admit ONLY the provider-owned stage modes proved by the exact live scene.
    -- Classic remains governed by the existing map-safety path below.
    if bcRuntimeGeneration()==2 then
      local gold=backends.__gold
      if type(gold)=="table" and gold.providerKind=="stadium2_importer" then
        local ix=gold.exports
        if bcImporterSceneApi(ix) then
          local live=nil
          local sceneApi=type(ix)=="table" and ix.scene or nil
          if type(sceneApi)=="table" and type(sceneApi.current)=="function" then
            local okS,value=pcall(sceneApi.current)
            if okS and type(value)=="table" then live=value end
          end
          if type(live)~="table" then live=gold.scene end
          local selection=type(live)=="table" and live.environmentSelection or nil
          local mode=type(selection)=="table" and selection.mode or nil
          if mode=="environment" then
            return true,"IMPORTER GEN2 ENVIRONMENT STAGE"
          elseif mode=="arena" and bcImporterNativeScene(ix,live) then
            return true,"IMPORTER GEN2 STADIUM STAGE"
          end
        end
      end
    end

    -- Explicit Importer HOST DEFAULT is a separate authored stage, not a
    -- live room. Do not disable it merely because the encounter map is indoor.
    if mod.options:get("importerArena")=="host" then
      local okI,importer=pcall(mod.find,"STADIUM2_IMPORTER")
      if okI and importer then return true,"IMPORTER HOST STAGE" end
    end
    local map=nil
    for _,v in ipairs(list) do
      if type(v.map)=="table" and type(v.map.def)=="table" then map=v.map;break end
    end
    if not map then
      local ow=game and game.overworld
      if type(ow)=="table" and type(ow.map)=="table" then map=ow.map end
    end
    local def=map and map.def
    if type(def)~="table" then return false,"MAP CONTEXT UNVERIFIED" end
    local outside=def.outdoor
    if type(outside)~="boolean" then
      local name=bcRuntimeGeneration()==2 and "src.world.gen2.Map" or "src.world.Map"
      local okM,M=pcall(require,name)
      if okM and type(M)=="table" and type(M.isOutside)=="function" then
        local okO,value=pcall(M.isOutside,def)
        if okO and type(value)=="boolean" then outside=value end
      end
    end
    if outside~=true then return false,"INDOOR PHENAC DEFERRED" end
    return true,"OUTDOOR MAP"
  end
end
state.battleOpening.queue=function(source)
  state.battleOpening.clear()
  local style,class=state.battleOpening.optionStyle(source)
  if style~="off" then
    local allowed,reason=state.battleOpening.releaseScope(source)
    state.battleOpening.releaseScopeReason=reason
    if not allowed then
      -- Failure-point notice only: the user actually selected Phenac for this
      -- encounter, but a known provider presentation setting refused it.
      -- Expected ownership (COOPERATIVE/native doubles/etc.) stays silent.
      if enabled() then state.battleOpening.compatibilityNotice(reason) end
      style="off"
    end
  end
  if not enabled() then style="off" end
  state.battleOpening.style=style
  state.battleOpening.scopeClass=class
  state.intro.fullOpeningStyle=style
  state.intro.fullOpeningClass=class
  state.intro.suppressOpeningWildEnemy=(style=="colosseum" and class=="wild")
  if style~="off" then
    state.battleOpening.pending=true
    state.battleOpening.duration=13.20
  end
end
state.battleOpening.begin=function()
  if not state.battleOpening.pending or state.battleOpening.style~="colosseum" then return false end
  state.battleOpening.pending=false
  state.battleOpening.active=true
  state.battleOpening.time=0
  state.battleOpening.duration=13.20
  state.battleOpening.phase="swoop"
  state.battleOpening.holdTime=0
  local b=state.battle
  state.battleOpening.trainerPromptSeen=b and (not not b.showEnemyTrainer) or false
  state.battleOpening.wildPrompt=state.battleOpening.scopeClass=="wild"
      or (b and (b.wild==true or (type(b.battle)=="table" and b.battle.wild==true))) or false
  state.active=false
  state.idle=0
  state.blend=0
  logDiagnostic("battle opening started: "..tostring(state.battleOpening.style)
      ..(state.battleOpening.wildPrompt and " / wild" or ""))
  return true
end

-- Phenac encounter ownership -------------------------------------------------
-- The full Battle Intro is an encounter gate, not merely a camera laid over a
-- live prompt. A is blocked while the travelling phrase owns the encounter; B
-- is consumed as a camera-only jump to HOLD. At HOLD, A is left in the normal
-- logical input queue and the same edge releases the battle-level camera.
state.battleOpening.release=function(reason,defensive)
  if not state.battleOpening.active then return false end
  local battle=state.battle
  local wild=(battle and battle.wild) and true or state.battleOpening.wildPrompt

  -- Fail-safe only: if a host somehow progressed despite the gate, do not replay
  -- Pokemon Intro history that is already visibly over. A player send-out means
  -- the trainer-side enemy send-out has completed; a menu/move means both initial
  -- actors have already entered. Normal HOLD+A release leaves the queued Intro
  -- chain untouched.
  if defensive and battle then
    if battle.phase=="menu" then
      state.intro.pendingEnemy=false
      state.intro.pendingPlayer=false
      state.intro.initial=false
      state.intro.openingBridgeActive=false
    elseif (not wild) and battle.sendingOut then
      state.intro.pendingEnemy=false
    end
  end

  -- In a wild battle Phenac has already presented the opponent. Release all
  -- BC primary-camera ownership so the real trainer throw/send-out remains
  -- visible, then admit only the queued PLAYER Hero after the host's
  -- showPlayerBack/sendingOut transition has genuinely completed.
  if wild and state.intro.initial and state.intro.pendingPlayer
      and not state.intro.pendingEnemy then
    state.intro.pendingEnemy=false
    state.intro.suppressOpeningWildEnemy=true
    state.intro.openingBridgeActive=false
    state.intro.openingChainHold=false
    state.intro.wildPlayerSendoutGate=true
    state.intro.wildPlayerSendoutSeen=(battle and
        (battle.showPlayerBack or battle.sendingOut)) and true or false
  end

  local style=state.battleOpening.style
  state.battleOpening.clear()
  state.blend=0
  state.active=false
  state.idle=0
  logDiagnostic("battle opening released: "..tostring(style).." / "
      ..tostring(reason or "prompt")..(defensive and " / reconciled" or ""))
  return true
end

state.battleOpening.gateLogicalInput=function(game,before)
  if not state.battleOpening.active then return false end
  local input=game and game.input
  local q=input and input.pressQueue
  if type(q)~="table" then return false end
  before=math.max(0,math.min(#q,tonumber(before) or 0))

  local phase=state.battleOpening.phase
  local sawA,sawB=false,false
  for i=#q,before+1,-1 do
    local action=q[i]
    if phase=="swoop" and (action=="a" or action=="b") then
      table.remove(q,i)
      if action=="a" then sawA=true else sawB=true end
    elseif phase=="hold" and action=="a" then
      -- Do not remove it: this exact logical edge must still advance the host.
      sawA=true
    end
  end

  if phase=="swoop" then
    if sawB then
      state.battleOpening.skipToHold("B button")
      return true
    end
    if sawA then
      logDiagnostic("Phenac encounter gate blocked A during swoop")
      return true
    end
  elseif phase=="hold" and sawA then
    state.battleOpening.release("A prompt advance",false)
    return true
  end
  return false
end

local HERO_INTRO_DURATION=9.4
-- Compact Send-In Test 1: later player summons facing an already-active enemy
-- get a deliberately shorter portrait phrase rather than forcing the battle
-- engine to wait for the full ceremonial BC Hero entrance.
local function battleIntroStyle()
  -- Gold Test 5 deliberately enables the EXISTING BC Hero / Send-In Director
  -- through the same saved option as Gen 1.  The Gold adapter supplies the live
  -- presentation state; no separate Gold intro grammar is invented here.
  return mod.options:get("dynamicIntro")=="off" and "off" or "hero"
end
local function battleIntroOn()
  return battleIntroStyle() ~= "off"
end
-- v1.5 Test92: Terrarium/CBE Colosseum routes should not require users to
-- discover a second BC setting before the source-derived action/send-in camera
-- can work. Preserve OFF as an explicit opt-out. Otherwise the historical
-- STADIUM value becomes host-auto: ordinary/non-Colosseum providers still get
-- Stadium, while a positively identified Terrarium/CBE Colosseum presentation
-- receives the already-validated COLOSSEUM director. The saved option is never
-- rewritten, so leaving the provider restores the user's ordinary Stadium path.
local function autoColosseumAttackHost()
  local C=backends and backends.__cbe
  if C and C.active==true then return true,"CBE CAMERA SEAM" end

  -- COLOSSEUM A/B can run on Terrarium's live voxel/overworld route without the
  -- standalone CBE camera seam. Use the provider's own exported selector rather
  -- than inferring the mode from sprites, actors or arena geometry.
  for _,backend in ipairs(backends or {}) do
    local OW=backend and backend.providerId=="DRAMATIC_SHAPE" and backend.OverworldBattle or nil
    if type(OW)=="table" and type(OW.colosseum)=="function" then
      local ok,value=pcall(OW.colosseum)
      if ok and value==true then return true,"TERRARIUM COLOSSEUM A/B" end
    end
  end

  -- Staged Terrarium/CBE can be bound through the resident presentation bridge
  -- before/without the generic C.active bit on a particular frame. This is the
  -- same exact context already used by the validated staged singles/doubles work.
  local X=state and state.terrariumCbeCameraAuthorityTest15 or nil
  if X and X.live and type(X.live.context)=="table" then
    return true,"TERRARIUM STAGED CBE"
  end

  local battle=state and state.battle or nil
  if type(battle)=="table" and (battle.__cbeBCView==true
      or battle.__cbeDoublesActive==true or battle.phase=="cbe_doubles") then
    return true,"CBE PRESENTATION"
  end
  return false,nil
end

local function attackCameraStyle()
  local saved=mod.options:get("attackCamera") or "off"
  if saved=="off" then
    state.attackCameraAutoColosseum=false;state.attackCameraAutoReason=nil
    return "off"
  end
  local auto,reason=autoColosseumAttackHost()
  state.attackCameraAutoColosseum=auto and true or false
  state.attackCameraAutoReason=auto and reason or nil
  if auto then return "colosseum" end
  return saved
end
local function stadiumAttackOn()
  -- COLOSSEUM is additive: it uses the existing Attack Camera lifecycle and
  -- changes only the positively identified Terrarium native contact-camera
  -- solve below. Everywhere else it degrades to the existing Stadium path.
  local style=attackCameraStyle()
  return style=="stadium" or style=="colosseum"
end
local function faintCameraOn()
  -- Gold Test 6 likewise enables the existing Faint Camera rather than a
  -- generation-specific copy.  Adapter facts below supply Gold presentation
  -- timing while Gen-1 behaviour remains unchanged.
  return mod.options:get("faintCamera") ~= "off"
end
local function introFramingScale()
  local value=mod.options:get("introFraming") or "wide"
  -- Optical-only framing control. WIDE is the APB-era canonical BC Hero intro
  -- composition. The historical 1.00 "standard" value remains save-compatible
  -- but is now labelled NEAR because APB-aware subjects make it visibly tighter.
  -- EXTRA WIDE gives additional breathing room; CLOSE remains the intentional
  -- intimate portrait treatment.
  if value=="extra_wide" then return 1.75 end
  if value=="wide" then return 1.45 end
  if value=="close" then return 0.78 end
  return 1.00
end
local function introSpeedScale()
  local value=mod.options:get("introSpeed") or "fast"
  if value=="faster" then return 3.0 end    -- optional accelerated intro presentation
  if value=="fast" then return 2.0 end      -- established v0.7.1 default
  if value=="slow" then return 0.75 end     -- gentler presentation
  return 1.0                                -- normal / legacy normal
end
function bcIntroPanOn()
  return (mod.options:get("introPan") or "off") ~= "off"
end
local function introResetMode()
  return mod.options:get("introReset") or "b"
end
-- Test39: on the verified Terrarium/CBE Colosseum route, Pokemon Intro keeps
-- the established BC Hero timing/lifecycle for BOTH sides and only refits its
-- authored camera to the same close live-bounds optical language as S3.
-- Keep this provider-owned/narrow so Stadium/Importer/voxel and standalone
-- hosts remain byte-for-byte on their established Intro timing.
state.intro.colosseumCbeIntro39=function()
  return state.intro.colosseumCbeLive39==true and attackCameraStyle()=="colosseum"
end
local cancelActiveIntro
local function clearIntro(preserveStructuralHandoff,preserveOpeningAnchor)
  state.intro.active=false
  state.intro.style=nil
  state.intro.side=nil
  state.intro.time=0
  state.intro.compact=false
  if not preserveOpeningAnchor then
    state.intro.openingStructuralCamera=nil
    state.intro.openingStructuralMode=nil
    state.intro.openingStructuralPitch=nil
    state.intro.openingChainCamera=nil
    state.intro.openingChainPitch=nil
    state.intro.openingChainMode=nil
    state.intro.openingChainHold=false
    state.intro.openingBridgeActive=false
    state.intro.openingChainSide39=nil
  end
  if not preserveStructuralHandoff then
    state.intro.structuralHandoffNeeded=false
  end
end
local function queueIntro(side)
  if battleIntroStyle()~="hero" then return end
  -- A full encounter-level Battle Intro already presents the initial wild
  -- opponent. Keep that suppression authoritative across every event seam: a
  -- later battler_switched notification for the same opening must not re-arm
  -- the redundant enemy Pokemon Intro. Trainer battles are unaffected, and
  -- later non-initial enemy replacements remain eligible as before.
  if side=="enemy" and state.intro.initial
      and state.intro.suppressOpeningWildEnemy then
    state.intro.pendingEnemy=false
    logDiagnostic("initial wild enemy Pokemon Intro suppressed by Phenac Stadium")
    return
  end
  if side=="enemy" then state.intro.pendingEnemy=true
  elseif side=="player" then state.intro.pendingPlayer=true end
end
state.intro.playerUnderThreat=function(battle)
  -- Test 3 keeps Test 2's narrow rule but distinguishes an enemy that is
  -- merely live from a hostile action that can actually follow this Send-In.
  --
  -- Gen 1 trainer battles can offer the player a free change after an opponent
  -- faints. The foe's replacement is presented first and the player's agreed
  -- replacement follows. At that instant battle.enemy is live, but there is no
  -- immediate hostile action waiting to pre-empt the player's presentation.
  if state.intro.initial or not battle then return false end
  if state.intro.battleArtGen2Opening then return false end
  if state.intro.enemyFreshSendIn then return false end
  -- A forced replacement after the player's own faint begins only after the
  -- KO'ing action has completed. The next state after this Send-In is the
  -- player's command menu, so there is no immediate hostile action to outrun.
  if state.intro.playerFaintReplacement then return false end
  if battle.showEnemyTrainer or battle.enemySendingOut then return false end
  local enemy=battle.enemy
  if not enemy or enemy.fainted then return false end
  local shown=tonumber(enemy.shownHP)
  if shown~=nil and shown<=0 then return false end
  return true
end

local function startIntro(side,style,compact)
  style=style or "hero"
  state.intro.openingBridgeActive=false
  if side=="player" then
    state.intro.wildPlayerSendoutGate=false
    state.intro.wildPlayerSendoutSeen=false
  end
  state.intro.active=true
  state.intro.style=style
  state.intro.side=side
  state.intro.time=0
  -- The inter-Intro hold ends the instant the next Pokemon Intro really starts.
  -- Keep openingChainCamera as the blend/base anchor, but stop presenting it.
  state.intro.openingChainHold=false
  -- Battle Art Gen2's opening player presentation is encounter-level Hero,
  -- never a threat-shortened Compact Send-In. The explicit opening marker is
  -- cleared only when the initial Intro chain itself completes/cancels.
  if side=="player" and state.intro.battleArtGen2Opening then compact=false end
  state.intro.compact=compact and true or false
  state.intro.structuralHandoffNeeded=false
  if side=="player" then
    -- This grace belongs only to the immediate replacement chain. Once the
    -- player's Send-In is classified, the newly arrived enemy becomes an
    -- ordinary established threat for any later voluntary switch.
    state.intro.enemyFreshSendIn=false
    state.intro.playerFaintReplacement=false
  end
  if side=="enemy" then
    state.intro.pendingEnemy=false
  elseif side=="player" then
    state.intro.pendingPlayer=false
  end
  state.active=false
  state.idle=0
  state.blend=0
  if state.intro.compact then
    logDiagnostic("compact send-in: "..tostring(side).." / live enemy")
  else
    logDiagnostic("battle intro: "..style..(side and (" / "..side) or ""))
  end
end
local function clearAttack()
  state.attack.pending=false
  state.attack.active=false
  state.attack.side=nil
  state.attack.moveId=nil
  state.attack.mode="target"
  state.attack.time=0
  state.attack.progress=0
  state.attack.sawAnimation=false
  state.attack.animTotal=0
  state.attack.tail=0
  state.attack.goldAnimToken=nil
  state.attack.apbSnapshotReady=false
  state.attack.apbAttackerBounds=nil
  state.attack.apbTargetBounds=nil
end
local function clearFaint()
  state.faint.pending=false
  state.faint.active=false
  state.faint.side=nil
  state.faint.battler=nil
  state.faint.time=0
  state.faint.shownStart=nil
  state.faint.zeroReached=false
  state.faint.zeroTime=0
  state.faint.stadiumSeen=false
  state.faint.stadiumGone=0
end
local function queueFaint(side,battler)
  if not enabled() or not faintCameraOn() or not side or not battler then return end
  -- onFaint fires when actual HP reaches zero, before the queued move FX / HP
  -- drain / visible collapse have necessarily finished. Record the victim here;
  -- camera ownership is handed over later so we never pre-empt the attack.
  clearFaint()
  state.faint.pending=true
  state.faint.side=side
  state.faint.battler=battler
  state.faint.shownStart=tonumber(battler.shownHP)
  logDiagnostic("faint camera queued: "..tostring(side))
end
local function beginFaint()
  if not state.faint.pending or not faintCameraOn() then return false end
  state.battleOpening.clear()
  local lateGen2=backends.__gold or backends.__battleArtGen2 or bcCbeActive()
  local keepGoldEnemy=lateGen2 and state.intro.pendingEnemy or false
  local keepGoldPlayer=lateGen2 and state.intro.pendingPlayer or false
  clearIntro()
  state.intro.pendingEnemy=keepGoldEnemy
  state.intro.pendingPlayer=keepGoldPlayer
  state.faint.pending=false
  state.faint.active=true
  state.faint.time=0
  state.faint.zeroReached=false
  state.faint.zeroTime=0
  state.faint.stadiumSeen=false
  state.faint.stadiumGone=0
  state.active=false
  state.idle=0
  -- A faint is a deliberate cut from the completed attack/engine camera to the
  -- defeated Pokemon. Do not spend its collapse blending through the rear rig.
  state.blend=1
  logDiagnostic("faint camera started: "..tostring(state.faint.side))
  return true
end
local function classifyAttackMove(battle,move)
  -- Gen1Recomp exposes the merged move-effect record through battle.data.
  -- Its own battle engine documents a useful semantic distinction: status
  -- effects with accuracyChecked=true are aimed at the opponent; the other
  -- primary status effects operate on the user. Reuse that contract instead
  -- of maintaining a brittle list of move names, while keeping sensible
  -- fallbacks for old/alternate data registries.
  if not move then return "target" end
  if (tonumber(move.power) or 0)>0 then return "target" end

  local effect=move.effect
  if effect=="HAZE_EFFECT" then return "field" end

  local effects=battle and battle.data and battle.data.move_effects
  local record=effects and effect and effects[effect] or nil
  if type(record)=="table" and record.kind=="primary" then
    return record.accuracyChecked and "target" or "self"
  end

  -- Older caches / third-party effect registries may not expose the record
  -- metadata above. These are the opponent-directed primary effect families
  -- in Gen 1; unknown zero-power moves are safer framed on their user than on
  -- an opponent they may never touch.
  local opponentEffects={
    SLEEP_EFFECT=true, POISON_EFFECT=true, PARALYZE_EFFECT=true,
    CONFUSION_EFFECT=true, LEECH_SEED_EFFECT=true, DISABLE_EFFECT=true,
    ATTACK_DOWN1_EFFECT=true, DEFENSE_DOWN1_EFFECT=true,
    DEFENSE_DOWN2_EFFECT=true, SPEED_DOWN1_EFFECT=true,
    ACCURACY_DOWN1_EFFECT=true,
  }
  if opponentEffects[effect] then return "target" end
  if move.id=="ROAR" then return "target" end
  return "self"
end

local function armAttack(side,moveId,mode)
  if not enabled() or not stadiumAttackOn() then return end
  -- move_used is the reliable commitment signal, but the text announcement can
  -- precede the visual animation by an arbitrary amount of time. Arm here and
  -- take camera control only when Gen1Recomp actually starts AnimPlayer.
  state.attack.pending=true
  state.attack.active=false
  state.attack.side=side
  state.attack.moveId=moveId
  state.attack.mode=mode or "target"
  state.attack.time=0
  state.attack.progress=0
  state.attack.sawAnimation=false
  state.attack.animTotal=0
  state.attack.tail=0
  state.attack.goldAnimToken=nil
  state.attack.apbSnapshotReady=false
  state.attack.apbAttackerBounds=nil
  state.attack.apbTargetBounds=nil
  logDiagnostic("stadium attack armed: "..tostring(side).." / "..tostring(moveId).." / "..tostring(state.attack.mode))
end
local function beginAttack()
  if not state.attack.pending then return end
  state.battleOpening.clear()
  -- Gen 1 can safely discard a queued Intro when a real move starts. Gen 2 is
  -- presentation-late: its logic may already have emitted a future replacement
  -- battler_switched while the finishing move has not yet appeared on screen.
  -- Preserve those future Send-In arms on Gold so the visible replacement can
  -- still receive BC Hero after the current Attack Camera finishes.
  local lateGen2=backends.__gold or backends.__battleArtGen2 or bcCbeActive()
  local keepGoldEnemy=lateGen2 and state.intro.pendingEnemy or false
  local keepGoldPlayer=lateGen2 and state.intro.pendingPlayer or false
  clearIntro()
  state.intro.pendingEnemy=keepGoldEnemy
  state.intro.pendingPlayer=keepGoldPlayer
  state.attack.pending=false
  state.attack.active=true
  state.attack.time=0
  state.attack.progress=0
  state.attack.sawAnimation=false
  state.attack.animTotal=0
  state.attack.tail=0
  state.attack.goldAnimToken=nil
  state.active=false
  state.idle=0
  -- Stadium uses deliberate cuts; do not spend the first shot blending out of
  -- the ordinary rear camera.
  state.blend=1
  logDiagnostic("stadium attack camera started")
end

local function activity()
  state.idle=0
