    if okA and type(arena)=="table" and type(arena.player)=="table" and type(arena.enemy)=="table" then
      P.voxelAscendantConstantLastArena=arena
    elseif constantLive and importerContext()~=nil and type(P.voxelAscendantConstantLastArena)=="table" then
