    -- models are genuinely enabled. Do not let the newly attached Gen2 vanilla
    -- renderer race/overwrite that PiP.
    if isGen2 and importerContext()~=nil then return false end
    local b=OW.battle()
    local arena=OW.arena()
    local expectedBattle=state.battle
    if isGen2 and type(expectedBattle)=="table"
        and type(expectedBattle.__battleArtGen2Screen)=="table" then
      expectedBattle=expectedBattle.__battleArtGen2Screen
    end
    local liveStage=b and b==expectedBattle and type(arena)=="table"
      and type(arena.player)=="table" and type(arena.enemy)=="table"
    if liveStage then
      P.battleArtConstantLastArena=arena
    else
