    end

    -- v1.2.5 Test3: DYNAMIC retains the accepted independent private timeline.
    -- CONTINUOUS no longer advances a second battle animation clock here; its
    -- private Actor is posed from the live Importer renderer immediately before
    -- the private Battle Art draw. If live metadata is transiently unavailable,
    -- hold the last exact pose until the next live sample rather than inventing
    -- private time.
    local constantExact=P.liveViewMode and P.liveViewMode() and P.constantArmed==true
    if not constantExact then
      local now=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
      local dt=P.battleArtImporterLastTime and (now-P.battleArtImporterLastTime) or 0.10
      P.battleArtImporterLastTime=now
      dt=math.max(0,math.min(0.20,tonumber(dt) or 0.10))
      if type(actor.update)=="function" then pcall(actor.update,actor,dt) end
    else
