  -- current identity and presentation-transition metadata; its live Actor is
  -- never submitted to Battle Art's private scene.
  P.battleArtImporterLivePresentation=function()
    local x=select(1,importerContext())
    local api=x and x.scene or nil
    if not (x and type(api)=="table" and type(api.current)=="function") then
      return false,nil,nil,nil
    end
    local okScene,scene=pcall(api.current)
    if not (okScene and type(scene)=="table") then return false,nil,nil,nil end
    local visual=nil
    if type(scene.visualState)=="function" then
      local okState,v=pcall(scene.visualState,scene,"player")
      if okState and v~=nil then visual=tostring(v) end
    end
    local liveActor=nil
    if type(api.actor)=="function" then
      local okActor,a=pcall(api.actor,"player",scene)
      if okActor and type(a)=="table" then liveActor=a end
    elseif type(scene.actors)=="table" and type(scene.actors.player)=="table" then
      liveActor=scene.actors.player
    end
    if visual==nil then return false,nil,liveActor,nil end
    -- `hidden` is a transient main-scene presentation decision, not vacancy.
    return true,(visual=="pokemon" or visual=="hidden"),liveActor,visual
  end

  -- v1.2.5 Test3: Battle Art exact live-presentation snapshot. The private
  -- Importer Actor remains BC-owned and scene-neutral, but its renderer is posed
  -- to the live main Actor's actual Stadium animation selection/time. This is
  -- the same-battle/two-camera contract proven on Dramaless Test2.
  P.syncBattleArtImporterExactAnimation=function(actor,liveActor)
    if not (type(actor)=="table" and type(liveActor)=="table") then return false end
    if not (P.liveViewMode and P.liveViewMode() and P.constantArmed==true) then return false end
    local liveR=liveActor.renderer
    local privateR=actor.renderer
    if not (type(liveR)=="table" and type(privateR)=="table") then return false end

    local anim=tonumber(liveR.animIndex)
    if not anim then return false end
    local loop=liveR.loop~=false
    local aux=tonumber(liveR.auxIndex)
    if privateR.animIndex~=anim or privateR.loop~=loop or privateR.auxIndex~=aux then
      local okSet=false
      if type(privateR.setAnimation)=="function" then
        local ok,value=pcall(privateR.setAnimation,privateR,anim,loop,aux)
        okSet=ok and value~=false
      elseif type(actor.playAnimation)=="function" then
        local ok,value=pcall(actor.playAnimation,actor,anim,loop,aux)
        okSet=ok and value~=false
      end
      if not okSet then return false end
    end

    local runtime={
      callbackFrame=math.floor(tonumber(liveActor.callbackFrame) or 0),
      frame=tonumber(liveR.frame) or 0,
      textureFrame=tonumber(liveR.frame) or 0,
      species=tonumber(liveActor.dex),
      dynamicObjectIndex=liveActor.dynamicObjectIndex,
      animationState=anim,
      animationFrame=tonumber(liveR.frame) or 0,
      dynamicObjectEnabled=true,
      dynamicObjectUpdateEnabled=true,
      modelAlphaByte=tonumber(liveActor.modelAlphaByte) or 255,
      dynamicObjectGastlyAlternate=liveActor.variant=="shiny",
    }
    if type(privateR.setHandlerRuntime)=="function" then
      pcall(privateR.setHandlerRuntime,privateR,runtime,true)
    end

    privateR.time=math.max(0,tonumber(liveR.time) or 0)
    privateR.displayTime=math.max(0,tonumber(liveR.displayTime) or privateR.time)
    privateR.frame=-1
    privateR.poseDT=0
    local okPose=true
    if type(privateR.updatePose)=="function" then
      okPose=pcall(privateR.updatePose,privateR,true)
    elseif type(actor.seekFrame)=="function" then
      okPose=pcall(actor.seekFrame,actor,tonumber(liveR.frame) or 0)
    end
    privateR.poseDT=nil
    if not okPose then return false end

    -- Copy live Actor-level presentation metadata. Actor:scale() will therefore
    -- reproduce Importer's real send-out grow without running a private timer.
    actor.callbackFrame=liveActor.callbackFrame
    actor.flash=math.max(0,tonumber(liveActor.flash) or 0)
    if type(liveActor.grow)=="table" then
      actor.grow={time=tonumber(liveActor.grow.time) or 0,
        duration=tonumber(liveActor.grow.duration) or .65}
    else
      actor.grow=nil
    end
    if liveActor.modelAlphaByte~=nil then actor.modelAlphaByte=liveActor.modelAlphaByte end
    if liveActor.dynamicObjectIndex~=nil then actor.dynamicObjectIndex=liveActor.dynamicObjectIndex end

    P.battleArtExactMirrored=true
    return true
  end

  P.syncBattleArtImporterPresentation=function(actor,liveActor)
    if not (type(actor)=="table" and type(liveActor)=="table") then return end
    P.battleArtExactMirrored=false

    -- CONTINUOUS: exact live renderer state is authoritative. Do not start a
    -- generic private attack/entrance/faint clip when this succeeds.
    if type(P.syncBattleArtImporterExactAnimation)=="function" then
      local ok,value=pcall(P.syncBattleArtImporterExactAnimation,actor,liveActor)
      if ok and value then
        P.battleArtSyncActor=actor
        P.battleArtSyncMon=actor.mon
        P.battleArtSyncLiveContext=tostring(liveActor.context or "idle")
        return
      end
    end

    -- Defensive fallback only: retain the exact accepted Test47 context-edge
    -- behavior if the current Importer renderer cannot expose a usable snapshot.
    local context=tostring(liveActor.context or "idle")
    local sameActor=(P.battleArtSyncActor==actor and P.battleArtSyncMon==actor.mon)
    local prior=sameActor and P.battleArtSyncLiveContext or nil
    if not sameActor then
      P.battleArtSyncActor=actor; P.battleArtSyncMon=actor.mon
      P.battleArtSyncLiveContext=nil; prior=nil
    end
    if context~=prior then
      P.battleArtSyncLiveContext=context
      if context=="faint" and type(actor.faint)=="function" then
        pcall(actor.faint,actor)
      elseif context=="entrance" and type(actor.entrance)=="function" then
        pcall(actor.entrance,actor)
      elseif (context=="attack" or context=="attack_default") and type(actor.play)=="function" then
        pcall(actor.play,actor,"attack",false)
      end
    end
    local flash=tonumber(liveActor.flash) or 0
    if flash>0 then actor.flash=math.max(tonumber(actor.flash) or 0,flash) end
    if type(liveActor.grow)=="table" then
      actor.grow={time=tonumber(liveActor.grow.time) or 0,
        duration=tonumber(liveActor.grow.duration) or .65}
    elseif context~="entrance" then actor.grow=nil end
    if liveActor.modelAlphaByte~=nil then actor.modelAlphaByte=liveActor.modelAlphaByte end
    if liveActor.dynamicObjectIndex~=nil then actor.dynamicObjectIndex=liveActor.dynamicObjectIndex end

    -- Because resolveBattleArtImporterActor intentionally does not advance a
    -- CONTINUOUS private clock in Test3, advance only in this fallback branch.
    if P.liveViewMode and P.liveViewMode() and P.constantArmed==true then
      local now=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
      local dt=P.battleArtImporterLastTime and (now-P.battleArtImporterLastTime) or 0.10
      P.battleArtImporterLastTime=now
      dt=math.max(0,math.min(0.20,tonumber(dt) or 0.10))
      if type(actor.update)=="function" then pcall(actor.update,actor,dt) end
    end
  end

  P.battleArtImporterBounds=function(actor)
    local renderer=actor and actor.renderer or nil
    if not (renderer and type(renderer.poseBounds)=="function"
        and type(renderer.worldMetrics)=="function") then return nil end
    local okB,b=pcall(renderer.poseBounds,renderer)
    local okM,m=pcall(renderer.worldMetrics,renderer)
    if not (okB and okM and type(b)=="table" and type(m)=="table") then return nil end
    local minX,maxX=tonumber(b.minX),tonumber(b.maxX)
    local minY,maxY=tonumber(b.minY),tonumber(b.maxY)
    local minZ,maxZ=tonumber(b.minZ),tonumber(b.maxZ)
    local modelH=tonumber(m.height)
    if not (minX and maxX and minY and maxY and minZ and maxZ
        and modelH and modelH>1e-4 and maxY>minY) then return nil end
    local worldH=math.max(5,math.min(18,14*math.sqrt(modelH/52.25)))
    local k=worldH/modelH
    local floor=tonumber(m.floor) or 0
    local hover=math.min(math.max(floor,0),modelH*0.5)
    local offset=floor-hover
    local bottom=(minY-offset)*k
    local top=(maxY-offset)*k
    local height=top-bottom
    if height<=1e-3 then return nil end
    local sx=math.max(0,(maxX-minX)*k)
    local sz=math.max(0,(maxZ-minZ)*k)
    local breadth=math.sqrt(sx*sx+sz*sz)
    local elevation=math.max(0,bottom)
    local elevationNorm=elevation/height
    if elevation<0.75 or elevationNorm<0.05 then elevation=0 end
    return {
      visualBottomY=bottom,visualTopY=top,centerY=(bottom+top)*0.5,height=height,
      breadth=breadth,spanX=sx,spanZ=sz,
      breadthHeightRatio=breadth/math.max(1e-3,height),
      elevation=elevation,elevationNorm=elevationNorm,
      source="STADIUM2_IMPORTER_BATTLE_ART_LOWER_LEVEL_POSED_V1",confidence="medium",
    }
  end


  -- Defensive fallback only: Test47 CONSTANT freezes the first valid POSED APB
  -- record per private actor identity (the Test45 rule). Bind/world bounds are
  -- used only when pose data is unavailable; DYNAMIC remains frame-posed.
  P.battleArtImporterStableBounds=function(actor)
    local renderer=actor and actor.renderer or nil
    if not (renderer and type(renderer.worldMetrics)=="function") then return nil end
    local okM,m=pcall(renderer.worldMetrics,renderer)
    local b=okM and type(m)=="table" and m.bounds or nil
    if not (type(b)=="table" and type(m)=="table") then return nil end
    local minX,maxX=tonumber(b.minX),tonumber(b.maxX)
    local minY,maxY=tonumber(b.minY),tonumber(b.maxY)
    local minZ,maxZ=tonumber(b.minZ),tonumber(b.maxZ)
    local modelH=tonumber(m.height)
    if not (minX and maxX and minY and maxY and minZ and maxZ
        and modelH and modelH>1e-4 and maxY>minY) then return nil end
    local worldH=math.max(5,math.min(18,14*math.sqrt(modelH/52.25)))
    local k=worldH/modelH
    local floor=tonumber(m.floor) or 0
    local hover=math.min(math.max(floor,0),modelH*0.5)
    local offset=floor-hover
    local bottom=(minY-offset)*k
    local top=(maxY-offset)*k
    local height=top-bottom
    if height<=1e-3 then return nil end
    local sx=math.max(0,(maxX-minX)*k)
    local sz=math.max(0,(maxZ-minZ)*k)
    local breadth=math.sqrt(sx*sx+sz*sz)
    local elevation=math.max(0,bottom)
    local elevationNorm=elevation/height
    if elevation<0.75 or elevationNorm<0.05 then elevation=0 end
    return {visualBottomY=bottom,visualTopY=top,centerY=(bottom+top)*0.5,height=height,
      breadth=breadth,spanX=sx,spanZ=sz,breadthHeightRatio=breadth/math.max(1e-3,height),
      elevation=elevation,elevationNorm=elevationNorm,
      source="STADIUM2_IMPORTER_BATTLE_ART_STABLE_FALLBACK_V1",confidence="medium"}
  end

  local function copyState(world,arena,vw,vh)
    local view={}
    for k,v in pairs(world) do view[k]=v end
    view.entities={}
    view.ghosts={}
    view.camera={x=(arena.mid[1] or 0)-vw/2,y=(arena.mid[2] or 0)-vh/2}
    return view
  end

  local function dims(img)
    if not img or type(img.getDimensions)~="function" then return nil,nil end
    local ok,w,h=pcall(img.getDimensions,img)
    if ok then return tonumber(w),tonumber(h) end
    return nil,nil
  end

  -- Test D19 / Battle Art Gen2 fixed-FRONT translation.
  -- D16 incorrectly called BattleState:pic(mon,false). Battle Art Gen2 wraps
  -- that method so an already-installed external Dynamic sprite wins regardless
  -- of the requested side; the PiP therefore followed main 4-Way facing.
  -- Resolve the FRONT from the same provider-owned source classes used by the
  -- accepted Rebase37 Battle Art adapter, never from the main battler sprite.
  local function gen2FixedFront(battle)
    if not isGen2 or type(battle)~="table" then return nil,"not Gen2" end
    local screen=battle.__battleArtGen2Screen
    if type(screen)~="table" then return nil,"Gen2 BattleState unavailable" end
    local shown=type(screen.shownMon)=="table" and screen.shownMon.player or nil
    local mon=shown
    if type(mon)~="table" and type(screen.activeMon)=="function" then
      local ok,m=pcall(screen.activeMon,screen,"player")
      if ok and type(m)=="table" then mon=m end
    end
    if type(mon)~="table" then
      local logic=type(battle.__battleArtGen2Logic)=="table" and battle.__battleArtGen2Logic or nil
      mon=(logic and logic.player) or battle.player
    end
    if type(mon)~="table" then return nil,"Gen2 player mon unavailable" end

    local species=type(BA.speciesFor)=="function" and BA.speciesFor(mon) or mon.species
    local art=BA.setting and type(BA.setting.get)=="function" and BA.setting:get() or "rom"

    if art=="static" and species and type(BA.image)=="function" then
      local ok,img=pcall(BA.image,species,"front",mon)
      if ok and img and type(img.getDimensions)=="function" then
        return img,"battle_art_gen2_static_front"
      end
    elseif art=="animated" and species and ABA
        and type(ABA.interfaceFront)=="function" then
      local generation=BA.frontAnimationSetting
        and type(BA.frontAnimationSetting.get)=="function"
        and BA.frontAnimationSetting:get() or "gen5"
      local displayMode=type(BA.displayMode)=="function" and BA.displayMode() or "pixel"
      local ok,frames,durations=pcall(ABA.interfaceFront,
        species,generation,displayMode,"bc_secondary_view_gen2")
      if ok and type(frames)=="table" and #frames>0 then
        local now=((love and love.timer and love.timer.getTime)
          and love.timer.getTime() or 0)
        local total=0
        for i=1,#frames do
          total=total+math.max(0.001,(tonumber(durations and durations[i]) or 100)/1000)
        end
        if total<=0 then return frames[1],"battle_art_gen2_animated_front" end
        local t=now%total
        for i=1,#frames do
          local d=math.max(0.001,(tonumber(durations and durations[i]) or 100)/1000)
          if t<d then return frames[i],"battle_art_gen2_animated_front" end
          t=t-d
        end
        return frames[#frames],"battle_art_gen2_animated_front"
      end
    end

    -- ROM/MODDED: Gen2BattleAdapter deliberately stores the engine/provider
    -- resolver before Battle Art wraps BattleState:pic. Calling this stored
    -- method bypasses only Battle Art's current external Dynamic sprite, while
    -- retaining the underlying ROM/other-provider FRONT selection.
    local native=screen.battleArtGen2NativePic
    if type(native)=="function" then
      local ok,img=pcall(native,screen,mon,false)
      if ok and img and type(img.getDimensions)=="function" then
        return img,"battle_art_gen2_native_front"
      end
    end
    return nil,"Gen2 fixed FRONT source unavailable"
  end

  P.renderBattleArtFrame=function()
    if not P.battleArtEligible() then P.shot=nil; return end
    local battle=state.battle
    local constantLive=P.persistentMode and P.persistentMode() and P.constantArmed==true
    if P.battleArtConstantBattle~=battle then
      P.battleArtConstantBattle=battle
      P.battleArtConstantLastPresence=nil
      P.battleArtConstantLastArena=nil
      P.battleArtStableBounds=nil; P.battleArtStableBoundsMon=nil
      P.battleArtSyncActor=nil; P.battleArtSyncMon=nil; P.battleArtSyncLiveContext=nil
    end
    local arena=OW.arena()
    if type(arena)=="table" and type(arena.player)=="table" and type(arena.enemy)=="table" then
      P.battleArtConstantLastArena=arena
    elseif constantLive and P.battleArtImporterEnabled()
        and type(P.battleArtConstantLastArena)=="table" then
      arena=P.battleArtConstantLastArena
    end
    local world=nil
    if isGen2 and type(V.game)=="function" then
      local okGame,game=pcall(V.game)
      if okGame and type(game)=="table" then world=game.overworld or game.world end
    else
      local GameModule=select(2,pcall(require,"src.core.Game"))
      world=type(GameModule)=="table" and GameModule.overworld or nil
    end
    if not (world and world.map and world.player) then
      P.shot=nil; P.failure="Battle Art read-only world unavailable"; return
    end
    if arena.map and arena.map~=world.map then
      P.shot=nil; P.failure="Battle Art Rebase38 cross-floor arena deferred"; return
    end

    -- Resolve actor CLASS before the camera. DYNAMIC preserves Rebase38.
    -- CONSTANT + Importer follows the live visible slot as metadata while BC
    -- keeps the same independent Battle Art private presentation Actor.
    local importerActor=nil
    local vacant=false
    local liveKnown,livePresent,liveActor,liveVisual=false,nil,nil,nil
    if constantLive and P.battleArtImporterEnabled()
        and type(P.battleArtImporterLivePresentation)=="function" then
      P.battleArtImporterRequested=true
      liveKnown,livePresent,liveActor,liveVisual=P.battleArtImporterLivePresentation()
      if liveKnown then P.battleArtConstantLastPresence=livePresent end
      local effectivePresent=liveKnown and livePresent or P.battleArtConstantLastPresence
      if effectivePresent==false then
        vacant=true
      else
        local liveMon=type(liveActor)=="table" and liveActor.mon or nil
        importerActor=P.resolveBattleArtImporterActor(battle,liveMon)

        -- v1.2.5 Test11: the PIP MODE presentation driver must not choose a
        -- different Battle Art portrait camera. Test10 exposed a real divergence:
        -- LIVE VIEW exact-synced the private Importer actor *before* the persistent
        -- camera snapshot was frozen, while DYNAMIC / LIVING PORTRAIT described
        -- the independently posed private actor. For Mew this could freeze a very
        -- different APB pose and leave the PiP as an extreme head/crop view.
        --
        -- Seed the persistent Battle Art camera from the same neutral private
        -- portrait actor BEFORE any mode-specific live presentation sync. LIVE VIEW
        -- receives one invisible 0.10 s private pose step only for this camera
        -- measurement; the exact live renderer snapshot immediately replaces that
        -- pose for drawing. LIVING PORTRAIT has already advanced naturally in
        -- resolveBattleArtImporterActor. DYNAMIC remains completely untouched.
        if importerActor and constantLive
            and (P.battleArtStableBoundsMon~=importerActor.mon
              or type(P.battleArtStableBounds)~="table") then
          if P.liveViewMode and P.liveViewMode()
              and type(importerActor.update)=="function" then
            pcall(importerActor.update,importerActor,0.10)
          end
          P.battleArtStableBounds=(type(P.battleArtImporterBounds)=="function"
              and P.battleArtImporterBounds(importerActor) or nil)
            or (type(P.battleArtImporterStableBounds)=="function"
              and P.battleArtImporterStableBounds(importerActor) or nil)
          P.battleArtStableBoundsMon=importerActor.mon
        end

        if importerActor and liveActor and type(P.syncBattleArtImporterPresentation)=="function" then
          pcall(P.syncBattleArtImporterPresentation,importerActor,liveActor)
        end
      end
    else
      importerActor=P.resolveBattleArtImporterActor(battle)
    end
    if P.battleArtImporterRequested and not importerActor and not vacant then
      P.shot=nil
      P.failure="Battle Art + Importer 3D actor unavailable: "..tostring(P.battleArtImporterFailure or "unknown")
      return
    end
    local actorMode=vacant and "empty_3d" or (importerActor and "stadium2_importer" or "battle_art_2d")

    local img,source=nil,nil
    if not importerActor and not vacant then
      local fixedFront=isGen2 and gen2FixedFront
        or state.secondaryViewProbe.battleArtFixedFront
      if type(fixedFront)~="function" then
        P.shot=nil; P.failure="Battle Art fixed-FRONT seam unavailable"; return
      end
      local okImg,value,src=pcall(fixedFront,battle)
      if not (okImg and value) then
        P.shot=nil; P.failure="Battle Art fixed-FRONT unavailable: "..tostring(src or value); return
      end
      img,source=value,src
    elseif importerActor then
      source=constantLive and ("stadium2_importer_private_"..tostring(liveVisual or "live"))
        or "stadium2_importer_actor"
    else
      source="constant_empty_player"
    end

    local px,pz=tonumber(arena.player[1]),tonumber(arena.player[2])
    local exx,ezz=tonumber(arena.enemy and arena.enemy[1]),tonumber(arena.enemy and arena.enemy[2])
    if not (px and pz and exx and ezz) then P.shot=nil; P.failure="Battle Art arena actors unavailable"; return end
    local map=world.map
    local cx,cz=math.floor(px/16),math.floor(pz/16)
    local okGY,groundY=pcall(VS.groundAt,map,cx,cz)
    groundY=(okGY and tonumber(groundY)) or 0

    local oldBounds=P._goldImporterBounds
    local oldStable=P._constantStableImporterBounds
    if importerActor then
      P._goldImporterBounds=P.battleArtImporterBounds(importerActor)
      if constantLive then
        if P.battleArtStableBoundsMon~=importerActor.mon or type(P.battleArtStableBounds)~="table" then
          -- Fallback only. Test11 normally seeds this before mode-specific
          -- presentation sync so LIVE VIEW / LIVING PORTRAIT share one neutral
          -- Battle Art portrait-camera contract rather than freezing different
          -- animation poses.
          P.battleArtStableBounds=P._goldImporterBounds
            or (type(P.battleArtImporterStableBounds)=="function"
              and P.battleArtImporterStableBounds(importerActor) or nil)
          P.battleArtStableBoundsMon=importerActor.mon
        end
        P._constantStableImporterBounds=P.battleArtStableBounds
      end
    elseif constantLive and vacant and type(P.battleArtStableBounds)=="table" then
      -- Empty side remains the SAME monitor composition. Keep the last loaded
      -- actor's semantic frame only as camera geometry; no actor is rendered.
      P._constantStableImporterBounds=P.battleArtStableBounds
    end
    local cameraActorMode=(constantLive and vacant and P.battleArtImporterRequested)
      and "stadium2_importer" or actorMode
    local cam,pitch=P.cameraFor(backend,arena,groundY,cameraActorMode)
    P._goldImporterBounds=oldBounds
    P._constantStableImporterBounds=oldStable
    if not cam then P.shot=nil; P.failure="Battle Art portrait camera unavailable"; return end

    local terrain,nbMesh,water,nbWater,ready=VS.prefetch(world)
    -- Battle Art Gen2 2.0.8 returns four values from VoxelScene.prefetch; the
    -- terrain object itself is the readiness signal. The older Gen1 fork also
    -- returned a fifth boolean. D16 treated Gen2's missing fifth value as false
    -- and rejected a valid terrain mesh every frame.
    local terrainReady=isGen2 and (terrain~=nil) or (ready and terrain~=nil)
    if not terrainReady then
      P.shot=nil; P.failure="Battle Art lower-level terrain not ready"; return
    end

    -- Test14 resolution proof: separate internal render quality from PIP SIZE.
    -- Battle Art is the first target because its private world has an explicit
    -- stable 16:9 render contract. PIP SIZE still controls only compositor size.
    local rw,rh=P.renderResolution()
    local vw,vh=160,90
    local viewState=copyState(world,arena,vw,vh)
    P.battleArtViewState=viewState

    local function atlasFor(m)
      local colors=type(VS._modeColors)=="function" and VS._modeColors(nil,m) or nil
      return TA.forMap(m,colors)
    end

    local g=love and love.graphics or nil
    if not g then P.shot=nil; P.failure="Battle Art graphics unavailable"; return end
    local unpack_=table.unpack or unpack
    local prevCanvas={}
    if type(g.getCanvas)=="function" then prevCanvas={g.getCanvas()} end
    local prevShader=type(g.getShader)=="function" and g.getShader() or nil
    local br,ba=type(g.getBlendMode)=="function" and g.getBlendMode() or "alpha",nil
    if type(g.getBlendMode)=="function" then br,ba=g.getBlendMode() end
    local cr,cg,cb,ca=1,1,1,1
    if type(g.getColor)=="function" then cr,cg,cb,ca=g.getColor() end
    local dm,dw=nil,nil
    if type(g.getDepthMode)=="function" then dm,dw=g.getDepthMode() end
    local cull=type(g.getMeshCullMode)=="function" and g.getMeshCullMode() or nil

    local oldCamera=V3.camera
    local oldTint=V3.tint
    local oldGlassMask,oldGlassNight=V3.glassMask,V3.glassNight
    local oldGlassPhase,oldGlassGlint=V3.glassPhase,V3.glassGlint
    local oldShadowAlpha=V3.SHADOW_ALPHA
    local canvas=nil
    local actorDrawn=vacant and true or false

    local okRender,errRender=pcall(function()
      V3.camera=cam
      local sky=type(VS.skyColor)=="function" and VS.skyColor(map,1) or nil
      if not V3.beginScene(rw,rh,arena.mid[1],arena.mid[2],vw,vh,sky,
          "bc_secondary_battle_art_world") then
        error("beginScene declined",0)
      end
      V3.draw(terrain,atlasFor(map),nil)
      for i,nb in ipairs(world.neighbors or {}) do
        local mesh=nbMesh and nbMesh[i] or nil
        if mesh and nb and nb.map then
          V3.draw(mesh,atlasFor(nb.map),M4.translate(nb.ox or 0,0,nb.oy or 0))
        end
      end
      if water then V3.draw(water,atlasFor(map),nil) end
      for i,nb in ipairs(world.neighbors or {}) do
        local mesh=nbWater and nbWater[i] or nil
        if mesh and nb and nb.map then
          V3.draw(mesh,atlasFor(nb.map),M4.translate(nb.ox or 0,0,nb.oy or 0))
        end
      end

      if vacant then
        -- Genuine player-slot vacancy: keep the Battle Art world and monitor
        -- camera live, but submit no stale private actor until Importer reports
        -- a replacement identity.
      elseif importerActor then
        local renderer=importerActor.renderer
        if not (renderer and type(renderer.worldMetrics)=="function"
            and type(renderer.drawScene)=="function") then
          error("Importer actor renderer unavailable",0)
        end
        local okM,metrics=pcall(renderer.worldMetrics,renderer)
        local height=okM and metrics and tonumber(metrics.height) or nil
        if not (height and height>1e-4) then error("Importer actor metrics unavailable",0) end

        local okIR,IR=pcall(require,"mods.STADIUM2_IMPORTER.lib.renderer")
        if not (okIR and type(IR)=="table" and type(IR.matMul)=="function"
            and type(IR.lookAt)=="function" and type(IR.normalMatrix)=="function") then
          error("Importer shared-scene renderer API unavailable",0)
        end

        -- Exact Importer classic presentation scale/hover, but placed at the
        -- Battle Art voxel arena's player anchor and facing its enemy anchor.
        local worldH=math.max(5,math.min(18,14*math.sqrt(height/52.25)))
        local grow=type(importerActor.scale)=="function" and importerActor:scale() or 1
        grow=math.max(0,math.min(1,tonumber(grow) or 1))
        local k=worldH/height*grow
        local floor=tonumber(metrics.floor) or 0
        local hover=math.min(math.max(floor,0),height*0.5)
        local yaw=math.atan2(exx-px,ezz-pz)
        local model=M4.mul(M4.translate(px,groundY,pz),
          M4.mul(M4.rotateY(yaw),
            M4.mul(M4.scale(k,k,k),M4.translate(0,-(floor-hover),0))))
        local viewMatrix=IR.lookAt(cam.eye[1],cam.eye[2],cam.eye[3],
          cam.focus[1],cam.focus[2],cam.focus[3])
        local tint=V3.tint or {1,1,1}
