  local function backdropFor(arena)
    local id=tostring(type(arena)=="table" and (arena._cbeArenaId or arena.selectedArena or arena.profile) or "")
    if BACKDROPS[id] then return BACKDROPS[id],id end
    local profileId=BACKDROP_PROFILE_IDS[id]
    if profileId then return BACKDROPS[profileId],profileId end
    if id:find("summit",1,true) or id:find("mt_battle",1,true) then return BACKDROPS.mt_battle_summit,"mt_battle_summit" end
