      setColor(g,p.accent,0.35);g.ellipse("line",rw*.50+drift*.10,rh*.92,rw*.42,rh*.20)
    elseif p.kind=="summit" then
      setColor(g,{0.19,0.12,0.11})
      g.polygon("fill",-20+drift,horizon+12, rw*.12+drift,horizon-15, rw*.24+drift,horizon+8,
        rw*.40+drift,horizon-28, rw*.56+drift,horizon+5, rw*.73+drift,horizon-18,
        rw*.90+drift,horizon+9, rw+30+drift,horizon-22, rw+30,horizon+35,-20,horizon+35)
      gradient(g,0,horizon,rw,rh-horizon,{0.80,0.20,0.025},{0.24,0.035,0.012},8)
      setColor(g,p.groundTop);g.polygon("fill",rw*.08+drift*.18,rh, rw*.25+drift*.08,horizon+20,
        rw*.78+drift*.08,horizon+20,rw*.96+drift*.18,rh)
      setColor(g,{0.18,0.18,0.18});g.rectangle("fill",rw*.18,horizon+15,rw*.64,5)
      for i=0,7 do
        if i%2==0 then setColor(g,{0.92,0.66,0.08}) else setColor(g,{0.09,0.09,0.09}) end
        g.polygon("fill",rw*.18+i*rw*.08,horizon+15,rw*.23+i*rw*.08,horizon+15,
          rw*.20+i*rw*.08,horizon+20,rw*.15+i*rw*.08,horizon+20)
      end
    elseif p.kind=="wild" then
      gradient(g,0,horizon,rw,rh-horizon,p.groundTop,p.groundBottom,8)
      setColor(g,{0.13,0.25,0.11});g.polygon("fill",0,horizon+15,rw*.18+drift*.25,horizon-2,
        rw*.34+drift*.20,horizon+11,rw*.54+drift*.12,horizon-7,rw*.72+drift*.18,horizon+13,
        rw,horizon-1,rw,rh,0,rh)
      for i=0,7 do
        local x=((i*47+21+drift*(0.42+(i%3)*0.12))%(rw+60))-30
        local y=horizon+4+(i%2)*5
        setColor(g,{0.12,0.075,0.035});g.rectangle("fill",x-2,y-13,4,17)
        setColor(g,{0.05,0.23+0.025*(i%3),0.07});g.ellipse("fill",x,y-15,9+(i%2)*3,7+(i%3))
      end
      setColor(g,p.accent,0.65);g.ellipse("line",rw*.50+drift*.12,rh*.90,rw*.43,rh*.21)
    elseif p.kind=="water" then
