      end
      setColor(g,{0.53,0.57,0.60});g.ellipse("fill",rw*.50+drift*.10,rh*.88,rw*.38,rh*.18)
      setColor(g,p.accent,0.75);g.ellipse("line",rw*.50+drift*.10,rh*.88,rw*.38,rh*.18)
    else
      gradient(g,0,horizon,rw,rh-horizon,p.groundTop,p.groundBottom,8)
      setColor(g,{0.18,0.20,0.24});g.rectangle("fill",0,horizon-3,rw,18)
      setColor(g,{0.55,0.58,0.60});g.rectangle("fill",0,horizon-2,rw,3)
      for i=0,12 do
        local x=i*rw/12+drift*.36
        setColor(g,(i%2==0) and p.accent or {0.80,0.34,0.22},0.72)
        g.rectangle("fill",x,horizon+2,3,5+(i%3))
      end
      if p.kind=="tech" then
        setColor(g,p.accent,0.32)
        g.line(rw*.18+drift*.18,horizon+16,rw*.10,rh)
        g.line(rw*.82+drift*.18,horizon+16,rw*.90,rh)
      end
      setColor(g,p.accent,0.55);g.ellipse("line",rw*.50+drift*.10,rh*.91,rw*.42,rh*.20)
    end

    -- Shared perspective cues bind the card to the moving camera. Keep them
    -- subtle so the Pokemon, not the backdrop, remains the PiP subject.
    local vanishX=rw*.50+sideBias+drift*.34
    setColor(g,{1,1,1},0.10)
    for i=0,6 do
      local x=rw*i/6
      g.line(x,rh,vanishX,horizon+8)
    end
    for i=1,4 do
      local q=(i/5)^1.7
      local y=horizon+8+(rh-horizon-8)*q
      g.line(0,y,rw,y)
    end
    g.setColor(1,1,1,1)
  end

  local TWO_PI=math.pi*2
  local function sat(v) return math.max(0,math.min(1,tonumber(v) or 0)) end
  local function currentStageArena()
    local C=backends and backends.__cbe
    return C and C.currentArena or nil
  end


  -- Test51: exact Terrarium 1.7.1 + RC 1.7.2 integrated-CBE DATA-ONLY Secondary View.
  -- Tests45/46 proved that the real arena is obtainable but that loading or
  -- re-entering Terrarium's Arena renderer can disturb the proven main frame.
  -- This path therefore calls ZERO Terrarium Arena draw/update/helper methods
  -- and performs ZERO debug.setupvalue writes. It reads only the already-live
  -- scene table / transforms / baked backdrop through Arena.status upvalues,
  -- then submits the resident Mesh objects into BC's own bounded framebuffer
  -- using a tiny BC-owned shader. Meshes/textures are treated as immutable.
  local T47={}
  T47.VERTEX=[[
    uniform mat4 bcVP;
    uniform mat4 bcModel;
    attribute vec4 VertexTint;
    varying vec4 bcTint;
    vec4 position(mat4 transform_projection, vec4 vertex_position) {
      bcTint=VertexTint;
      return bcVP*bcModel*vertex_position;
    }
  ]]
  T47.PIXEL=[[
    varying vec4 bcTint;
    uniform float bcAlphaCut;
    vec4 effect(vec4 color, Image tex, vec2 uv, vec2 sc) {
      vec4 c=Texel(tex,uv)*bcTint*color;
      if (c.a < bcAlphaCut) discard;
      return c;
    }
  ]]
  T47.adler=function(source)
    if type(source)~="string" then return nil end
    local a,b=1,0
    for i=1,#source do a=(a+source:byte(i))%65521;b=(b+a)%65521 end
    return b*65536+a
  end
  T47.up=function(fn,name)
    if type(fn)~="function" or not (debug and type(debug.getupvalue)=="function") then return nil,false end
    for i=1,96 do
      local ok,n,v=pcall(debug.getupvalue,fn,i)
      if not ok or n==nil then break end
      if n==name then return v,true end
    end
    return nil,false
  end
  T47.handle=function()
    local X=state and state.terrariumCbeCameraAuthorityTest15
    local C=backends and backends.__cbe
    local h=(type(X)=="table" and X.handle) or (C and C.handle)
    if type(h)~="table" or tostring(h.id or "")~="DRAMATIC_SHAPE" then
      return nil,"Terrarium DRAMATIC_SHAPE handle unavailable"
    end
    local ex=type(h.exports)=="table" and h.exports or nil
    if not (ex and type(ex.status)=="function" and type(ex.lib)=="table"
        and type(ex.lib.mod)=="table" and type(ex.lib.mod.read)=="function") then
      return nil,"Terrarium resident export surface unavailable"
    end
    return h,ex
  end
  -- RC 1.7.2's manifest currently reports 1.6.5, so version labels cannot be
  -- the admission contract. Recognise only the two exact audited Arena.lua
  -- sources instead. This keeps 1.7.1 frozen while admitting the RC narrowly.
  T47.recognize=function()
    local h,ex=T47.handle();if not h then return nil,ex end
    local probe=P.terrariumDataProviderProbe
    if type(probe)=="table" and probe.statusFn==ex.status then
      if probe.variant then return h,ex,probe.variant end
      return nil,probe.reason or "Terrarium provider source unrecognised"
    end
    local okSource,source=pcall(ex.lib.mod.read,ex.lib.mod,"lib/Arena.lua")
    local variant=nil
    if okSource and type(source)=="string" then
      local n,sum=#source,T47.adler(source)
      if n==183593 and sum==3341154622 then variant="1.7.1"
      elseif n==192973 and sum==2668570538 then variant="RC-1.7.2"
      elseif n==193400 and sum==2473769452 then variant="1.7.4" end
    end
    local reason=variant and nil or "Terrarium Arena.lua exact-source fingerprint mismatch"
    P.terrariumDataProviderProbe={statusFn=ex.status,variant=variant,reason=reason}
    if not variant then return nil,reason end
    return h,ex,variant
  end
  T47.build=function()
    local h,ex,variant=T47.recognize();if not h then return nil,ex end
    local cached=P.terrariumDataArena
    if type(cached)=="table" and cached.statusFn==ex.status and cached.providerVariant==variant then return cached end
    P.terrariumDataArena=nil
    local Arena,okArena=T47.up(ex.status,"Arena")
    if not (okArena and type(Arena)=="table" and type(Arena.status)=="function") then
      return nil,"resident Terrarium Arena status closure unavailable"
    end
    -- Test52 LIVE VIEW: CurrentSpriteModels is read-only provider truth for the
    -- actor that CBE itself just rendered.  Both admitted Terrarium sources keep
    -- this exact status-closure upvalue.  We never call its lifecycle methods or
    -- mutate its actor/session tables; the pointer is used only to sample the
    -- already-live player actor and its last rendered world matrix.
    local Models,okModels=T47.up(ex.status,"CurrentSpriteModels")
    local api={statusFn=ex.status,Arena=Arena,status=Arena.status,shader=nil,providerVariant=variant,
      models=(okModels and type(Models)=="table") and Models or nil,
      actorService=(type(ex.pokemonActorsOverworld)=="table") and ex.pokemonActorsOverworld or nil,
      overworldSnapshot=(type(ex.lib.ArenaOverworldSnapshot)=="table") and ex.lib.ArenaOverworldSnapshot or nil,
      voxel3d=(type(ex.lib.Voxel3D)=="table") and ex.lib.Voxel3D or nil}
    P.terrariumDataArena=api
    return api
  end

  T47.livePlayer=function()
    local api,why=T47.build();if not api then return nil,nil,nil,why end
    local models=api.models
    local rec=type(models)=="table" and type(models.stadiumActors)=="table" and models.stadiumActors.player or nil
    local actor=type(rec)=="table" and rec.actor or nil
    local service=api.actorService
    if not (type(actor)=="table" and type(actor.draw)=="function" and type(actor.worldMatrix)=="table") then
      return nil,nil,nil,"resident CBE player actor not yet rendered"
    end
    if not (type(service)=="table" and service.portable==true and type(service.withRenderer)=="function") then
      return nil,nil,nil,"resident CBE actor service is not explicitly portable"
    end
    return actor,service,rec,nil
  end
  T47.snapshot=function(api,arena)
    local fn=api and api.status
    local scene,okScene=T47.up(fn,"scene")
    local def,okDef=T47.up(fn,"activeDef")
    local arenaId,okId=T47.up(fn,"activeArenaId")
    local stageScale,okScale=T47.up(fn,"STAGE_SCALE")
    local stageYaw,okYaw=T47.up(fn,"STAGE_YAW")
    local figureScale,okFigure=T47.up(fn,"figureScale")
    local backdrop,okBackdrop=T47.up(fn,"backdropCanvas")
    if not (okScene and okDef and okId and okScale and okYaw and okFigure
        and type(scene)=="table" and type(def)=="table") then
      return nil,"resident arena data is not ready"
    end
    local liveOverworld=def.liveOverworld==true
    if liveOverworld and not (type(api.overworldSnapshot)=="table"
        and type(api.overworldSnapshot.draw)=="function"
        and type(api.voxel3d)=="table") then
      return nil,"Terrarium OVERWORLD arena snapshot renderer unavailable"
    end
    if type(arena)~="table" or arena._cbeArenaId~=arenaId
        or ((not liveOverworld) and arena.cachePath~=def.cache) then
      return nil,"resident arena identity mismatch"
    end
    stageScale=tonumber(stageScale);stageYaw=tonumber(stageYaw);figureScale=tonumber(figureScale)
    if not (stageScale and stageScale>0 and stageYaw and figureScale and figureScale>0) then
      return nil,"resident arena transform invalid"
    end
    return {scene=scene,def=def,arenaId=arenaId,stageScale=stageScale,stageYaw=stageYaw,
      figureScale=figureScale,backdrop=okBackdrop and backdrop or nil,
      liveOverworld=liveOverworld,overworldSnapshot=liveOverworld and api.overworldSnapshot or nil}
  end
  T47.ensureShader=function(api)
    if api.shader then return api.shader end
    local g=love and love.graphics
    if not (g and type(g.newShader)=="function") then return nil,"shader API unavailable" end
    local ok,sh=pcall(g.newShader,T47.VERTEX,T47.PIXEL)
    if not ok or not sh then return nil,"BC data-only arena shader unavailable: "..tostring(sh) end
    api.shader=sh
    return sh
  end
  T47.release=function()
    local api=P.terrariumDataArena
    if type(api)=="table" and api.shader and type(api.shader.release)=="function" then
      pcall(api.shader.release,api.shader)
    end
    P.terrariumDataArena=nil
    return true
  end
  T47.requested=function()
    local h=T47.recognize()
    return h~=nil
  end
  T47.model=function(scale,yaw)
    local c,s=math.cos(yaw),math.sin(yaw)
    return {c*scale,0,s*scale,0, 0,scale,0,0, -s*scale,0,c*scale,0, 0,0,0,1}
  end
  T47.layout=function(snap,request)
    local arena,cam=request.arena,request.camera
    local function finite(v)return type(v)=="number" and v==v and v>-math.huge and v<math.huge end
    local function point(v)return type(v)=="table" and finite(v[1]) and finite(v[2]) and finite(v[3]) end
    if not (type(cam)=="table" and point(cam.eye) and point(cam.focus)
        and finite(cam.fov) and cam.fov>0 and cam.fov<math.pi) then return nil,"invalid secondary camera" end
    local player=arena.visualPlayer or arena.player
    local enemy=arena.visualEnemy or arena.enemy
    local px,pz=type(player)=="table" and tonumber(player[1]) or nil,type(player)=="table" and tonumber(player[2]) or nil
    local ex,ez=type(enemy)=="table" and tonumber(enemy[1]) or nil,type(enemy)=="table" and tonumber(enemy[2]) or nil
    local k=snap.figureScale
    if not (px and pz and ex and ez and k and k>0) then return nil,"invalid resident stage anchors" end
    local dx,dz=ex-px,ez-pz;local length=math.sqrt(dx*dx+dz*dz)
    if length<1e-6 then return nil,"degenerate resident battler axis" end
    local sn,cs=dx/length,dz/length
    local ground=tonumber(request.groundY) or 0
    local frame={cs*k,0,sn*k,px, 0,k,0,ground, -sn*k,0,cs*k,pz, 0,0,0,1}
    local function world(v)return {px+k*(cs*v[1]+sn*v[3]),ground+k*v[2],pz+k*(-sn*v[1]+cs*v[3])} end
    return {frame=frame,pose={eye=world(cam.eye),focus=world(cam.focus),up={0,1,0},fov=cam.fov,curve=0}}
  end
  T47.drawBase=function(g,w,h,arena,backdrop)
    g.setShader();if g.setDepthMode then g.setDepthMode() end
    g.setBlendMode("alpha","alphamultiply");g.setColor(1,1,1,1)
    if backdrop and type(backdrop.getWidth)=="function" and type(backdrop.getHeight)=="function" then
      local okW,bw=pcall(backdrop.getWidth,backdrop);local okH,bh=pcall(backdrop.getHeight,backdrop)
      if okW and okH and tonumber(bw) and tonumber(bh) and bw>0 and bh>0 then
        g.draw(backdrop,0,0,0,w/bw,h/bh);return
      end
    end
    -- Exact resident baked sky is preferred above. This fallback is only an
    -- unadorned profile gradient: no cyber-grid, fake landmarks or perspective
    -- card. The real 3D scene geometry is drawn immediately afterwards.
    local profile=backdropFor(arena)
    profile=type(profile)=="table" and profile or BACKDROPS.water
    local horizon=math.floor(h*.54)
    gradient(g,0,0,w,horizon,profile.skyTop,profile.skyBottom,10)
    gradient(g,0,horizon,w,h-horizon,profile.groundTop,profile.groundBottom,8)
  end
  T47.materialColor=function(row)
    local d=type(row)=="table" and row.diffuse or nil
    if type(d)~="table" then return 1,1,1 end
    return math.max(.12,tonumber(d[1]) or 1),math.max(.12,tonumber(d[2]) or 1),math.max(.12,tonumber(d[3]) or 1)
  end
  T47.drawGroup=function(g,shader,row,cut)
    if type(row)~="table" or not row.mesh then return end
    local r,gg,b=T47.materialColor(row)
    local a=math.max(0,math.min(1,tonumber(row.alpha) or 1))
    g.setColor(r,gg,b,a)
    pcall(shader.send,shader,"bcAlphaCut",tonumber(cut) or .01)
    g.draw(row.mesh)
  end
  T47.drawBucket=function(g,shader,rows,cut)
    for i=1,#(rows or {}) do T47.drawGroup(g,shader,rows[i],cut) end
  end
  T47.worldCenter=function(row,scale,yaw)
    local c=type(row)=="table" and row.center or nil
    local x,y,z=type(c)=="table" and tonumber(c[1]) or 0,type(c)=="table" and tonumber(c[2]) or 0,type(c)=="table" and tonumber(c[3]) or 0
    x,y,z=x*scale,y*scale,z*scale
    local cs,sn=math.cos(yaw),math.sin(yaw)
    return cs*x+sn*z,y,-sn*x+cs*z
  end
  T47.sorted=function(rows,eye,scale,yaw)
    local out={}
    local ex,ey,ez=eye[1] or 0,eye[2] or 0,eye[3] or 0
    for i,row in ipairs(rows or {}) do
      local x,y,z=T47.worldCenter(row,scale,yaw);local dx,dy,dz=x-ex,y-ey,z-ez
      out[i]={row=row,d=dx*dx+dy*dy+dz*dz}
    end
    table.sort(out,function(a,b)return a.d>b.d end)
    return out
  end
  T47.draw=function(request,actor,service)
    local api,why=T47.build();if not api then return false,why end
    local snap,snapWhy=T47.snapshot(api,request.arena);if not snap then return false,snapWhy end
    local plan,planWhy=T47.layout(snap,request);if not plan then return false,planWhy end
    local shader,shaderWhy=nil,nil
    if not snap.liveOverworld then
      shader,shaderWhy=T47.ensureShader(api);if not shader then return false,shaderWhy end
    end
    local g=love and love.graphics
    if not (g and type(g.push)=="function" and type(g.pop)=="function" and type(g.getCanvas)=="function"
        and type(service)=="table" and type(service.withRenderer)=="function"
        and type(actor)=="table" and type(actor.draw)=="function" and type(actor.matrix)=="function") then
      return false,"data-only arena draw prerequisites unavailable"
    end
    local w,h=request.width,request.height
    local prior={g.getCanvas()};local pushed=false;local detail
    local ok,err=pcall(function()
      g.push("all");pushed=true
      if g.origin then g.origin() end;if g.setScissor then g.setScissor() end
      local bound,hasDepth=request.bind()
      if not bound or not hasDepth then error("data-only arena PiP requires depth target",0) end
      g.clear(0,0,0,1,true,true)
      T47.drawBase(g,w,h,request.arena,snap.backdrop)
      local view=lookAt(plan.pose.eye[1],plan.pose.eye[2],plan.pose.eye[3],plan.pose.focus[1],plan.pose.focus[2],plan.pose.focus[3])
      local projection=matMul(LOVE_CANVAS_Y,perspective(plan.pose.fov,w/math.max(1,h),.1,1000))
      local vp=matMul(projection,view)
      local model=T47.model(snap.stageScale,snap.stageYaw)
      if snap.liveOverworld then
        -- RC's OVERWORLD arena is not an HSD scene: ArenaOverworldSnapshot is
        -- the provider's renderer for the cached live voxel FIELD. Its draw()
        -- deliberately uses Voxel3D slot "current", meaning it renders into the
        -- framebuffer BC has already bound, and restores Voxel3D.camera itself.
        -- We never call Arena.render/update/acquire or alter gameplay state.
        local okField,fieldResult=pcall(snap.overworldSnapshot.draw,w,h,plan.pose)
        if not okField or fieldResult~=true then
          error("Terrarium OVERWORLD PiP field draw failed: "..tostring(fieldResult),0)
        end
        if not (api.voxel3d and type(api.voxel3d.vp)=="table") then
          error("Terrarium OVERWORLD PiP VP unavailable",0)
        end
        vp=api.voxel3d.vp
      else
        g.setShader(shader);pcall(shader.send,shader,"bcVP","row",vp);pcall(shader.send,shader,"bcModel","row",model)
        if g.setMeshCullMode then g.setMeshCullMode("none") end
        g.setBlendMode("alpha","alphamultiply");g.setDepthMode("lequal",true)
        T47.drawBucket(g,shader,snap.scene.opaque,.01)
        T47.drawBucket(g,shader,snap.scene.cutout,.40)
        T47.drawBucket(g,shader,snap.scene.crowd,.10)
      end
      -- Test52 LIVE VIEW may draw the provider's already-live actor pose without
      -- advancing or re-triggering it. PokemonActors explicitly publishes the
      -- service as portable and Actor:draw consumes a caller-supplied matrix;
      -- therefore the alternate camera can reuse the resident pose while CBE
      -- remains the sole owner of attack/hit/faint timing. Non-LIVE modes retain
      -- the established independent portable actor and authored portrait matrix.
      g.setShader();g.setColor(1,1,1,1);g.setBlendMode("alpha","alphamultiply");g.setDepthMode("lequal",true)
      local actorVP=vp
      local drawMatrix=nil
      if type(request.liveMatrix)=="table" then
        local k=math.max(.001,tonumber(snap.figureScale) or 1)
        actorVP=matMul(vp,{k,0,0,0, 0,k,0,0, 0,0,k,0, 0,0,0,1})
        drawMatrix=request.liveMatrix
      else
        drawMatrix=matMul(plan.frame,actor:matrix(0,0,0,0,1))
      end
      local called,value,actorWhy=pcall(service.withRenderer,actorVP,function()
        return actor:draw(drawMatrix)
      end,{eye=plan.pose.eye})
      if not called or value==false then error(tostring(actorWhy or value or "portable actor draw failed"),0) end
      -- Transparent HSD buckets exist only on extracted stage arenas. The
      -- OVERWORLD snapshot already completed its voxel-field pass above.
      if not snap.liveOverworld then
        g.setShader(shader);g.setDepthMode("lequal",false);g.setBlendMode("alpha","alphamultiply")
        for _,item in ipairs(T47.sorted(snap.scene.translucent,plan.pose.eye,snap.stageScale,snap.stageYaw)) do
          T47.drawGroup(g,shader,item.row,.01)
        end
        g.setBlendMode("add","alphamultiply")
        T47.drawBucket(g,shader,snap.scene.additive,.01)
      end
      detail={arenaId=snap.arenaId,source=snap.scene.source,width=w,height=h,
        mode=snap.liveOverworld and "terrarium-overworld-snapshot" or "terrarium-data-only-arena",
        opaque=#(snap.scene.opaque or {}),cutout=#(snap.scene.cutout or {}),
        crowd=#(snap.scene.crowd or {}),translucent=#(snap.scene.translucent or {}),additive=#(snap.scene.additive or {})}
    end)
    if pushed then pcall(g.setShader);pcall(g.setDepthMode);pcall(g.pop) end
    if #prior>0 then pcall(g.setCanvas,(table.unpack or unpack)(prior)) else pcall(g.setCanvas) end
    g.setColor(1,1,1,1)
    if not ok then return false,tostring(err) end
    return true,detail
  end

  local function staticBounds(actor)
    local b=actor and actor.scene and actor.scene.bounds or nil
    local mn=b and b.min or nil
    local mx=b and b.max or nil
    if not (type(mn)=="table" and type(mx)=="table") then return nil end
    local s=math.abs(tonumber(actor.worldScale) or 1)
    local sx=math.abs((tonumber(mx[1]) or 0)-(tonumber(mn[1]) or 0))*s
    local sy=math.abs((tonumber(mx[2]) or 0)-(tonumber(mn[2]) or 0))*s
    local sz=math.abs((tonumber(mx[3]) or 0)-(tonumber(mn[3]) or 0))*s
    if sy<=1e-3 then return nil end
    local breadth=math.sqrt(sx*sx+sz*sz)
    return {
      visualBottomY=0,visualTopY=sy,centerY=sy*.5,height=sy,
      breadth=breadth,spanX=sx,spanZ=sz,
      breadthHeightRatio=breadth/math.max(1e-3,sy),
      elevation=0,elevationNorm=0,
      source="CBE_PORTABLE_STATIC_APB_V2",confidence="high",
    }
  end

  local function portraitCamera(bounds,now)
    if type(bounds)~="table" then return nil,nil,nil end
    local h=math.max(1e-3,tonumber(bounds.height) or 0)
    if h<=1e-3 then return nil,nil,nil end
    local sx=math.max(0,tonumber(bounds.spanX) or tonumber(bounds.breadth) or 0)
    local sz=math.max(0,tonumber(bounds.spanZ) or 0)

    -- CBE's portable information actor is scaled in Colosseum world units
    -- (ordinary adults are roughly 16..18 high), whereas the shared Stadium
    -- portrait rig expects much smaller actor units. Classify only by the
    -- stable presented APB height: ordinary actors remain near-full, while the
    -- upper end progressively receives an upper-body composition.
    local sizePressure=sat((h-15.5)/5.5)
    local spanRatio=1.14-0.50*(sizePressure^1.05)
    local close=(mod.options:get("secondaryViewFraming") or "normal")=="close"
    if close then spanRatio=spanRatio*0.78 end
    local focusFrac=0.52+0.14*sizePressure+(close and 0.025 or 0)

    -- CBE visual parity: the portable PKX actor faces local +Z. A 26..42 degree
    -- orbit reads as the established forward three-quarter portrait here; the
    -- old 52..68 range looked almost profile once cropped. Complete a full
    -- gentle cycle in 10.5 seconds so it is actually observable in normal play.
    if not tonumber(P.cbePipPanEpoch) then P.cbePipPanEpoch=now end
    local panNorm=math.sin((now-P.cbePipPanEpoch)*(TWO_PI/10.5))
    local side=(mod.options:get("secondaryViewSide") or "left")
    local sideSign=(side=="left") and 1 or -1 -- Test16 accepted handedness
    local baseDeg,ampDeg=34.0,8.0
    local arc=math.rad(baseDeg+ampDeg*panNorm)*sideSign

    -- Freeze distance to the worst projected breadth across the complete pan.
    -- This prevents apparent zoom pumping while still keeping broad/long actors
    -- out of catastrophic one-segment crops. It is generic geometry, not a
    -- species/body-type rule.
    local function projectedAt(deg)
      local a=math.rad(deg)
      return sx*math.abs(math.cos(a))+sz*math.abs(math.sin(a))
    end
    local projected=math.max(projectedAt(baseDeg-ampDeg),projectedAt(baseDeg+ampDeg))
    local aspect=16/9
    local maxHorizontalOccupancy=close and 0.90 or 0.82
    local verticalSpan=math.max(h*spanRatio,
      projected/math.max(1e-3,aspect*maxHorizontalOccupancy))

    -- If breadth protection has pulled an actor back to a full-body window,
    -- lower the target smoothly rather than retaining a giant-only upper aim.
    local effectiveRatio=verticalSpan/h
    if effectiveRatio>1.02 then
      local t=sat((effectiveRatio-1.02)/0.30)
      focusFrac=mix(focusFrac,0.52,t)
    end

    local desiredFov=math.rad(close and 29.0 or 31.0)
    local dist=verticalSpan/(2*math.tan(desiredFov*.5))
    -- Keep perspective flattering even for the deliberately cropped large class.
    dist=math.max(dist,h*1.30)
    local fov=2*math.atan(verticalSpan/(2*dist))
    fov=math.max(math.rad(22),math.min(math.rad(34),fov))

    local elevation=math.rad(4.5)
    local flat=dist*math.cos(elevation)
    local focusY=h*focusFrac
    local eye={math.sin(arc)*flat,focusY+dist*math.sin(elevation),math.cos(arc)*flat}
    local focus={0,focusY,0}
    P.cbePipPanDegrees=(baseDeg+ampDeg*panNorm)*sideSign
    P.cbePipVisibleSpanRatio=effectiveRatio
    P.cbePipSizePressure=sizePressure
    return {eye=eye,focus=focus,up={0,1,0},fov=fov,curve=0},panNorm,sideSign
  end

  -- Test21 Gen1 action parity -------------------------------------------------
  -- CBE's Gen1 move/damage semantics can advance through ATTACK -> DAMAGE ->
  -- PASSIVE between two bounded (~10 fps) PiP draws. Test20 sampled only the
  -- latest camera phase, so the private information actor could miss the entire
  -- action even though CBE's full-rate stage actor reacted correctly. Preserve
  -- those authoritative Gen1 events in a tiny FIFO and consume them in the PiP
  -- draw context. Gen2 keeps its already-proven presentation-late phase path.
  local function reactsToBattle()
    local mode=P.visibilityMode and P.visibilityMode() or "constant"
    return mode~="portrait"
  end

  local function seenGen1Payload(kind,payload)
    if type(payload)~="table" then return false end
    if type(P.cbePipGen1Seen)~="table" then
      P.cbePipGen1Seen=setmetatable({}, {__mode="k"})
    end
    if P.cbePipGen1Seen[payload]==kind then return true end
    P.cbePipGen1Seen[payload]=kind
    return false
  end

  local function queueGen1Action(kind,side,payload,moveId,moveDef)
    if not (bcCbeActive() and bcCbeGeneration()==1) then return false end
    if (mod.options:get("secondaryView") or "off")~="on" or not reactsToBattle() then return false end
    if side~="player" then return false end
    if seenGen1Payload(kind,payload) then return false end
    local q=P.cbePipGen1Actions
    if type(q)~="table" then q={};P.cbePipGen1Actions=q end
    if #q>=16 then table.remove(q,1) end
    q[#q+1]={kind=kind,payload=payload,moveId=moveId,moveDef=moveDef}
    return true
  end

  P.noteCbeGen1Attack=function(side,moveId,moveDef,payload)
    return queueGen1Action("attack",side,payload,moveId,moveDef)
  end
  P.noteCbeGen1Hit=function(side,payload)
    return queueGen1Action("hit",side,payload)
  end
  P.noteCbeGen1Faint=function(side,payload)
    if not (bcCbeActive() and bcCbeGeneration()==1) then return false end
    if (mod.options:get("secondaryView") or "off")~="on" or not reactsToBattle() then return false end
    if side~="player" or seenGen1Payload("faint",payload) then return false end
    -- Raw Gen1 faint is intentionally early. Remember the side only; the actual
    -- actor:faint() call still waits for CBE's visible faint phase.
    P.cbePipGen1PendingFaintSide=side
    return true
  end

  local function consumeGen1Action(actor)
    local q=P.cbePipGen1Actions
    if type(q)~="table" or #q==0 then return false end
    local e=q[1]
    -- Preserve the authored attack before a rare recoil/self-hit. Damage can
    -- queue naturally behind Damage through PokemonActors; it must not cut the
    -- actor's own attack bank on the next 100 ms PiP refresh.
    if e.kind=="hit" and actor.state=="attack" then return false end
    table.remove(q,1)
    if e.kind=="attack" and type(actor.attack)=="function" then
      pcall(actor.attack,actor,e.moveId,e.moveDef)
    elseif e.kind=="hit" and type(actor.hit)=="function" then
      pcall(actor.hit,actor,e.payload or {})
    end
    return true
  end

  local function releaseActor()
    if P.cbePipActor and type(P.cbePipActor.release)=="function" then
      pcall(P.cbePipActor.release,P.cbePipActor)
    end
    P.cbePipActor=nil;P.cbePipActorService=nil;P.cbePipIdentity=nil
    P.cbePipPhaseSerial=nil;P.cbePipLastUpdate=nil;P.cbePipVacant=false
    P._cbePortableBounds=nil;P.cbePipBackdrop=nil;P.cbePipPanEpoch=nil
    P.cbePipPanDegrees=nil;P.cbePipVisibleSpanRatio=nil;P.cbePipSizePressure=nil
    P.cbePipGen1Actions=nil;P.cbePipGen1Seen=nil;P.cbePipGen1PendingFaintSide=nil
  end
  local function releaseCanvas()
    if T47 and type(T47.release)=="function" then pcall(T47.release) end
    if P.cbePipWorldApi and type(P.cbePipWorldApi.release)=="function" then
      pcall(P.cbePipWorldApi.release,P.cbePipWorldApi)
    end
    P.cbePipWorldApi=nil;P.cbePipWorldStatus=nil
    if P.cbePipCanvas and type(P.cbePipCanvas.release)=="function" then pcall(P.cbePipCanvas.release,P.cbePipCanvas) end
    if P.cbePipDepth and type(P.cbePipDepth.release)=="function" then pcall(P.cbePipDepth.release,P.cbePipDepth) end
    P.cbePipCanvas=nil;P.cbePipDepth=nil;P.cbePipCanvasW=nil;P.cbePipCanvasH=nil;P.cbePipDepthMode=nil
  end

  local oldClear=P.clear
  P.clear=function(...)
    releaseActor();releaseCanvas()
    return oldClear(...)
  end

  local function dexVariant()
    local C=backends and backends.__cbe
    local view=C and C.view or nil
    local battler=type(view)=="table" and view.player or nil
    local mon=type(battler)=="table" and (battler.mon or battler) or nil
    if type(mon)~="table" then return nil end
    local species=mon.species
    local dex=nil
    if type(species)=="number" then
      local n=math.floor(species);if n>=1 and n<=251 then dex=n end
    end
    local src=type(view)=="table" and view.__cbeSource or nil
    local data=(type(src)=="table" and src.data) or (view and view.game and view.game.data) or nil
    if not dex and data and type(data.pokemon)=="table" and species~=nil then
      local def=data.pokemon[species]
      local n=type(def)=="table" and tonumber(def.dex or def.index) or nil
      if n then n=math.floor(n);if n>=1 and n<=251 then dex=n end end
    end
    if not dex then return nil end
    local shiny=mon.shiny==true
    if mon.shiny==nil and type(mon.dvs)=="table" then
      local d=mon.dvs;local atk=tonumber(d.attack)
      local shinyAtk=atk==2 or atk==3 or atk==6 or atk==7 or atk==10 or atk==11 or atk==14 or atk==15
      shiny=(tonumber(d.defense)==10 and tonumber(d.speed)==10 and tonumber(d.special)==10 and shinyAtk) and true or false
    end
    return dex,shiny and "shiny" or "normal",mon,battler,view
  end

  local function infoModels()
    local C=backends and backends.__cbe
    local h=C and C.handle or nil
    if type(h)~="table" then
      local ok,v=pcall(function() return mod.find("COLOSSEUM_BATTLE_ENVIRONMENTS") end)
      if ok and type(v)=="table" then h=v end
      if type(h)~="table" then
        ok,v=pcall(function() return mod.find("COLOSSEUM_OVERHAUL") end)
        local hv=ok and type(v)=="table"
          and tostring(v.version or (v.exports and v.exports.version)) or ""
        if hv=="1.0" then h=v end
      end
    end
    local ex=type(h)=="table" and type(h.exports)=="table" and h.exports or nil
    local api=ex and ex.informationModels or nil
    return (type(api)=="table" and tonumber(api.version or 0)>=3) and api or nil
  end

  local function ensureActor()
    local dex,variant,mon,battler,view=dexVariant()
    if not dex then P.cbePipFailure="CBE player dex unavailable";return nil end
    local identity=tostring(mon)..":"..tostring(dex)..":"..tostring(variant)
    if P.cbePipActor and P.cbePipIdentity==identity then
      if not P._cbePortableBounds then P._cbePortableBounds=staticBounds(P.cbePipActor) end
      return P.cbePipActor
    end
    releaseActor()
    local api=infoModels()
    if not (api and type(api.resolveColosseum)=="function") then
      P.cbePipFailure="CBE informationModels v3 unavailable";return nil
    end
    local okResolve,service,source,ctx=pcall(api.resolveColosseum,api,
      {game=view and view.game or nil,mon=mon,battler=battler})
    if not okResolve or type(service)~="table" or type(service.acquire)~="function"
        or type(service.withRenderer)~="function" then
      P.cbePipFailure="CBE portable model unavailable: "..tostring(service or source);return nil
    end
    local okAcquire,actor,err=pcall(service.acquire,source,dex,variant,
      {side="player",context=ctx})
    if not okAcquire or type(actor)~="table" then
      P.cbePipFailure="CBE actor acquire failed: "..tostring(actor or err);return nil
    end
    P.cbePipActor=actor;P.cbePipActorService=service;P.cbePipIdentity=identity
    P.cbePipPhaseSerial=nil;P.cbePipLastUpdate=wallNow();P.cbePipVacant=false
    if type(actor.spawn)=="function" then pcall(actor.spawn,actor,1) end
    if type(actor.idle)=="function" then pcall(actor.idle,actor) end
    P._cbePortableBounds=staticBounds(actor)
    P.cbePipPanEpoch=wallNow()
    P.cbePipFailure=nil
    return actor
  end

  local function syncPhase(actor)
    local C=backends and backends.__cbe
    if not (actor and C) then return end
    local mode=P.visibilityMode and P.visibilityMode() or "constant"
    if mode=="portrait" then
      P.cbePipGen1Actions=nil;P.cbePipGen1PendingFaintSide=nil
      if P.cbePipPhaseSerial~="portrait" then
        if type(actor.spawn)=="function" then pcall(actor.spawn,actor,1) end
        if type(actor.idle)=="function" then pcall(actor.idle,actor) end
        P.cbePipPhaseSerial="portrait";P.cbePipVacant=false
      end
      return
    end

    local gen=(tonumber(C.generation)==2) and 2 or 1
    if gen==1 then consumeGen1Action(actor) end

    local serial=tonumber(C.phaseSerial) or 0
    if P.cbePipPhaseSerial==serial then return end
    P.cbePipPhaseSerial=serial
    local phase=tostring(C.lastPhase or "")

    if gen==1 then
      -- ATTACK and DAMAGE are driven by the preserved semantic FIFO above. CBE's
      -- visible faint phase remains authoritative because raw Gen1 HP==0 leads
      -- the actual sink/collapse presentation.
      if phase=="faint" then
        local side=C.currentFaintSide or P.cbePipGen1PendingFaintSide
        if side=="player" and type(actor.faint)=="function" then
          pcall(actor.faint,actor,"collapse");P.cbePipVacant=true
          P.cbePipGen1PendingFaintSide=nil
        end
      elseif phase=="switch" then
        -- Identity change reacquires the presented replacement.
      elseif phase=="passive" or phase=="intro" then
        if not P.cbePipVacant and type(actor.idle)=="function" and actor.state~="attack"
            and actor.state~="hit" and actor.state~="faint" then
          pcall(actor.idle,actor)
        end
      end
      return
    end

    -- Gen2 remains on the already runtime-proven presentation-late phase path.
    if phase=="attack" then
      local a=C.currentAttack
      if a and a.side=="player" and type(actor.attack)=="function" then
        pcall(actor.attack,actor,a.moveId,a.moveDef)
      end
    elseif phase=="damage" or phase=="reaction" then
      local a=C.currentAttack
      if a and a.side=="enemy" and type(actor.hit)=="function" then
        pcall(actor.hit,actor,{})
      end
    elseif phase=="faint" then
      if C.currentFaintSide=="player" and type(actor.faint)=="function" then
        pcall(actor.faint,actor,"collapse");P.cbePipVacant=true
      end
    elseif phase=="switch" then
      -- Identity change reacquires the presented replacement.
    elseif phase=="passive" or phase=="intro" then
      if not P.cbePipVacant and type(actor.idle)=="function" and actor.state~="attack"
          and actor.state~="hit" and actor.state~="faint" then
        pcall(actor.idle,actor)
      end
    end
  end

  local function ensureCanvas(w,h)
    local g=love and love.graphics
    if not (g and type(g.newCanvas)=="function") then return nil end
    if P.cbePipCanvas and P.cbePipCanvasW==w and P.cbePipCanvasH==h then return P.cbePipCanvas end
    releaseCanvas()
    local ok,c=pcall(g.newCanvas,w,h,{dpiscale=1,msaa=0})
    if not ok then ok,c=pcall(g.newCanvas,w,h) end
    if not ok or not c then P.cbePipFailure="CBE PiP color canvas unavailable: "..tostring(c);return nil end
    P.cbePipCanvas=c;P.cbePipCanvasW=w;P.cbePipCanvasH=h
    local formats={}
    if type(g.getCanvasFormats)=="function" then
      local okF,v=pcall(g.getCanvasFormats);if okF and type(v)=="table" then formats=v end
    end
    for _,fmt in ipairs({"depth24stencil8","depth16"}) do
      if formats[fmt]~=false then
        local okD,d=pcall(g.newCanvas,w,h,{format=fmt,readable=false,dpiscale=1,msaa=0})
        if okD and d then P.cbePipDepth=d;P.cbePipDepthMode="explicit";break end
      end
    end
    if not P.cbePipDepthMode then P.cbePipDepthMode="auto" end
    return c
  end

  local function bindCanvas(g,c)
    if P.cbePipDepthMode=="explicit" and P.cbePipDepth then
      local ok=pcall(g.setCanvas,{c,depthstencil=P.cbePipDepth})
      if ok then return true,true end
      P.cbePipDepth=nil;P.cbePipDepthMode="auto"
    end
    if P.cbePipDepthMode=="auto" then
      local ok=pcall(g.setCanvas,{c,depth=true})
      if ok then return true,true end
      P.cbePipDepthMode="none"
    end
    local ok=pcall(g.setCanvas,c)
    return ok,false
  end

  P.cbeEligible=function()
    local C=backends and backends.__cbe
    if not (C and C.active==true and bcCbeActive()) then return false end
    if not enabled() or (mod.options:get("secondaryView") or "off")~="on" then return false end
    if not (P.liveLifecycleEligible and P.liveLifecycleEligible()) then return false end
    return infoModels()~=nil
  end

  -- Real CBE arena visitor: the portrait camera and portable actor are moved
  -- together into the live stage's coordinate frame. Their relative optical
  -- composition is unchanged. The provider only draws its resident environment.
  local function liveArenaRequested()
    local C=backends and backends.__cbe
    local h=C and C.handle
    if type(h)~="table" then return false end
    local id=tostring(h.id or "")
    local version=tostring(h.version or (h.exports and h.exports.version) or "")
    return (id=="COLOSSEUM_BATTLE_ENVIRONMENTS" and version=="2.0")
      or (id=="COLOSSEUM_OVERHAUL" and version=="1.0")
  end
  local function renderLiveArena(g,c,rw,rh,arena,cam,actor)
    local C=backends and backends.__cbe
    local ex=C and C.handle and C.handle.exports
    local api=type(ex)=="table" and ex.bcSecondaryArena or nil
    local B=state.cbeStockReabsorb
    if not (B and B.exactStock and B.state=="PATCHED" and B.arenaServed
        and type(api)=="table" and api.version==1 and type(api.draw)=="function") then
      return false,"verified CBE secondary arena seam unavailable"
    end
    if type(arena)~="table" then return false,"live CBE stage unavailable" end
    P.cbePipWorldApi=api
    local service=P.cbePipActorService
    if not (service and type(service.withRenderer)=="function"
        and type(actor.draw)=="function" and type(actor.matrix)=="function") then
      return false,"portable actor renderer unavailable"
    end
    local request={canvas=c,width=rw,height=rh,camera=cam,
      arenaId=arena._cbeArenaId,cachePath=arena.cachePath,groundY=0,
      dex=actor.dex,variant=actor.variant,actorScale=actor.worldScale,
      bind=function()return bindCanvas(g,c)end}
    local ok,result,detail=pcall(api.draw,api,request,function(vp,frame,pose)
      local called,value,why=pcall(service.withRenderer,vp,function()
        return actor:draw(matMul(frame,actor:matrix(0,0,0,0,1)))
      end,{eye=pose.eye})
      if not called or value==false then error(tostring(why or value or "portable actor draw failed"),0) end
      return true
    end)
    if not ok then return false,tostring(result) end
    if result~=true then return false,tostring(detail or "secondary arena draw declined") end
    P.cbePipWorldStatus=detail
    P.cbePipBackdrop=arena._cbeArenaId
    return true
  end

  P.renderCbeFrame=function()
    P.cbePipRejectStale=liveArenaRequested() or T47.requested()
    if not P.cbeEligible() then P.shot=nil;return end

    -- Test52: LIVE VIEW means live presentation, not a second independently
    -- clocked Pokemon. Prefer the resident actor CBE has already advanced for
    -- this exact frame. LIVING PORTRAIT/DYNAMIC keep the established private
    -- actor semantics, and LIVE VIEW also fails over to that path until the
    -- resident actor has produced its first worldMatrix.
    local liveView=P.liveViewMode and P.liveViewMode()
    local actor,actorService,liveMatrix=nil,nil,nil
    if liveView and T47.requested() then
      local resident,service= T47.livePlayer()
      if resident and service then
        actor=resident;actorService=service;liveMatrix=resident.worldMatrix
        P.cbePipResidentLive=true
        -- Any raw Gen1 events captured before the first resident frame are not
        -- allowed to replay later through a private actor.
        P.cbePipGen1Actions=nil;P.cbePipGen1PendingFaintSide=nil
      end
    end
    if not actor then
      P.cbePipResidentLive=false
      actor=ensureActor();actorService=P.cbePipActorService
      if not actor then P.shot=nil;P.failure=P.cbePipFailure or "CBE PiP actor unavailable";return end
      syncPhase(actor)
      local nowStep=wallNow();local last=tonumber(P.cbePipLastUpdate) or nowStep
      local dt=math.max(0,math.min(0.20,nowStep-last));P.cbePipLastUpdate=nowStep
      if type(actor.update)=="function" then pcall(actor.update,actor,dt) end
    end

    local now=wallNow()
    local stageArena=currentStageArena()
    if not P._cbePortableBounds or P.cbePipResidentLive then P._cbePortableBounds=staticBounds(actor) end
    local cam,panNorm,sideSign=portraitCamera(P._cbePortableBounds,now)
    if not cam then P.shot=nil;P.failure="CBE APB portrait camera unavailable";return end
    P.actorMode="cbe_colosseum"

    local rw,rh=P.renderResolution()
    local c=ensureCanvas(rw,rh)
    local g=love and love.graphics
    if not (c and g) then P.shot=nil;P.failure=P.cbePipFailure or "CBE PiP renderer unavailable";return end
    if liveArenaRequested() then
      local ok,why=renderLiveArena(g,c,rw,rh,stageArena,cam,actor)
      if ok then
        P.shot={canvas=c};P.failure=nil;P.cbePipFailure=nil
        P.cbePipFrames=(P.cbePipFrames or 0)+1
      else
        -- Never disguise a failed live render as a synthetic arena, or retain
        -- a previous venue's image after a scene/session transition.
        P.shot=nil;P.failure="CBE live arena PiP: "..tostring(why)
        P.cbePipFailure=P.failure;P.cbePipWorldStatus=nil
      end
      return
    end
    if T47.requested() then
      local service=actorService or P.cbePipActorService
      local ok,detail=T47.draw({canvas=c,width=rw,height=rh,camera=cam,arena=stageArena,groundY=0,
        liveMatrix=liveMatrix,bind=function()return bindCanvas(g,c)end},actor,service)
      if ok then
        P.shot={canvas=c};P.failure=nil;P.cbePipFailure=nil
        P.cbePipWorldStatus=detail;P.cbePipBackdrop=stageArena and stageArena._cbeArenaId or nil
        P.cbePipFrames=(P.cbePipFrames or 0)+1
      else
        -- Fail closed. Never hide an isolation failure by silently returning to
        -- the synthetic card or retaining a stale arena frame.
        P.shot=nil;P.failure="Terrarium data-only arena PiP: "..tostring(detail)
        P.cbePipFailure=P.failure;P.cbePipWorldStatus=nil
      end
      return
    end
    -- Older CBE 1.8.4 keeps its already-accepted themed-card fallback.
    local prior={}
    if type(g.getCanvas)=="function" then
      local ok,a,b,c2,d=pcall(g.getCanvas);if ok and a~=nil then prior={a,b,c2,d} end
    end
    local pushed=false
    if type(g.push)=="function" then pushed=pcall(g.push,"all") end
    local bound,depth=bindCanvas(g,c)
    if not bound then
      if pushed and type(g.pop)=="function" then pcall(g.pop) end
      if #prior>0 then pcall(g.setCanvas,(table.unpack or unpack)(prior)) else pcall(g.setCanvas) end
      P.shot=nil;P.failure="CBE PiP framebuffer bind failed";return
    end
    if g.origin then g.origin() end
    if g.setScissor then g.setScissor() end
    if depth then g.clear(0.025,0.075,0.145,1,true,true) else g.clear(0.025,0.075,0.145,1) end
    if g.setDepthMode then pcall(g.setDepthMode) end
    drawBackdrop(g,rw,rh,stageArena,panNorm,sideSign)

    local eye,focus=cam.eye,cam.focus
    local view=lookAt(eye[1],eye[2],eye[3],focus[1],focus[2],focus[3])
    local projection=matMul(LOVE_CANVAS_Y,perspective(cam.fov,rw/math.max(1,rh),0.1,1000))
    local vp=matMul(projection,view)
    local service=P.cbePipActorService
    local drawOk=false;local drawErr=nil
    if service and type(service.withRenderer)=="function" and type(actor.draw)=="function"
        and type(actor.matrix)=="function" then
      local okR,value=pcall(service.withRenderer,vp,function()
        local m=actor:matrix(0,0,0,0,1)
        return actor:draw(m)
      end,{eye=eye})
      drawOk=okR and value~=false
      if not drawOk then drawErr=value end
    end
    pcall(g.setShader);pcall(g.setDepthMode)
    if pushed and type(g.pop)=="function" then pcall(g.pop) end
    if #prior>0 then pcall(g.setCanvas,(table.unpack or unpack)(prior)) else pcall(g.setCanvas) end
    g.setColor(1,1,1,1)
    if drawOk then
      P.shot={canvas=P.cbePipCanvas};P.failure=nil;P.cbePipFailure=nil
      P.cbePipFrames=(P.cbePipFrames or 0)+1
    else
      P.shot=nil;P.failure="CBE portable actor draw failed: "..tostring(drawErr)
    end
  end
end)()

state.secondaryViewProbe.renderFrame=function()
  local P=state.secondaryViewProbe; P.renderFrameCalls=(P.renderFrameCalls or 0)+1
  P.dramalessS2ExactMirrored=false
  if not (P.installed and P.backend and P.eligible(P.backend)) then P.shot=nil; return end
  P.eligibleFrames=(P.eligibleFrames or 0)+1
  local world=P.arenaProvider and P.arenaProvider.state or nil
  if not (world and world.map) then P.shot=nil; P.failure="Dramaless voxel arena not active"; return end
  local constantLive=P.persistentMode and P.persistentMode() and P.constantArmed==true
  if P.dramalessConstantBattle~=state.battle then
    P.dramalessConstantBattle=state.battle
    P.dramalessConstantLastPresence=nil
    P.dramalessConstantLastArena=nil
    P.dramalessS2SyncIdentity=nil
    P.dramalessS2SyncLiveContext=nil
    P.dramalessS2ConstantScale=nil
    P.dramalessS2Flash=nil
    P.dramalessConstantLastRender=nil
  end
  local okArena,arena=pcall(P.arenaProvider.arena,P.arenaProvider,{services={}})
  if okArena and type(arena)=="table" then
    P.dramalessConstantLastArena=arena
  elseif constantLive and type(P.dramalessConstantLastArena)=="table" then
    -- Provider phase changes may transiently withhold the arena accessor. The
    -- Dramaless world itself remains live, so reuse this battle's established
    -- geometry while resolving actor presence fresh from Importer metadata.
    arena=P.dramalessConstantLastArena
    okArena=true
  end
  if not (okArena and type(arena)=="table") then P.shot=nil; P.failure="Dramaless arena unavailable: "..tostring(arena); return end

  -- Actor-provider arbitration. Stadium2 Importer's public scene-neutral model
  -- API is the maintained premier Stadium source and therefore resolves first.
  -- In CONSTANT, its live scene contributes metadata only; the private model
  -- remains BC-owned through models API v2.
  local actorMode=nil
  local vacant=false
  local liveKnown,livePresent,liveActor,liveVisual=false,nil,nil,nil
  if constantLive and P.diagS2 and type(P.dramalessImporterLivePresentation)=="function" then
    liveKnown,livePresent,liveActor,liveVisual=P.dramalessImporterLivePresentation()
    P.dramalessS2LiveVisual=liveVisual
    if liveKnown then P.dramalessConstantLastPresence=livePresent end
    local effectivePresent=liveKnown and livePresent or P.dramalessConstantLastPresence
    if effectivePresent==false then
      actorMode="stadium2_importer"
      vacant=true
    else
      local mon=type(liveActor)=="table" and liveActor.mon or nil
      local okS2,value=pcall(P.resolveS2Actor,mon)
      if okS2 and value then
        actorMode="stadium2_importer"
        if liveActor and type(P.syncDramalessS2Presentation)=="function" then
          pcall(P.syncDramalessS2Presentation,P.s2Instance,liveActor)
        end
      end
    end
  end
  if not actorMode and not (constantLive and liveKnown) and type(P.resolveS2Actor)=="function" then
    local okS2,value=pcall(P.resolveS2Actor)
    if okS2 and value then actorMode="stadium2_importer" end
  end
  local sbfxShowing=false
  if not actorMode and P.diagSB and P.diagMP and P.diagMA and P.battles then
    local okResolve,provider,entry=pcall(P.battles.resolve,P.battles,"models")
    if okResolve and provider==P.modelProvider and type(P.modelProvider.showing)=="function" then
      local okShow,value=pcall(P.modelProvider.showing,P.modelProvider,nil,"player")
      sbfxShowing=okShow and value and true or false
      if sbfxShowing then actorMode="sbfx" end
    end
  end
  local spriteSource=state.secondarySpriteSource
  if not actorMode and type(spriteSource)=="table" and type(spriteSource.drawPlayer)=="function" then actorMode="sprite" end
  if not actorMode then
    P.shot=nil; P.failure=P.s2Failure or (sbfxShowing and "secondary actor unavailable" or "no compatible Secondary View actor provider")
    return
  end

  local cam,pitch=P.cameraFor(P.backend,arena,0,actorMode)
  if not cam then P.shot=nil; P.failure="no portrait camera"; return end

  P.renderAttempts=(P.renderAttempts or 0)+1
  local V3,AA=P.Voxel3D,P.AntiAlias; local oldBegin,oldResolve=V3.beginScene,AA.resolve
  V3.beginScene=function(rw,rh,cx,cy,vw,vh,sky,slot) if slot=="battle" then slot="bc_secondary_view" end; return oldBegin(rw,rh,cx,cy,vw,vh,sky,slot) end
  AA.resolve=function(canvas,w,h,slot,...) if slot=="battle" then slot="bc_secondary_view" end; return oldResolve(canvas,w,h,slot,...) end
  local actorErr=nil
  local function drawActors(view)
    if not (view and type(view.vp)=="table") then actorErr="secondary world supplied no VP"; return end
    if tonumber(view.groundY) then
      local nextCam,nextPitch=P.cameraFor(P.backend,arena,view.groundY,actorMode)
      if nextCam then cam,pitch=nextCam,nextPitch end
    end
    if vacant and actorMode=="stadium2_importer" then
      -- Faint/replacement vacancy: keep the same 3D monitor camera/world but
      -- intentionally submit no player actor until Importer reports occupancy.
    elseif actorMode=="stadium2_importer" then
      local okDraw,value=pcall(P.drawS2Actor,view,arena,tonumber(view.groundY) or 0,cam)
      if not okDraw then actorErr="Stadium2 Importer model draw error: "..tostring(value)
      elseif not value then actorErr=P.s2Failure or "Stadium2 Importer model unavailable" end
    elseif actorMode=="sbfx" then
      local okDraw,a,b=pcall(P.modelsApi.withRenderer,view.vp,function()
        P.modelProvider:drawWorld(nil,0)
        return true
      end)
      if not okDraw then actorErr="SBFX live-model draw error: "..tostring(a)
      elseif not a then actorErr="SBFX Stadium renderer rejected: "..tostring(b) end
    else
      local okDraw,value=pcall(spriteSource.drawPlayer,view,arena,tonumber(view.groundY) or 0,cam)
      if not okDraw then actorErr="2D portrait draw error: "..tostring(value)
      elseif not value then actorErr="2D portrait source unavailable" end
    end
    if not actorErr then P.actorDraws=(P.actorDraws or 0)+1 end
  end
  P.camera,P.pitch=cam,pitch; P.rendering=true; P.actorMode=vacant and "empty_3d" or actorMode

  -- v1.2.4 Test23 retained: Secondary View private worlds must be resolution-bounded.
  -- Dramaless' public VoxelBattleScene.render() derives its battle surface from
  -- love.graphics.getPixelDimensions(), which otherwise makes a tiny PiP pay
  -- for a second full-device-resolution 3D world (plus any provider AA).
  --
  -- Keep the accepted camera/composition exactly equivalent: preserve the
  -- physical framebuffer aspect ratio, freeze Renderer.fitScale at the value
  -- the provider would have used for the real display, and pre-compensate the
  -- host FOV so Dramaless' own windowCamera() produces the same final vertical
  -- FOV after seeing the smaller private target. Only pixel workload changes.
  local g=love and love.graphics or nil
  local oldPixelDimensions=g and g.getPixelDimensions or nil
  local actualW,actualH=nil,nil
  if type(oldPixelDimensions)=="function" then
    local okSize,w,h=pcall(oldPixelDimensions)
    if okSize and tonumber(w) and tonumber(h) and w>0 and h>0 then actualW,actualH=w,h end
  end
  if not actualW and g and type(g.getDimensions)=="function" then
    local okSize,w,h=pcall(g.getDimensions)
    if okSize and tonumber(w) and tonumber(h) and w>0 and h>0 then actualW,actualH=w,h end
  end
  actualW,actualH=actualW or 320,actualH or 180
  local targetW,targetH=P.renderResolution()
  local scale=math.min(1,targetW/math.max(1,actualW),targetH/math.max(1,actualH))
  local privateW=math.max(1,math.floor(actualW*scale+0.5))
  local privateH=math.max(1,math.floor(actualH*scale+0.5))
  P.dramalessPrivateW,P.dramalessPrivateH=privateW,privateH
  P.dramalessDisplayW,P.dramalessDisplayH=actualW,actualH

  local Renderer=nil
  local oldFitScale=nil
  local frozenFitScale=nil
  local okRenderer,value=pcall(require,"src.render.Renderer")
  if okRenderer and type(value)=="table" and type(value.fitScale)=="function" then
    Renderer=value; oldFitScale=value.fitScale
    local okFit,fit=pcall(oldFitScale,Renderer)
    if okFit and type(fit)=="number" and fit>0 then frozenFitScale=fit end
  end

  local renderCam=cam
  if type(cam)=="table" and type(cam.fov)=="number" and actualH>0 and privateH>0 then
    renderCam={}
    for k,v in pairs(cam) do renderCam[k]=v end
    renderCam.fov=2*math.atan(math.tan(cam.fov*0.5)*(actualH/privateH))
  end

  if g and type(oldPixelDimensions)=="function" then
    g.getPixelDimensions=function() return privateW,privateH end
  end
  if Renderer and frozenFitScale then
    Renderer.fitScale=function() return frozenFitScale end
  end

  local _bcRenderStart=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
  local ok,canvas=pcall(P.Scene.render,world,arena,drawActors,{pose=renderCam,pitch=pitch})
  local _bcRenderEnd=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
  P.eventMirrorRenderMs=math.max(0,(_bcRenderEnd-_bcRenderStart)*1000)

  if Renderer and oldFitScale then Renderer.fitScale=oldFitScale end
  if g and type(oldPixelDimensions)=="function" then g.getPixelDimensions=oldPixelDimensions end
  P.rendering=false; P.camera=nil; P.pitch=nil
  V3.beginScene=oldBegin; AA.resolve=oldResolve
  if actorErr then P.shot=nil; P.failure=actorErr
  elseif ok and canvas then
    P.shot={canvas=canvas}; P.failure=nil; P.frames=(P.frames or 0)+1
    if P.lastLoggedActorMode~=actorMode then
      P.lastLoggedActorMode=actorMode
      local label=(actorMode=="stadium2_importer" and "Stadium2 Importer scene-neutral model")
        or (actorMode=="sbfx" and "SBFX Stadium models")
        or "Dramaless/native 2D player portrait"
      mod.log:warn("[SECONDARY VIEW] live actor path: %s",label)
    end
  else P.shot=nil; P.failure=ok and ("render returned "..tostring(canvas)) or ("render error: "..tostring(canvas)) end
end

state.secondaryViewProbe.fixedStep=function()
  local P=state.secondaryViewProbe; if not P then return end; P.fixedStepCalls=(P.fixedStepCalls or 0)+1

  -- Test20 CBE: provider-owned APB portrait rendering remains draw-scheduled only.
  -- Do not let the generic Dramaless fallback clear its bounded last-good shot.
  if type(P.cbeEligible)=="function" and P.cbeEligible() then
    P.status="eligible / Secondary View / CBE APB forward-pan portrait"
    return
  end

  -- Gold Stadium2 Importer owns a complete Stadium scene. DYNAMIC retains the
  -- accepted fixed-step ~10 fps cadence. Test18 moves ONLY persistent modes to
  -- the render.hud wall clock, matching the already-proven Dramaless / Randy /
  -- Ultimate / Ascendant / Dramatic rule: Gen2 attack presentation can pause the
  -- battle update/fixed-step seam, but it must never pause a persistent PiP.
  if type(P.goldImporterEligible)=="function" and P.goldImporterEligible() then
    P.status="eligible / Secondary View / Gold Stadium2 Importer live scene"
    local persistent=P.persistentMode and P.persistentMode() and P.constantArmed==true
    if persistent then return end
    P.accum=(tonumber(P.accum) or 0)+1/60
    if P.accum<0.10 and P.shot then return end
    P.accum=0
    return P.renderGoldImporterFrame()
  end
  -- Importer 0.14 direct Gen1: DYNAMIC only marks a draw-safe refresh here;
  -- persistent LIVE VIEW owns its wall-clock refresh in render.hud below.
  if type(P.importer14Eligible)=="function" and P.importer14Eligible() then
    P.status="eligible / Secondary View / Stadium2 Importer 0.14 public live scene"
    if P.persistentMode and P.persistentMode() and P.constantArmed==true then return end
    P.accum=(tonumber(P.accum) or 0)+1/60
    if (not P.shot) or P.accum>=0.10 then
      P.importer14RenderDue=true
      P.accum=0
    end
    return
  end

  -- Rebase28: Randy's alternate-eye renderer returns nil on a fresh pass until
  -- its terrain cache is prefetched.  Warm that provider-owned cache while BC
  -- is still suppressing PiP during the fast Gen2 Intro/Send-In lifecycle, so
  -- the first eligible idle/menu frame does not pay the cold-start delay.
  if type(P.warmRandyScene)=="function" then pcall(P.warmRandyScene) end
  if type(P.randyEligible)=="function" and P.randyEligible() then
    P.status="eligible / Secondary View / Randy live world + "..tostring(P.actorMode or "actor scan")
    -- Rebase30: provider-native VoxelScene rendering happens only from render.hud.
    -- Test52 keeps Voxel Ultimate Gen2 CONSTANT on a wall-clock refresh and
    -- wall-clock draw time so attack/faint simulation cadence cannot pause the
    -- monitor. Randy itself remains on the accepted fixed-step due marks until
    -- its own isolated CONSTANT application is tested.
    local gold=backends.__gold
    local constantVU=gold and gold.providerKind=="voxel_ultimate"
      and P.persistentMode and P.persistentMode() and P.constantArmed==true
    local constantRandy=gold and gold.providerKind=="randy"
      and P.persistentMode and P.persistentMode() and P.constantArmed==true
    if constantVU or constantRandy then return end
    P.accum=(tonumber(P.accum) or 0)+1/60
    if (not P.shot) or P.accum>=0.10 then
      P.randyRenderDue=true
      P.accum=0
    end
    return
  end

  -- Rebase39 Voxel Ascendant public VoxelScene alternate-camera pass renders
  -- from render.hud. Keep the accepted ~10 fps scheduler here and preserve
  -- the last good canvas between due frames.
  if type(P.voxelAscendantEligible)=="function" and P.voxelAscendantEligible() then
    P.status="eligible / Secondary View / Voxel Ascendant public MAP world"
    -- Test49: DYNAMIC keeps the accepted fixed-step due marks. CONSTANT owns
    -- its wall-clock refresh from render.hud so attack/faint cadence cannot pause it.
    if P.persistentMode and P.persistentMode() and P.constantArmed==true then return end
    P.accum=(tonumber(P.accum) or 0)+1/60
    if (not P.shot) or P.accum>=0.10 then
      P.voxelAscendantRenderDue=true
      P.accum=0
    end
    return
  end

  -- Rebase38 Battle Art private world renders from render.hud only. Keep the
  -- fixed-step director from clearing its last good canvas while Battle Art is
  -- the active proven eligibility seam.
  if type(P.battleArtEligible)=="function" and P.battleArtEligible() then
    P.status="eligible / Secondary View / Battle Art lower-level world"
    return
  end

  -- Rebase58 base Dramatic: never perform the second 3D world render from the
  -- fixed-step/update seam. 1.6.x predates the newer draw-safe provider paths
  -- and a private Voxel/BattleScene pass here stalls simulation/input on Android.
  -- Fixed-step only schedules a conservative ~6.7 fps PiP refresh; render.hud
  -- performs the graphics work in an actual draw context and preserves the last
  -- good canvas between refreshes.
  if type(P.dramaticEligible)=="function" and P.dramaticEligible() then
    P.status="eligible / Secondary View / Dramatic draw-scheduled world"
    -- Test48: DYNAMIC retains the accepted ~6.7 fps fixed-step due marks.
    -- CONSTANT owns its refresh clock in render.hud so attack/faint simulation
    -- cadence cannot pause the monitor.
    if P.persistentMode and P.persistentMode() and P.constantArmed==true then return end
    P.accum=(tonumber(P.accum) or 0)+1/60
    if not P.drag and ((not P.shot) or P.accum>=0.15) then
      P.dramaticRenderDue=true
      P.accum=0
    end
    return
  end

  -- DYNAMIC preserves Potato's accepted update-time path. CONSTANT owns its
  -- refresh clock in render.hud so attack/faint simulation timing cannot pause
  -- the monitor. fixedStep performs no CONSTANT private-render scheduling.
  if type(P.potatoEligible)=="function" and P.potatoEligible() then
    P.status="eligible / Secondary View / PotatoVoxel staged world"
    if P.persistentMode and P.persistentMode() and P.constantArmed==true then
      return
    end
    P.accum=(tonumber(P.accum) or 0)+1/60
    if P.accum<0.10 and P.shot then return end
    P.accum=0
    if type(P.renderPotatoFrame)=="function" then return P.renderPotatoFrame() end
    P.shot=nil; P.failure="PotatoVoxel Secondary View renderer unavailable"
    return
  end

  if not P.installed then P.status="fixed-step alive / seam blocked"; P.shot=nil; P.dramalessRenderDue=false; return end
  if not P.eligible(P.backend) then P.status="fixed-step alive / not eligible"; P.shot=nil; P.accum=0; P.dramalessRenderDue=false; return end
  -- v1.2.4 Test24: match the draw-safe scheduling already proven for the other
  -- expensive private 3D worlds. DYNAMIC keeps its accepted fixed-step cadence.
  -- Test46 CONSTANT moves only the refresh CLOCK to wall-clock render.hud so an
  -- attack/faint simulation stall cannot pause the monitor; expensive 3D work
  -- still happens exclusively in the same draw-safe Dramaless path.
  P.status="eligible / Secondary View / Dramaless draw-scheduled world + "..tostring(P.actorMode or "actor scan")
  if P.persistentMode and P.persistentMode() and P.constantArmed==true then
    return
  end
  P.accum=(tonumber(P.accum) or 0)+1/60
  if (not P.shot) or P.accum>=0.10 then
    P.dramalessRenderDue=true
    P.accum=0
  end
  return
end

state.secondaryViewProbe.placementXY=function(sw,sh,targetW,targetH)
  local P=state.secondaryViewProbe
  -- While a pointer drag is active, draw from the live absolute top-left.
  if P and P.drag and P.drag.active and P.drag.x and P.drag.y then
    local maxX=math.max(0,sw-targetW)
    local maxY=math.max(0,sh-targetH)
    return math.max(0,math.min(maxX,P.drag.x)),math.max(0,math.min(maxY,P.drag.y))
  end

  local mode=mod.options:get("secondaryViewPlace") or "mid_right"
  if mode=="custom" then
    local nx=math.max(0,math.min(1000,tonumber(mod.options:get("secondaryViewCustomX")) or 500))/1000
    local ny=math.max(0,math.min(1000,tonumber(mod.options:get("secondaryViewCustomY")) or 220))/1000
    return math.floor(math.max(0,sw-targetW)*nx+0.5),
           math.floor(math.max(0,sh-targetH)*ny+0.5)
  end

  -- "MID" means the DW3-inspired middle band, but kept above the stock white
  -- battle UI. Its bottom edge targets ~65% of screen height instead of true
  -- vertical centre, which overlapped the command box in Rebase 3.
  local midY=math.max(12,math.floor(sh*0.65-targetH-8))
  local y=(mode=="mid_right" or mode=="mid_left" or mode=="mid_center") and midY or 12
  if mode=="top_left" or mode=="mid_left" then return 12,y end
  if mode=="mid_center" then return math.floor((sw-targetW)*0.5),y end
  if mode=="mid_right" then return sw-targetW-12,y end
  return sw-targetW-12,12
end

-- Global PiP frame compositor v1.2.8 ---------------------------------------
-- Colosseum Inspired UI Overhaul 1.1.0: portraitPod uses c=8*u with a
-- 78*u normal portrait; portraitPodOverlay supplies the complete 45-degree
-- eight-edge opening. Only that shape language and its metal RGB are used:
-- no UI artwork, UI renderer, provider dependency or extra scene is copied.
-- The already-rendered PiP texture is mapped without rescaling its composition
-- to a cached eight-vertex fan. This actually removes the image corners and
-- does not clear/borrow the host stencil or allocate another render target.
;(function()
  local P=state.secondaryViewProbe
  function P.drawCutFrameRect(g,mode,x,y,w,h,c)
    g.polygon(mode,x+c,y, x+w-c,y, x+w,y+c, x+w,y+h-c,
      x+w-c,y+h, x+c,y+h, x,y+h-c, x,y+c)
  end
  function P.cutFrameMesh(g,w,h,canvas)
    local cache=P.cutFrameCache
    if not cache or cache.w~=w or cache.h~=h then
      local old=cache
      cache={w=w,h=h,cut=math.min(w,h)*8/78}
      P.cutFrameCache=cache
      local c=cache.cut
      local points={{c,0},{w-c,0},{w,c},{w,h-c},
        {w-c,h},{c,h},{0,h-c},{0,c}}
      local vertices={}
      for i,p in ipairs(points) do
        vertices[i]={p[1],p[2],p[1]/w,p[2]/h,1,1,1,1}
      end
      local ok,result=pcall(function()
        if old and old.mesh then
          old.mesh:setVertices(vertices)
          return old.mesh
        end
        return g.newMesh(vertices,"fan","dynamic")
      end)
      if ok then cache.mesh=result else cache.error=tostring(result) end
    end
    if not cache.mesh then return nil end
    local ok,err=pcall(cache.mesh.setTexture,cache.mesh,canvas)
    if not ok then cache.error=tostring(err); return nil end
    return cache.mesh
  end
end)()

state.secondaryViewProbe.draw=function()
  local P=state.secondaryViewProbe
  if not (P and love and love.graphics) then
    if P then P.lastRect=nil end
    return
  end
  if P.doublesBlocked and P.doublesBlocked() then
    P.lastRect=nil
    P.shot=nil
    return
  end
  -- Rebase26: the compositor is shared by two independently proven renderer
  -- seams. Gen1 Dramaless uses P.backend/P.eligible; Gold/Silver Stadium2
  -- Importer bypasses that world seam and uses its own live-scene eligibility.
  -- Do not require the Gen1 backend in order to display an already-rendered
  -- Gold Importer Secondary View shot.
  local worldEligible=P.backend and P.eligible(P.backend) or false
  local cbeEligible=type(P.cbeEligible)=="function" and P.cbeEligible() or false
  local goldEligible=type(P.goldImporterEligible)=="function" and P.goldImporterEligible() or false
  local importer14Eligible=type(P.importer14Eligible)=="function" and P.importer14Eligible() or false
  local randyEligible=type(P.randyEligible)=="function" and P.randyEligible() or false
  local voxelAscendantEligible=type(P.voxelAscendantEligible)=="function" and P.voxelAscendantEligible() or false
  local battleArtEligible=type(P.battleArtEligible)=="function" and P.battleArtEligible() or false
  local potatoEligible=type(P.potatoEligible)=="function" and P.potatoEligible() or false
  local dramaticEligible=type(P.dramaticEligible)=="function" and P.dramaticEligible() or false
  -- Existing mixed-provider Secondary View paths remain first choice. The new
  -- direct Importer scene is a fallback only when no established independent
  -- world/provider path is active.
  if worldEligible or cbeEligible or goldEligible or randyEligible or voxelAscendantEligible
      or battleArtEligible or potatoEligible or dramaticEligible then
    importer14Eligible=false
  end
  if not (worldEligible or cbeEligible or goldEligible or importer14Eligible or randyEligible or voxelAscendantEligible or battleArtEligible or potatoEligible or dramaticEligible) then
    P.lastRect=nil
    return
  end
  local g=love.graphics

  -- CBE: bounded portable actor and exact supported live arena visitor,
  -- draw-scheduled at ~10 fps. No second simulation or full-size target.
  if cbeEligible and not P.drag and type(P.renderCbeFrame)=="function" then
    local now=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
    local last=tonumber(P.cbePipLastRender) or -1e9
    if (not P.shot) or now-last>=0.10 then
      P.cbePipLastRender=now
      local oldShot=P.shot
      local okCBE,errCBE=pcall(P.renderCbeFrame)
      if not okCBE then
        if P.cbePipRejectStale then P.shot=nil else P.shot=oldShot end
        P.failure="CBE Secondary View draw-context error: "..tostring(errCBE)
      elseif not P.cbePipRejectStale and not P.shot and oldShot and P.persistentMode and P.persistentMode() then
        P.shot=oldShot
      end
    end
  end

  -- v1.2.5 Test18: direct Gen2 Stadium2 Importer persistent monitor.
  --
  -- Test17 proved the provider actor itself is the correct live actor, but this
  -- path still refreshed from BattleState/fixed-step. Gen2's authored attack
  -- presentation can suspend that seam, so LIVE VIEW / LIVING PORTRAIT held the
  -- last PiP canvas until the attack ended. Refresh the SAME read-only borrowed
  -- live actor + secondary camera from wall-clock draw time instead. No actor
  -- update/play/attack is called here; Importer remains the sole animation owner.
  -- DYNAMIC (DW3) is deliberately left on its old fixed-step phase-gated path.
  if goldEligible and P.persistentMode and P.persistentMode()
      and P.constantArmed==true and not P.drag
      and type(P.renderGoldImporterFrame)=="function" then
    local now=((love and love.timer and love.timer.getTime)
      and love.timer.getTime() or os.clock())
    local last=tonumber(P.goldImporterConstantLastRender) or -1e9
    if (not P.shot) or now-last>=0.10 then
      P.goldImporterConstantLastRender=now
      local prevCanvas={}
      if type(g.getCanvas)=="function" then
        local okPrev,a,b,c,d=pcall(g.getCanvas)
        if okPrev and a~=nil then prevCanvas={a,b,c,d} end
      end
      local pushed=false
      if type(g.push)=="function" then pushed=pcall(g.push,"all") end
      local oldShot=P.shot
      local okGI,errGI=pcall(P.renderGoldImporterFrame)
      if pushed and type(g.pop)=="function" then pcall(g.pop) end
      if #prevCanvas>0 then pcall(g.setCanvas,(table.unpack or unpack)(prevCanvas))
      else pcall(g.setCanvas) end
      if not okGI then
        P.shot=oldShot
        P.failure="Gold Stadium2 Importer persistent draw-context error: "..tostring(errGI)
      elseif not P.shot and oldShot then
        -- Retry safety only. Normal attack/faint frames are fresh redraws; this
        -- fallback covers only a transient provider/render exception.
        P.shot=oldShot
      end
    end
  end

  -- Stadium2 Importer 0.14 direct Gen1: render the provider-owned scene from
  -- the draw seam. LIVE VIEW / LIVING PORTRAIT use a wall-clock ~10 fps monitor;
  -- DYNAMIC consumes the fixed-step due mark above.
  if importer14Eligible and not P.drag and type(P.renderImporter14Frame)=="function" then
    local persistent=P.persistentMode and P.persistentMode() and P.constantArmed==true
    local due=false
    if persistent then
      local now=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
      local last=tonumber(P.importer14ConstantLastRender) or -1e9
      if (not P.shot) or now-last>=0.10 then
        P.importer14ConstantLastRender=now; due=true
      end
    elseif P.importer14RenderDue or not P.shot then
      P.importer14RenderDue=false; due=true
    end
    if due then
      local prevCanvas={}
      if type(g.getCanvas)=="function" then
        local okPrev,a,b,c,d=pcall(g.getCanvas)
        if okPrev and a~=nil then prevCanvas={a,b,c,d} end
      end
      local pushed=false
      if type(g.push)=="function" then pushed=pcall(g.push,"all") end
      local oldShot=P.shot
      local okImp,errImp=pcall(P.renderImporter14Frame)
      if pushed and type(g.pop)=="function" then pcall(g.pop) end
      if #prevCanvas>0 then pcall(g.setCanvas,(table.unpack or unpack)(prevCanvas)) else pcall(g.setCanvas) end
      if not okImp then
        if persistent then P.shot=oldShot else P.shot=nil end
        P.failure="Importer 0.14 draw-context error: "..tostring(errImp)
      elseif persistent and not P.shot and oldShot then
        P.shot=oldShot
      end
    end
  end

  -- v1.2.4 Test24: Dramaless' private VoxelBattleScene used to execute directly
  -- from the fixed-step/update hook. Keep Test23's bounded private resolution,
  -- independent canvas slots and actor bridge, with all expensive work here in
  -- the graphics/HUD seam. Test46 gives CONSTANT its own wall-clock ~10 fps
  -- refresh so battle simulation phases cannot stop the monitor. DYNAMIC retains
  -- Test24's accepted fixed-step due marks unchanged.
  if worldEligible and not P.drag and type(P.renderFrame)=="function" then
    local constantDR=P.persistentMode and P.persistentMode() and P.constantArmed==true
    local due=false
    if constantDR then
      local now=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
      local last=tonumber(P.dramalessConstantLastRender) or -1e9
      if (not P.shot) or now-last>=0.10 then
        P.dramalessConstantLastRender=now
        due=true
      end
    elseif P.dramalessRenderDue or not P.shot then
      P.dramalessRenderDue=false
      due=true
    end
    if due then
      local prevCanvas={}
      if type(g.getCanvas)=="function" then
        local okPrev,a,b,c,d=pcall(g.getCanvas)
        if okPrev and a~=nil then prevCanvas={a,b,c,d} end
      end
      local pushed=false
      if type(g.push)=="function" then pushed=pcall(g.push,"all") end
      local oldShot=P.shot
      local okDR,errDR=pcall(P.renderFrame)
      if pushed and type(g.pop)=="function" then pcall(g.pop) end
      if #prevCanvas>0 then pcall(g.setCanvas,(table.unpack or unpack)(prevCanvas))
      else pcall(g.setCanvas) end
      if not okDR then
        if constantDR then P.shot=oldShot else P.shot=nil end
        P.failure="Dramaless draw-context error: "..tostring(errDR)
      elseif constantDR and not P.shot and oldShot then
        -- Transient provider/render exceptions are retried on the next wall-clock
        -- tick; they do not define normal CONSTANT freeze semantics.
        P.shot=oldShot
      end
    end
  end

  -- Rebase30: Randy's provider-native VoxelScene alternate-eye renderer must
  -- execute from a DRAW seam.  Rebase27-29 invoked it from BattleState.update;
  -- terrain prefetch could succeed there, but VoxelScene.render kept returning
  -- nil before either the 3D Stadium actor or 2D card could be submitted.
  --
  -- Preserve the HUD's current render target around Randy's pass because
  -- Voxel3D.endScene intentionally unbinds its own canvas.  The provider's
  -- internal camera/world/card state is restored by renderRandyFrame itself.
  -- Rebase39 Voxel Ascendant uses its published VoxelScene/Voxel3D facade and
  -- therefore also executes from a real draw context. Its fixed-step path only
  -- marks frames due.
  if voxelAscendantEligible and not P.drag and type(P.renderVoxelAscendantFrame)=="function" then
    local constantVA=P.persistentMode and P.persistentMode() and P.constantArmed==true
    local due=false
    if constantVA then
      local now=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
      local last=tonumber(P.voxelAscendantConstantLastRender) or -1e9
      if (not P.shot) or now-last>=0.10 then
        P.voxelAscendantConstantLastRender=now; due=true
      end
    elseif P.voxelAscendantRenderDue or not P.shot then
      P.voxelAscendantRenderDue=false; due=true
    end
    if due then
      local oldShot=P.shot
      local okVA,errVA=pcall(P.renderVoxelAscendantFrame)
      if not okVA then
        if constantVA then P.shot=oldShot else P.shot=nil end
        P.failure="Voxel Ascendant MAP draw-context error: "..tostring(errVA)
      elseif constantVA and not P.shot and oldShot then
        P.shot=oldShot
      end
    end
  end

  -- Rebase38 Battle Art world: render only from this draw seam and throttle
  -- independently of the main staged battle. No provider ownership transfer.
  if battleArtEligible and type(P.renderBattleArtFrame)=="function" then
    local now=((love and love.timer and love.timer.getTime)
      and love.timer.getTime() or os.clock())
    local last=tonumber(P.battleArtLastRender) or -1e9
    if (not P.shot) or now-last>=0.10 then
      P.battleArtLastRender=now
      local constantBA=P.persistentMode and P.persistentMode()
        and P.constantArmed==true and P.battleArtImporterEnabled()
      local oldShot=P.shot
      local okBA,errBA=pcall(P.renderBattleArtFrame)
      if not okBA then
        if constantBA then P.shot=oldShot else P.shot=nil end
        P.failure="Battle Art Rebase38 draw-context error: "..tostring(errBA)
      elseif constantBA and not P.shot and oldShot then
        -- Retry safety only; normal CONSTANT semantics still render every state,
        -- including a genuinely empty player side.
        P.shot=oldShot
      end
    end
  end

  -- Rebase58 Dramatic 1.6.x: execute the private Secondary View render only
  -- from this HUD/draw seam. Preserve the caller's graphics state/canvas around
  -- the provider pass; older Dramatic was not designed to render a second scene
  -- from BattleState.update, and doing so caused gameplay/input stalls on Android.
  if dramaticEligible and not P.drag and type(P.renderDramaticFrame)=="function" then
    local constantDR=P.persistentMode and P.persistentMode() and P.constantArmed==true
    local due=false
    if constantDR then
      local now=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
      local last=tonumber(P.dramaticConstantLastRender) or -1e9
      if (not P.shot) or now-last>=0.10 then
        P.dramaticConstantLastRender=now; due=true
      end
    elseif P.dramaticRenderDue or not P.shot then
      P.dramaticRenderDue=false; due=true
    end
    if due then
      local prevCanvas={}
      if type(g.getCanvas)=="function" then
        local okPrev,a,b,c,d=pcall(g.getCanvas)
        if okPrev and a~=nil then prevCanvas={a,b,c,d} end
      end
      local pushed=false
      if type(g.push)=="function" then pushed=pcall(g.push,"all") end
      local oldShot=P.shot
      local okDR,errDR=pcall(P.renderDramaticFrame)
      if pushed and type(g.pop)=="function" then pcall(g.pop) end
      if #prevCanvas>0 then pcall(g.setCanvas,(table.unpack or unpack)(prevCanvas))
      else pcall(g.setCanvas) end
      if not okDR then
        if constantDR then P.shot=oldShot else P.shot=nil end
        P.failure="Dramatic draw-context error: "..tostring(errDR)
      elseif constantDR and not P.shot and oldShot then
        -- Retry safety only; normal CONSTANT semantics render attack/faint/vacancy.
        P.shot=oldShot
      end
    end
  end

  -- Test43 Potato + Importer CONSTANT: one continuously running bounded monitor.
  -- Refresh from wall-clock draw time (~10 fps), independent of battle phases.
  -- A transient render failure keeps the last successful canvas while retrying.
  if potatoEligible and P.persistentMode and P.persistentMode()
      and P.constantArmed==true and not P.drag
      and type(P.renderPotatoFrame)=="function" then
    local now=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
    local last=tonumber(P.potatoConstantLastRender) or -1e9
    if (not P.shot) or now-last>=0.10 then
      P.potatoConstantLastRender=now
      local prevCanvas={}
      if type(g.getCanvas)=="function" then
        local okPrev,a,b,c,d=pcall(g.getCanvas)
        if okPrev and a~=nil then prevCanvas={a,b,c,d} end
      end
      local pushed=false
      if type(g.push)=="function" then pushed=pcall(g.push,"all") end
      local oldShot=P.shot
      local okPV,errPV=pcall(P.renderPotatoFrame)
      if pushed and type(g.pop)=="function" then pcall(g.pop) end
      if #prevCanvas>0 then pcall(g.setCanvas,(table.unpack or unpack)(prevCanvas))
      else pcall(g.setCanvas) end
      if not okPV then
        P.shot=oldShot
        P.failure="Potato CONSTANT retry: "..tostring(errPV)
      elseif not P.shot and oldShot then
        P.shot=oldShot
      end
    end
  end

  if randyEligible then
    local gold=backends.__gold
    local constantVU=gold and gold.providerKind=="voxel_ultimate"
      and P.persistentMode and P.persistentMode() and P.constantArmed==true
    local constantRandy=gold and gold.providerKind=="randy"
      and P.persistentMode and P.persistentMode() and P.constantArmed==true
    local due=P.randyRenderDue or not P.shot
    if constantVU or constantRandy then
      local now=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
      local last=constantVU and (tonumber(P.voxelUltimateConstantLastRender) or -1e9)
        or (tonumber(P.randyConstantLastRender) or -1e9)
      due=(not P.shot) or now-last>=0.10
      if due then
        if constantVU then P.voxelUltimateConstantLastRender=now
        else P.randyConstantLastRender=now end
      end
    end
    if due then
      P.randyRenderDue=false
      local prevCanvas=nil
      if type(g.getCanvas)=="function" then
        local okPrev,value=pcall(g.getCanvas)
        if okPrev then prevCanvas=value end
      end
      local oldShot=P.shot
      local okRender,errRender=pcall(P.renderRandyFrame)
      if prevCanvas~=nil then pcall(g.setCanvas,prevCanvas)
      else pcall(g.setCanvas) end
      if not okRender then
        if constantVU or constantRandy then P.shot=oldShot else P.shot=nil end
        P.failure=(constantVU and "Voxel Ultimate CONSTANT draw-context error: "
          or constantRandy and "Randy CONSTANT draw-context error: "
          or "Randy Secondary View draw-context error: ")..tostring(errRender)
      elseif constantVU and not P.shot and oldShot then
        -- VU retry safety retained exactly. Randy normal vacancy is accepted as
        -- a newly rendered actor-free world and is not converted to a frozen card.
        P.shot=oldShot
      end
    end
  end
  local pushed=false
  local frameMesh=nil
  local ok,err=pcall(function()
    local sw,sh=g.getDimensions(); local sizeMode=mod.options:get("secondaryViewSize") or "standard"; local frac=(sizeMode=="small") and 0.20 or 0.27; local minW=(sizeMode=="small") and 132 or 180; local targetW=math.max(minW,math.floor(sw*frac)); local targetH=math.min(sh*0.34,targetW*9/16); local x,y=P.placementXY(sw,sh,targetW,targetH)
    P.lastRect={x=x-6,y=y-6,w=targetW+12,h=targetH+12,sw=sw,sh=sh,targetW=targetW,targetH=targetH}
    g.push("all"); pushed=true; g.origin(); g.setBlendMode("alpha")
    local canvas=P.shot and P.shot.canvas or nil
    local angled=(mod.options:get("secondaryViewFrameStyle") or "colosseum")=="colosseum"
    local mesh=angled and canvas and P.cutFrameMesh(g,targetW,targetH,canvas) or nil
    frameMesh=mesh
    -- A missing mesh capability must not blank a working PiP. Fall back only
    -- for this frame to the established rounded compositor; preferences remain.
    if angled and canvas and not mesh then angled=false end
    local cut=math.min(targetW,targetH)*8/78
    local expand=2-math.sqrt(2) -- parallel 45-degree inset/outset, not stretched cuts
    g.setColor(0,0,0,0.78)
    if angled then P.drawCutFrameRect(g,"fill",x-6,y-6,targetW+12,targetH+12,cut+6*expand)
    else g.rectangle("fill",x-6,y-6,targetW+12,targetH+12,5,5) end
    if canvas then
      local cw,ch=canvas:getDimensions(); g.setColor(1,1,1,1)
      if mesh then
        if type(g.setMeshCullMode)=="function" then g.setMeshCullMode("none") end
        g.draw(mesh,x,y)
      else g.draw(canvas,x,y,0,targetW/cw,targetH/ch) end
    else
      g.setColor(1,1,1,0.23)
      if angled then P.drawCutFrameRect(g,"fill",x,y,targetW,targetH,cut)
      else g.rectangle("fill",x,y,targetW,targetH) end
      g.setColor(1,1,1,1); g.setLineWidth(4); g.line(x+12,y+12,x+targetW-12,y+targetH-12); g.line(x+targetW-12,y+12,x+12,y+targetH-12)
      local flags=("SC:%s V3:%s AA:%s AR:%s CARD:%s SB:%s"):format(P.diagScene and "Y" or "N",P.diagV3 and "Y" or "N",P.diagAA and "Y" or "N",P.diagArena and "Y" or "N",P.diagCard and "Y" or "N",P.diagSB and "Y" or "N")
      local counts=("FIX:%d RF:%d EL:%d TRY:%d ACT:%d"):format(P.fixedStepCalls or 0,P.renderFrameCalls or 0,P.eligibleFrames or 0,P.renderAttempts or 0,P.actorDraws or 0)
      g.print(tostring(P.failure or P.status),x+8,y+6,0,0.50,0.50); g.print(flags,x+8,y+21,0,0.43,0.43); g.print(counts,x+8,y+35,0,0.43,0.43); g.print("DR:"..tostring(P.diagVersion or "?").." ACT:"..tostring(P.actorMode or "?").." SBFX:"..tostring(P.sbfxVersion or "?"),x+8,y+49,0,0.43,0.43)
    end
    local borderStyle=mod.options:get("secondaryViewBorder") or "colosseum_grey"
    if borderStyle=="dark" then g.setColor(0.06,0.07,0.09,1)
    -- Exact opaque portraitPod metal / portraitPodOverlay lip colour from the
    -- supplied Colosseum Inspired UI Overhaul 1.1.0, not its menu GRAY swatch.
    elseif borderStyle=="colosseum_grey" then g.setColor(0.30,0.32,0.30,1)
    else g.setColor(1,1,1,1) end
    g.setLineWidth(3)
    if angled then P.drawCutFrameRect(g,"line",x-3,y-3,targetW+6,targetH+6,cut+3*expand)
    else g.rectangle("line",x-3,y-3,targetW+6,targetH+6,4,4) end
  end)
  -- Release the borrowed canvas even after a draw failure; cache geometry only.
  if frameMesh then pcall(frameMesh.setTexture,frameMesh) end
  -- Always restore graphics state, including error paths. The old pcall could
  -- swallow an exception after push("all") and leave later UI draws transformed.
  if pushed then pcall(g.pop) end
  g.setColor(1,1,1,1)
  if not ok then
    P.failure="PiP draw error: "..tostring(err)
    mod.log:warn("Secondary View compositor draw failed: %s",tostring(err))
  end

end

-- v1.2.5 Test1 Android-visible event-mirror diagnostic -------------------------
-- Enabled only through BC's existing DIAGNOSTICS option. It compares the live
-- Importer Actor's authoritative Stadium pose with the private PiP renderer pose
-- sampled for the same Secondary View frame.
state.secondaryViewProbe.drawEventMirrorOverlay=function()
  local P=state.secondaryViewProbe
  if not (P and mod.options:get("diagnostics")=="on" and love and love.graphics) then return end
  if (mod.options:get("secondaryView") or "off")~="on" or not state.battle then return end

  local d=P.eventMirrorDiag
  local g=love.graphics
  local now=((love and love.timer and love.timer.getTime) and love.timer.getTime() or os.clock())
  local live=d and d.live or nil
  local pip=d and d.pip or nil

  -- Cheap current-live sample for diagnosing perceived lag between 10 fps
  -- private refreshes. This does not mutate/borrow the provider actor.
  local currentLive=nil
  if type(P.dramalessImporterLivePresentation)=="function" then
    local okKnown,known,present,actor,visual=pcall(P.dramalessImporterLivePresentation)
    if okKnown and known and type(actor)=="table" and type(actor.renderer)=="table" then
      local r=actor.renderer
      currentLive={context=tostring(actor.context or "?"),index=r.animIndex,
        frame=r.frame,time=r.time,visual=visual}
    end
  end

  local function yn(v) return v and "Y" or "N" end
  local function n(v,fmt)
    v=tonumber(v); if not v then return "?" end
    return string.format(fmt or "%.3f",v)
  end
  local sameAnim=live and pip and tonumber(live.index)==tonumber(pip.index)
  local df=live and pip and tonumber(live.frame) and tonumber(pip.frame)
    and math.abs(tonumber(live.frame)-tonumber(pip.frame)) or nil
  local dt=live and pip and tonumber(live.time) and tonumber(pip.time)
    and math.abs(tonumber(live.time)-tonumber(pip.time)) or nil
  local ageMs=d and tonumber(d.sampleWall) and math.max(0,(now-tonumber(d.sampleWall))*1000) or nil
  local liveNowDelta=currentLive and pip and tonumber(currentLive.time) and tonumber(pip.time)
    and math.abs(tonumber(currentLive.time)-tonumber(pip.time)) or nil

  local lines={
    "BC 1.2.5 T2 EVENT MIRROR  armed="..yn(P.constantArmed==true)
      .." arm="..tostring(P.constantArmSource or "-")
      .." mode="..tostring(d and d.mode or "WAIT"),
    "LIVE NOW ctx="..tostring(currentLive and currentLive.context or "?")
      .." anim="..tostring(currentLive and currentLive.index or "?")
      .." frame="..tostring(currentLive and currentLive.frame or "?")
      .." t="..n(currentLive and currentLive.time),
    "SHOT     ctx="..tostring(live and live.context or "?")
      .." anim="..tostring(live and live.index or "?")
      .." frame="..tostring(live and live.frame or "?")
      .." t="..n(live and live.time)
      .." age="..n(ageMs,"%.0f").."ms",
    "PIP      anim="..tostring(pip and pip.index or "?")
      .." frame="..tostring(pip and pip.frame or "?")
      .." t="..n(pip and pip.time),
    "AT SAMPLE anim="..yn(sameAnim).." dFrame="..n(df,"%.0f")
      .." dTime="..n(dt).."  NOW->PIP="..n(liveNowDelta)
      .." render="..n(P.eventMirrorRenderMs,"%.1f").."ms",
  }

  -- Deliberately use the already-active HUD font: Test1's draw-context font
  -- allocation could fail silently on Android and hide the entire diagnostic.
  local ok=pcall(function()
    g.push("all"); g.origin()
    local font=(type(g.getFont)=="function") and g.getFont() or nil
    local width=0
    if font and type(font.getWidth)=="function" then
      for _,line in ipairs(lines) do width=math.max(width,font:getWidth(line)) end
    else
      width=620
    end
    local x,y=8,76
    local lineH=14
    g.setColor(0,0,0,.88); g.rectangle("fill",x,y,width+12,#lines*lineH+8,4,4)
    g.setColor(1,1,1,1)
    for i,line in ipairs(lines) do g.print(line,x+6,y+4+(i-1)*lineH,0,0.72,0.72) end
    g.pop()
  end)
  if not ok then pcall(g.setColor,1,1,1,1) end
end

-- v1.2.5 Test17 Gen2 LIVE VIEW diagnostic ------------------------------------
-- Android has no useful Recomp log workflow. Keep this invisible unless the
-- existing DIAGNOSTICS option is ON; it reports only read-only provider state.
state.secondaryViewProbe.drawGen2LiveOverlay=function()
  local P=state.secondaryViewProbe
  local gold=backends.__gold
  if not (P and gold and (gold.providerKind=="randy" or gold.providerKind=="voxel_ultimate")
      and mod.options:get("diagnostics")=="on"
      and P.liveViewMode and P.liveViewMode()
      and love and love.graphics) then return end
  local g=love.graphics
  local provider=(gold.providerKind=="voxel_ultimate") and "VOXEL ULTIMATE" or "STADIUM2 OVERWORLD MODELS"
  local line=("G2 LIVE %s  ctx=%s anim=%s scale=%s draw=%s  ok=%d/%d frames=%d"):format(
    provider,tostring(P.gen2LiveContextSource or "?"),tostring(P.gen2LiveAnim or "?"),
    tostring(P.gen2LiveScale or "?"),P.gen2LiveDirectDraw and "Y" or "N",
    tonumber(P.gen2LiveDrawSuccess) or 0,tonumber(P.gen2LiveDrawAttempts) or 0,
    tonumber(P.frames) or 0)
  pcall(function()
    g.push("all"); g.origin()
    local f=g.getFont and g.getFont() or nil
    local w=(f and f.getWidth and f:getWidth(line)) or 700
    g.setColor(0,0,0,.82); g.rectangle("fill",8,58,w+12,20,3,3)
    g.setColor(1,1,1,1); g.print(line,14,62,0,.62,.62)
    g.pop()
  end)
end

-- Direct Secondary View placement ------------------------------------------------
-- Current Recomp exposes uncaptured touch/mouse input through input.pointer.
-- TouchControls keeps first refusal, so dragging the PiP cannot steal a press
-- that began on the virtual D-pad / A / B / Start / Select controls.
do
  local P=state.secondaryViewProbe
  local okPointer=pcall(function()
    mod.hooks:wrap("input.pointer",function(nextFn,game,ev)
      local worldEligible=P and P.backend and P.eligible(P.backend) or false
      local cbeEligible=P and type(P.cbeEligible)=="function" and P.cbeEligible() or false
      local goldEligible=P and type(P.goldImporterEligible)=="function" and P.goldImporterEligible() or false
      local importer14Eligible=P and type(P.importer14Eligible)=="function" and P.importer14Eligible() or false
      local randyEligible=P and type(P.randyEligible)=="function" and P.randyEligible() or false
      local voxelAscendantEligible=P and type(P.voxelAscendantEligible)=="function" and P.voxelAscendantEligible() or false
      local battleArtEligible=P and type(P.battleArtEligible)=="function" and P.battleArtEligible() or false
      local potatoEligible=P and type(P.potatoEligible)=="function" and P.potatoEligible() or false
      local dramaticEligible=P and type(P.dramaticEligible)=="function" and P.dramaticEligible() or false
      local interactionOk=type(P.interactionLifecycleEligible)=="function" and P.interactionLifecycleEligible() or false
      if not (P and ev and P.lastRect and interactionOk
          and (worldEligible or cbeEligible or goldEligible or importer14Eligible or randyEligible or voxelAscendantEligible or battleArtEligible or potatoEligible or dramaticEligible)) then
        return nextFn(game,ev)
      end

      local d=P.drag
      local id=ev.id
      if ev.phase=="pressed" then
        local r=P.lastRect
        local x,y=tonumber(ev.x),tonumber(ev.y)
        if x and y and x>=r.x and x<=r.x+r.w and y>=r.y and y<=r.y+r.h then
          P.drag={
            id=id, startX=x, startY=y, pointerX=x, pointerY=y,
            originX=r.x+6, originY=r.y+6,
            offsetX=x-(r.x+6), offsetY=y-(r.y+6),
            x=r.x+6, y=r.y+6, active=false
          }
          return true
        end
      elseif d and d.id==id then
        if ev.phase=="moved" then
          local x,y=tonumber(ev.x) or d.pointerX,tonumber(ev.y) or d.pointerY
          d.pointerX,d.pointerY=x,y
          if not d.active then
            local dx,dy=x-d.startX,y-d.startY
            if dx*dx+dy*dy>=16 then d.active=true end
          end
          if d.active then
            local r=P.lastRect
            local maxX=math.max(0,(r.sw or 0)-(r.targetW or 0))
            local maxY=math.max(0,(r.sh or 0)-(r.targetH or 0))
            d.x=math.max(0,math.min(maxX,x-d.offsetX))
            d.y=math.max(0,math.min(maxY,y-d.offsetY))
          end
          return true
        elseif ev.phase=="released" or ev.phase=="cancelled" then
          if ev.phase=="released" and d.active then
            local r=P.lastRect
            local maxX=math.max(1,(r.sw or 1)-(r.targetW or 0))
            local maxY=math.max(1,(r.sh or 1)-(r.targetH or 0))
            local nx=math.floor(math.max(0,math.min(1,(d.x or 0)/maxX))*1000+0.5)
            local ny=math.floor(math.max(0,math.min(1,(d.y or 0)/maxY))*1000+0.5)
            local set=P.setOption
            if type(set)=="function" then
              set(game,"secondaryViewCustomX",nx)
              set(game,"secondaryViewCustomY",ny)
              set(game,"secondaryViewPlace","custom")
            end
          end
          P.drag=nil
          return true
        end
      end
      return nextFn(game,ev)
    end)
  end)
  if okPointer then
    mod.log:info("Secondary View direct-drag placement attached through input.pointer")
  else
    mod.log:warn("Secondary View direct-drag unavailable on this Recomp build; placement presets remain supported")
  end
end

-- v1.4.1 desktop mouse PiP drag bridge -------------------------------------
-- input.pointer is the preferred unified seam, but historical desktop validation
-- exposed that a physical mouse gesture was not reliably completing through that
-- hook on every supported Recomp frontend.  Capture only a mouse gesture that
-- BEGINS inside the already-drawn PiP, at Game/Game2 method level, and leave every
-- other mouse event untouched.  This is provider-neutral compositor interaction;
-- it does not depend on the active Secondary View renderer/backend.
do
  local P=state.secondaryViewProbe
  local function interactionEligible()
    -- Desktop mouse ownership follows the compositor: if the PiP is visibly
    -- drawn this frame, a primary-button gesture that begins inside it belongs
    -- to the PiP even when a provider has switched the main battle into its own
    -- mouse/manual camera state. Touch keeps the stricter passive-lifecycle gate
    -- in input.pointer so virtual battle controls are never stolen.
    return P and P.lastRect~=nil
  end
  local function beginMouseDrag(x,y,button)
    if not interactionEligible() then return false end
    -- Primary-button drag only. Do not steal secondary/context mouse actions.
    if button~=nil and tonumber(button)~=1 then return false end
    x,y=tonumber(x),tonumber(y)
    local r=P.lastRect
    if not (x and y and x>=r.x and x<=r.x+r.w and y>=r.y and y<=r.y+r.h) then
      return false
    end
    P.drag={
      id="mouse",startX=x,startY=y,pointerX=x,pointerY=y,
      originX=r.x+6,originY=r.y+6,
      offsetX=x-(r.x+6),offsetY=y-(r.y+6),
      x=r.x+6,y=r.y+6,active=false,directMouse=true
    }
    return true
  end
  local function moveMouseDrag(x,y)
    local d=P and P.drag
    if not (d and d.directMouse and d.id=="mouse") then return false end
    x,y=tonumber(x) or d.pointerX,tonumber(y) or d.pointerY
    d.pointerX,d.pointerY=x,y
    if not d.active then
      local dx,dy=x-d.startX,y-d.startY
      if dx*dx+dy*dy>=16 then d.active=true end
    end
    if d.active and P.lastRect then
      local r=P.lastRect
      local maxX=math.max(0,(r.sw or 0)-(r.targetW or 0))
      local maxY=math.max(0,(r.sh or 0)-(r.targetH or 0))
      d.x=math.max(0,math.min(maxX,x-d.offsetX))
      d.y=math.max(0,math.min(maxY,y-d.offsetY))
    end
    return true
  end
  local function endMouseDrag(game,released,button)
    local d=P and P.drag
    if not (d and d.directMouse and d.id=="mouse") then return false end
    if button~=nil and tonumber(button)~=1 then return false end
    if released and d.active and P.lastRect then
      local r=P.lastRect
      local maxX=math.max(1,(r.sw or 1)-(r.targetW or 0))
      local maxY=math.max(1,(r.sh or 1)-(r.targetH or 0))
      local nx=math.floor(math.max(0,math.min(1,(d.x or 0)/maxX))*1000+0.5)
      local ny=math.floor(math.max(0,math.min(1,(d.y or 0)/maxY))*1000+0.5)
      if type(P.setOption)=="function" then
        P.setOption(game,"secondaryViewCustomX",nx)
        P.setOption(game,"secondaryViewCustomY",ny)
        P.setOption(game,"secondaryViewPlace","custom")
      end
    end
    P.drag=nil
    return true
  end

  local function installGameMouseBridge(GameClass,label)
    if type(GameClass)~="table" or GameClass.__bcSecondaryViewMouseDrag then return false end
    local installed=false
    local pressed=GameClass.mousepressed
    if type(pressed)=="function" then
      GameClass.mousepressed=function(self,x,y,button,istouch,...)
        if not istouch and beginMouseDrag(x,y,button) then return true end
        return pressed(self,x,y,button,istouch,...)
      end
      installed=true
    end
    local moved=GameClass.mousemoved
    if type(moved)=="function" then
      GameClass.mousemoved=function(self,x,y,dx,dy,istouch,...)
        if not istouch and moveMouseDrag(x,y) then return true end
        return moved(self,x,y,dx,dy,istouch,...)
      end
      installed=true
    end
    local released=GameClass.mousereleased
    if type(released)=="function" then
      GameClass.mousereleased=function(self,x,y,button,istouch,...)
        if not istouch and endMouseDrag(self,true,button) then return true end
        return released(self,x,y,button,istouch,...)
      end
      installed=true
    end
    local focus=GameClass.focus
    if type(focus)=="function" then
      GameClass.focus=function(self,...)
        if P.drag and P.drag.directMouse then P.drag=nil end
        return focus(self,...)
      end
    end
    if installed then
      GameClass.__bcSecondaryViewMouseDrag=true
      mod.log:info("Secondary View direct desktop mouse drag bridge active ("..tostring(label)..")")
    end
    return installed
  end

  local okGame,GameClass=pcall(require,"src.core.Game")
  if okGame then installGameMouseBridge(GameClass,"Game") end
  local okGame2,Game2Class=pcall(require,"src.core.Game2")
  if okGame2 then installGameMouseBridge(Game2Class,"Game2") end
end


-- v1.4.1 late outer desktop mouse capture ---------------------------------
-- Some 3D presentation hosts install their own LOVE-level mouse steering after
-- BC's Game/input.pointer bridges.  In those stacks the provider is entitled to
-- keep mouse-look everywhere EXCEPT a primary-button gesture that begins inside
-- BC's already-drawn PiP.  Install a tiny forwarding outer wrapper late from
-- input.step: outside the PiP it delegates byte-for-byte to whichever provider
-- currently owns love.mouse*; during an active PiP drag it temporarily consumes
-- motion/release so the provider camera pauses, then resumes on the next event.
-- This is deliberately NOT a provider-specific camera override.
do
  local P=state.secondaryViewProbe
  local bridge={}

  local function interactionEligible()
    -- Desktop mouse ownership follows the compositor: if the PiP is visibly
    -- drawn this frame, a primary-button gesture that begins inside it belongs
    -- to the PiP even when a provider has switched the main battle into its own
    -- mouse/manual camera state. Touch keeps the stricter passive-lifecycle gate
    -- in input.pointer so virtual battle controls are never stolen.
    return P and P.lastRect~=nil
  end

  local function beginDrag(x,y,button)
    if not interactionEligible() then return false end
    if button~=nil and tonumber(button)~=1 then return false end
    x,y=tonumber(x),tonumber(y)
    local r=P.lastRect
    if not (x and y and x>=r.x and x<=r.x+r.w and y>=r.y and y<=r.y+r.h) then
      return false
    end
    P.drag={
      id="mouse",startX=x,startY=y,pointerX=x,pointerY=y,
      originX=r.x+6,originY=r.y+6,
      offsetX=x-(r.x+6),offsetY=y-(r.y+6),
      x=r.x+6,y=r.y+6,active=false,directMouse=true,loveOuter=true
    }
    return true
  end

  local function moveDrag(x,y)
    local d=P and P.drag
    if not (d and d.directMouse and d.id=="mouse") then return false end
    x,y=tonumber(x) or d.pointerX,tonumber(y) or d.pointerY
    d.pointerX,d.pointerY=x,y
    if not d.active then
      local dx,dy=x-d.startX,y-d.startY
      if dx*dx+dy*dy>=16 then d.active=true end
    end
    if d.active and P.lastRect then
      local r=P.lastRect
      local maxX=math.max(0,(r.sw or 0)-(r.targetW or 0))
      local maxY=math.max(0,(r.sh or 0)-(r.targetH or 0))
      d.x=math.max(0,math.min(maxX,x-d.offsetX))
      d.y=math.max(0,math.min(maxY,y-d.offsetY))
    end
    return true
  end

  local function endDrag(released,button)
    local d=P and P.drag
    if not (d and d.directMouse and d.id=="mouse") then return false end
    if button~=nil and tonumber(button)~=1 then return false end
    if released and d.active and P.lastRect then
      local r=P.lastRect
      local maxX=math.max(1,(r.sw or 1)-(r.targetW or 0))
      local maxY=math.max(1,(r.sh or 1)-(r.targetH or 0))
      local nx=math.floor(math.max(0,math.min(1,(d.x or 0)/maxX))*1000+0.5)
      local ny=math.floor(math.max(0,math.min(1,(d.y or 0)/maxY))*1000+0.5)
      if type(P.setOption)=="function" then
        local game=bridge.game
        P.setOption(game,"secondaryViewCustomX",nx)
        P.setOption(game,"secondaryViewCustomY",ny)
        P.setOption(game,"secondaryViewPlace","custom")
      end
    end
    P.drag=nil
    return true
  end

  local function ensureLoveMouseOuter()
    if not (love and type(love)=="table") then return end

    if love.mousepressed~=bridge.pressed then
      local inner=love.mousepressed
      local wrapper=function(x,y,button,istouch,...)
        if not istouch and beginDrag(x,y,button) then return true end
        if inner then return inner(x,y,button,istouch,...) end
      end
      bridge.pressed=wrapper
      love.mousepressed=wrapper
    end

    if love.mousemoved~=bridge.moved then
      local inner=love.mousemoved
      local wrapper=function(x,y,dx,dy,istouch,...)
        if not istouch and moveDrag(x,y) then return true end
        if inner then return inner(x,y,dx,dy,istouch,...) end
      end
      bridge.moved=wrapper
      love.mousemoved=wrapper
    end

    if love.mousereleased~=bridge.released then
      local inner=love.mousereleased
      local wrapper=function(x,y,button,istouch,...)
        if not istouch and endDrag(true,button) then return true end
        if inner then return inner(x,y,button,istouch,...) end
      end
      bridge.released=wrapper
      love.mousereleased=wrapper
    end
  end

  local okStep=pcall(function()
    mod.hooks:wrap("input.step",function(nextFn,game,dt)
      bridge.game=game or bridge.game
      ensureLoveMouseOuter()
      return nextFn(game,dt)
    end)
  end)
  if okStep then
    mod.log:info("Secondary View late outer desktop mouse capture armed")
  else
    mod.log:warn("Secondary View late outer mouse capture unavailable; existing mouse/touch placement remains")
  end
end

-- Rebase58 Dramatic 1.6.x legacy-touch bridge -----------------------------------
-- Dramatic 1.6.x predates input.pointer and wraps Game.touchpressed/moved/released
-- directly for battle-camera drags. On Android that legacy wrapper can claim an
-- open-screen finger before the newer pointer chain ever delivers BC a complete
-- press/move/release gesture. Install a Dramatic-only outer Game touch wrapper so
-- a gesture that BEGINS inside the PiP belongs to the PiP; all other touches pass
-- through untouched to Dramatic/TouchControls. This is Game-level API 2-safe input
-- handling, not a global love.* callback.
do
  local P=state.secondaryViewProbe
  local okGame,Game=pcall(require,"src.core.Game")
  if okGame and type(Game)=="table" and P and not Game.__bcSecondaryViewDramaticTouchDrag then
    local function eligible()
      return type(P.dramaticEligible)=="function" and P.dramaticEligible()
    end
    local function beginDrag(id,x,y)
      if not (eligible() and P.lastRect) then return false end
      x,y=tonumber(x),tonumber(y)
      local r=P.lastRect
      if not (x and y and x>=r.x and x<=r.x+r.w and y>=r.y and y<=r.y+r.h) then return false end
      P.drag={
        id=id,startX=x,startY=y,pointerX=x,pointerY=y,
        originX=r.x+6,originY=r.y+6,
        offsetX=x-(r.x+6),offsetY=y-(r.y+6),
        x=r.x+6,y=r.y+6,active=false,legacyDramatic=true
      }
      return true
    end
    local function moveDrag(id,x,y)
      local d=P.drag
      if not (d and d.id==id and d.legacyDramatic) then return false end
      x,y=tonumber(x) or d.pointerX,tonumber(y) or d.pointerY
      d.pointerX,d.pointerY=x,y
      if not d.active then
        local dx,dy=x-d.startX,y-d.startY
        if dx*dx+dy*dy>=16 then d.active=true end
      end
      if d.active and P.lastRect then
        local r=P.lastRect
        local maxX=math.max(0,(r.sw or 0)-(r.targetW or 0))
        local maxY=math.max(0,(r.sh or 0)-(r.targetH or 0))
        d.x=math.max(0,math.min(maxX,x-d.offsetX))
        d.y=math.max(0,math.min(maxY,y-d.offsetY))
      end
      return true
    end
    local function endDrag(game,id,released)
      local d=P.drag
      if not (d and d.id==id and d.legacyDramatic) then return false end
      if released and d.active and P.lastRect then
        local r=P.lastRect
        local maxX=math.max(1,(r.sw or 1)-(r.targetW or 0))
        local maxY=math.max(1,(r.sh or 1)-(r.targetH or 0))
        local nx=math.floor(math.max(0,math.min(1,(d.x or 0)/maxX))*1000+0.5)
        local ny=math.floor(math.max(0,math.min(1,(d.y or 0)/maxY))*1000+0.5)
        if type(P.setOption)=="function" then
          P.setOption(game,"secondaryViewCustomX",nx)
          P.setOption(game,"secondaryViewCustomY",ny)
          P.setOption(game,"secondaryViewPlace","custom")
        end
      end
      P.drag=nil
      return true
    end

    local pressed=Game.touchpressed
    if type(pressed)=="function" then
      Game.touchpressed=function(self,id,x,y,...)
        if beginDrag(id,x,y) then return true end
        return pressed(self,id,x,y,...)
      end
    end
    local moved=Game.touchmoved
    if type(moved)=="function" then
      Game.touchmoved=function(self,id,x,y,...)
        if moveDrag(id,x,y) then return true end
        return moved(self,id,x,y,...)
      end
    end
    local released=Game.touchreleased
    if type(released)=="function" then
      Game.touchreleased=function(self,id,x,y,...)
        if endDrag(self,id,true) then return true end
        return released(self,id,x,y,...)
      end
    end
    local focus=Game.focus
    if type(focus)=="function" then
      Game.focus=function(self,...)
        if P.drag and P.drag.legacyDramatic then P.drag=nil end
        return focus(self,...)
      end
    end
    Game.__bcSecondaryViewDramaticTouchDrag=true
    mod.log:info("Secondary View Dramatic legacy Game-touch drag bridge active")
  end
end

mod.hooks:wrap("render.hud",function(nextFn,game,viewport)
  local result=nextFn(game,viewport)
  state.secondaryViewProbe.draw()
  if type(state.secondaryViewProbe.drawEventMirrorOverlay)=="function" then
    state.secondaryViewProbe.drawEventMirrorOverlay()
  end
  if type(state.secondaryViewProbe.drawGen2LiveOverlay)=="function" then
    state.secondaryViewProbe.drawGen2LiveOverlay()
  end
  state.compatibilityNotice.draw()
  return result
end)

-- Sprite Facing / Dual Actor Presentation -----------------------------------
-- Sprite Facing exposes one product surface across supported 2D-card hosts and
-- applies the same camera-relative semantics independently to BOTH battlers.
--
-- SPRITE FACING:
--   HOST DEFAULT - BC does not alter sprite representation or orientation.
--   TURN ONLY    - keep the host/provider's chosen front/back representation,
--                  but turn each world card left/right toward its opponent.
--   DYNAMIC      - camera chooses FRONT/BACK independently for each battler,
--                  while left/right turning still points each actor toward the
--                  opposing battler. Crystal keeps ownership of live front
--                  animation; Dramaless keeps ownership of world placement.
--
-- This remains a Dramaless adapter. Battle Art/3D hosts are deliberately not
-- consumed here; HOST DEFAULT is therefore a safe no-op everywhere else.
;(function()
  local handle=mod.find("DRAMALESS_SHAPE")
  local exports=handle and handle.exports or nil
  local V=exports and exports.lib or nil
  local setting=V and V.backSpritesSetting or nil
  local provider=exports and exports.voxelCardProvider or nil
  if type(setting)~="table" or type(setting.get)~="function"
      or type(provider)~="table" then return end
  if provider.__bcSpriteFacingDualActorInstalled then return end

  local savedGet=setting.get
  local unpack_=table.unpack or unpack
  local depth=0
  local targetExtent=56
  do
    local okBB0,bb0=pcall(V.require,"BattleBillboard")
    if okBB0 and type(bb0)=="table" then
      local fp=tonumber(bb0.FULL_PIC)
      if fp and fp>0 then targetExtent=fp end
    end
  end

  local BattleState,Sprites,Assets,PaletteFX=nil,nil,nil,nil
  do
    local okBS,bs=pcall(require,"src.battle.BattleState")
    if okBS and type(bs)=="table" then BattleState=bs end
    local okSp,sp=pcall(require,"src.pokemon.Sprites")
    if okSp and type(sp)=="table" then Sprites=sp end
    local okAs,a=pcall(require,"src.render.Assets")
    if okAs and type(a)=="table" then Assets=a end
    local okPa,pal=pcall(require,"src.render.PaletteFX")
    if okPa and type(pal)=="table" then PaletteFX=pal end
  end

  local crystal=nil
  do
    local h=mod.find("crystal_animated_sprites_with_shiny_visuals")
    local ex=h and h.exports or nil
    if ex and type(ex.applyOption)=="function"
        and type(ex.frontPrefEnabled)=="function" then
      crystal={exports=ex,lastApplied=nil}
    end
  end

  local actor={
    player={side="back",turn="right",screenDelta=nil,scale=1,liveFront=nil,liveBack=nil,liveBackOwner=nil},
    enemy ={side="front",turn="left", screenDelta=nil,scale=1,liveFront=nil,liveBack=nil},
  }
  local battleRef=nil
  local contextRef=nil
  local imageCache={}
  local lastMode=nil
  local hudFont=nil
  -- Dramaless provider.update may run re-entrantly from inside BattleState.update.
  -- While BC is advancing Crystal's authoritative FRONT stream, do not let the
  -- main Dynamic presentation substitute FRONT/BACK into battler.sprite until
  -- that stream has been captured.
  local crystalFrontCaptureDepth=0

  local function dims(img)
    if img and type(img.getDimensions)=="function" then
      local ok,w,h=pcall(img.getDimensions,img)
      if ok then return tonumber(w),tonumber(h) end
    end
    return nil,nil
  end

  local function mode()
    local v=mod.options:get("spriteFacing") or "dynamic"
    if v~="turn" and v~="dynamic" then return "host" end
    return v
  end

  local function active()
    return enabled() and selectedPreset()~="external" and mode()~="host"
  end

  local function dynamic()
    return active() and mode()=="dynamic"
  end

  local function hostBackEnabled()
    local ok,v=pcall(savedGet,setting)
    return ok and v and true or false
  end

  local function crystalPref()
    if not crystal then return nil end
    local ok,v=pcall(crystal.exports.frontPrefEnabled)
    if ok then return v and true or false end
    return nil
  end

  local function setCrystal(v)
    if not crystal then return false end
    local ok=pcall(crystal.exports.applyOption,"crystalFront",v and true or false)
    if ok then crystal.lastApplied=v and true or false end
    return ok
  end

  local function restoreCrystal(v)
    if crystal and v~=nil then setCrystal(v and true or false) end
  end

  local function resetBattle(battle)
    if battle==battleRef then return end
    battleRef=battle
    contextRef=nil
    imageCache={}
    actor.player.side,actor.player.turn="back","right"
    actor.enemy.side,actor.enemy.turn="front","left"
    for _,a in pairs(actor) do
      a.screenDelta=nil; a.scale=1; a.liveFront=nil; a.liveBack=nil
      if a==actor.player then a.liveBackOwner=nil end
    end
    if crystal then crystal.lastApplied=crystalPref() end
    lastMode=mode()
  end

  local function actorCell(arena,name)
    return arena and arena[name] or nil
  end

  local function updateActorOrientation(name,cell,other,cam)
    local a=actor[name]
    local eye=cam and cam.eye or nil
    local focus=cam and cam.focus or nil
    if not (type(cell)=="table" and type(other)=="table" and type(eye)=="table") then return end

    -- FRONT/BACK: actor forward is always actor -> opponent.
    local fx=(tonumber(other[1]) or 0)-(tonumber(cell[1]) or 0)
    local fz=(tonumber(other[2]) or 0)-(tonumber(cell[2]) or 0)
    local vx=(tonumber(eye[1]) or 0)-(tonumber(cell[1]) or 0)
    local vz=(tonumber(eye[3]) or 0)-(tonumber(cell[2]) or 0)
    local fl=math.sqrt(fx*fx+fz*fz)
    local vl=math.sqrt(vx*vx+vz*vz)
    if fl>=0.001 and vl>=0.001 then
      local dot=(fx*vx+fz*vz)/(fl*vl)
      if a.side=="back" and dot>0.22 then a.side="front"
      elseif a.side=="front" and dot<(-0.22) then a.side="back" end
    end

    -- LEFT/RIGHT: use final-camera perspective screen ordering. Each actor asks
    -- on which side of itself the opposing actor appears.
    local screenDelta=nil
    if type(focus)=="table" then
      local cfx=(tonumber(focus[1]) or 0)-(tonumber(eye[1]) or 0)
      local cfz=(tonumber(focus[3]) or 0)-(tonumber(eye[3]) or 0)
      local cfl=math.sqrt(cfx*cfx+cfz*cfz)
      if cfl>=0.001 then
        cfx,cfz=cfx/cfl,cfz/cfl
        local rx,rz=cfz,-cfx
        local function screenX(p)
          local dx=(tonumber(p[1]) or 0)-(tonumber(eye[1]) or 0)
          local dz=(tonumber(p[2]) or 0)-(tonumber(eye[3]) or 0)
          local dep=dx*cfx+dz*cfz
          local lat=dx*rx+dz*rz
          if dep>0.05 then return lat/dep end
          return nil
        end
        local as=screenX(cell)
        local os=screenX(other)
        if as and os then screenDelta=os-as else screenDelta=fx*rx+fz*rz end
      end
    end
    if screenDelta~=nil then
      a.screenDelta=screenDelta
      local dead=0.035
      if a.turn=="right" and screenDelta<(-dead) then a.turn="left"
      elseif a.turn=="left" and screenDelta>dead then a.turn="right" end
    end
  end

  local function updateOrientation(context)
    contextRef=context or contextRef
    if not active() then return end
    local arena=context and context.arena or nil
    local p,e=actorCell(arena,"player"),actorCell(arena,"enemy")
    local cam=state.spriteFacingCamera
    if not (p and e and cam) then return end
    if dynamic() then
      updateActorOrientation("player",p,e,cam)
      updateActorOrientation("enemy",e,p,cam)
    else
      -- TURN ONLY keeps host/provider representation, but still derives an
      -- independent horizontal turn for each actor from the same final camera.
      local ps,es=actor.player.side,actor.enemy.side
      updateActorOrientation("player",p,e,cam)
      updateActorOrientation("enemy",e,p,cam)
      actor.player.side,actor.enemy.side=ps,es
    end
  end

  local function hostPlayerSide()
    if not hostBackEnabled() then return "front" end
    if crystal and crystalPref()==true then return "front" end
    return "back"
  end

  local function presentationSide(name)
    if mode()=="dynamic" then return actor[name].side end
    if name=="enemy" then return "front" end
    return hostPlayerSide()
  end

  local function temporarilyCrystalOff(fn)
    if not crystal then return fn() end
    local prior=crystalPref()
    if prior~=false then pcall(crystal.exports.applyOption,"crystalFront",false) end
    local r={pcall(fn)}
    if prior~=nil then pcall(crystal.exports.applyOption,"crystalFront",prior) end
    if not r[1] then error(r[2],0) end
    table.remove(r,1)
    return unpack_(r)
  end

  local function staticImage(context,name,side)
    local battle=context and context.battle or battleRef
    local battler=battle and battle[name] or nil
    local mon=battler and battler.mon or nil
    local species=mon and mon.species or nil
    if not (battle and species and Sprites and type(Sprites.path)=="function" and Assets) then return nil end

    local function resolve()
      local ok,path,tc=pcall(Sprites.path,battle.data,species,side,{mon=mon,kind="battle"})
      if not ok or type(path)~="string" or path=="" then return nil,nil end
      return path,tc
    end
    local path,tc
    if crystal and side=="back" then path,tc=temporarilyCrystalOff(resolve)
    else path,tc=resolve() end
    if not path then return nil end

    local palName="truecolor"
    if not tc and PaletteFX and type(PaletteFX.monPalName)=="function" then
      local okN,n=pcall(PaletteFX.monPalName,battle.data,species,false)
      if okN and n then palName=tostring(n) end
    end
    local key=table.concat({tostring(path),palName,name,side},"#")
    if imageCache[key] then return imageCache[key] end

    local img=nil
    if tc or not (love and love.image and love.image.newImageData and love.graphics and love.graphics.newImage) then
      local okI,v=pcall(Assets.image,path)
      if okI then img=v end
    else
      local okD,id=pcall(Assets.imageData,path)
      if okD and id then
        local pal=PaletteFX and type(PaletteFX.monPal)=="function"
          and PaletteFX.monPal(battle.data,species,false) or nil
        if pal then
          local c=pal
          pcall(id.mapPixel,id,function(_,_,r,g,b,a)
            if a==0 then return r,g,b,a end
            local col=r>0.83 and c[1] or r>0.5 and c[2] or r>0.17 and c[3] or c[4]
            return col[1]/255,col[2]/255,col[3]/255,a
          end)
        end
        local okI,v=pcall(love.graphics.newImage,id)
        if okI then img=v end
      end
    end
    if img and type(img.setFilter)=="function" then pcall(img.setFilter,img,"nearest","nearest") end
    imageCache[key]=img
    return img,displayScale
  end

  local function captureProviderLives(battle,frontAuthoritative)
    if not battle then return end
    if crystal then
      local p=battle.player
      local e=battle.enemy
      -- v1.2.0 RC1 Dramaless Crystal ownership correction: battle.player.sprite
      -- is a mutable presentation field. The main Dynamic camera may borrow a
      -- BACK image while Crystal's animation marker remains attached, so that
      -- field is not by itself proof of FRONT semantics. Only the exact
      -- BattleState.update window where BC explicitly enabled Crystal FRONT may
      -- advance the cached player FRONT used by Secondary View. This is the
      -- same provider-state ownership rule already runtime-proven on Potato.
      if frontAuthoritative==true and p and p.__crystalAnimation and p.sprite then
        actor.player.liveFront=p.sprite
      end
      if e and e.__crystalAnimation and e.sprite then actor.enemy.liveFront=e.sprite end
      if not actor.player.liveBack and hostBackEnabled() and crystalPref()==false
          and p and p.sprite and not p.__crystalAnimation then
        actor.player.liveBack=p.sprite
        actor.player.liveBackOwner=p
      end
    end
  end

  local function applySelectedRepresentations(context)
    if not active() then return end
    local battle=context and context.battle or battleRef
    if not battle then return end

    if battle.player and not battle.safari and not battle.demo
        and not battle.showPlayerBack and not battle.sendingOut then
      local side=presentationSide("player")
      local img=nil
      if crystal and side=="front" and (dynamic() or crystalPref()==true) then
        img=actor.player.liveFront
      elseif crystal and side=="back" then
        -- Crystal's FRONT animator is kept alive under DYNAMIC by temporarily
        -- enabling its crystalFront preference around BattleState.update. A
        -- player switch is executed *inside* that update, so the engine can
        -- construct the replacement battler while Crystal is transiently in
        -- FRONT mode. Never let a BACK cache outlive the battler it belongs to:
        -- resolve the current battler's provider-owned BACK art on an owner
        -- mismatch and bind that image to this exact battler instance.
        if actor.player.liveBackOwner~=battle.player then
          actor.player.liveBack=staticImage({battle=battle},"player","back")
          actor.player.liveBackOwner=actor.player.liveBack and battle.player or nil
        end
        img=actor.player.liveBack or staticImage({battle=battle},"player","back")
      else
        img=staticImage(context,"player",side)
      end
      if img then battle.player.sprite=img end
    end

    if battle.enemy and not battle.showEnemyTrainer and not battle.enemySendingOut then
      local side=presentationSide("enemy")
      local img=(crystal and side=="front" and actor.enemy.liveFront) or staticImage(context,"enemy",side)
      if img then battle.enemy.sprite=img end
    end
  end

  -- Crystal switch lifecycle repair. BC deliberately turns Crystal FRONT on
  -- only while Crystal's own Gen1 animator advances, but Gen1Recomp also
  -- replaces `battle.player` from inside that same BattleState.update when a
  -- party switch completes. The replacement's canonical BACK must therefore be
  -- captured from the new battler identity with Crystal temporarily restored to
  -- BACK resolution; otherwise the lead battler's cached back can survive the
  -- switch. `battle.battler_switched` is the engine's authoritative lifecycle
  -- seam for voluntary, forced and SHIFT replacements, so no species guessing
  -- or polling is needed here.
  if crystal then
    mod.events:on("battle.battler_switched",function(ev)
      if not dynamic() then return end
      local battle=ev and ev.battle or nil
      local side=ev and ev.side and ev.side.index or nil
      if side~=1 or not battle or battle~=battleRef then return end
      local battler=ev.battler or battle.player
      if not battler or battler~=battle.player then return end

      -- Drop both live identities immediately. Crystal's wrapped update will
      -- repopulate liveFront for the new species before this frame returns.
      actor.player.liveFront=nil
      actor.player.liveBack=nil
      actor.player.liveBackOwner=nil

      -- staticImage("back") already uses temporarilyCrystalOff(), so even
      -- though this event is raised while BC's transient FRONT preference is
      -- active, the image resolved here is the actual current mon's BACK art.
      local back=staticImage({battle=battle},"player","back")
      if back then
        actor.player.liveBack=back
        actor.player.liveBackOwner=battler
        -- makeBattler itself ran while BC's transient Crystal FRONT preference
        -- was active, so repair the new battler's canonical send-out sprite too.
        -- The engine sets sendingOut immediately after this event; Crystal then
        -- correctly leaves this BACK image alone until the send-out completes.
        battler.sprite=back
      end
    end)
  end

  -- HOST DEFAULT is deliberately zero-touch. When the user yields from TURN
  -- ONLY/DYNAMIC, BC stops substituting/placing/orienting immediately and the
  -- provider's own next lifecycle pass becomes authoritative again. Do not
  -- synthesize a "restored" frame here: that would no longer be host default.
  local function syncMode(context)
    lastMode=mode()
  end

  local function updateScale(name,battle)
    local a=actor[name]
    if not active() then a.scale=1 return end
    if crystal then a.scale=1 return end
    local battler=battle and battle[name] or nil
    local img=battler and battler.sprite or nil
    local w,h=dims(img)
    local ext=math.max(tonumber(w) or 0,tonumber(h) or 0)
    local f=(ext>0) and (targetExtent/ext) or 1
    if not (f>0.05 and f<8) then f=1 end
    a.scale=f
  end

  local function updateScales(battle)
    if not battle then return end
    if battle.showPlayerBack or battle.sendingOut then actor.player.scale=1 else updateScale("player",battle) end
    if battle.showEnemyTrainer or battle.enemySendingOut then actor.enemy.scale=1 else updateScale("enemy",battle) end
  end

  -- Crystal lifecycle bridge. Under DYNAMIC, BC transiently enables Crystal's
  -- own player-front animator for the duration of Crystal's BattleState.update
  -- even while a back view is being presented. Both front animations therefore
  -- keep advancing underneath; BC only selects which live/static side Dramaless
  -- presents after the provider has advanced its state.
  if crystal and BattleState and type(BattleState.update)=="function"
      and not BattleState.__bcSpriteFacingDualActorInstalled then
    local inner=BattleState.update
    BattleState.update=function(self,dt,...)
      resetBattle(self)
      local priorPref=crystalPref()
      local frontWindow=dynamic()
      if frontWindow then
        if actor.player.liveFront and self.player and not self.showPlayerBack then
          self.player.sprite=actor.player.liveFront
        end
        if actor.enemy.liveFront and self.enemy and not self.showEnemyTrainer then
          self.enemy.sprite=actor.enemy.liveFront
        end
        setCrystal(true)
        crystalFrontCaptureDepth=crystalFrontCaptureDepth+1
      end
      local r={pcall(inner,self,dt,...)}
      -- Dramaless provider.update can be nested inside `inner`. Its BC wrapper
      -- is suppressed while crystalFrontCaptureDepth>0, so battler.sprite here
      -- is still Crystal's genuine animated FRONT rather than the main camera's
      -- temporary BACK representation. Capture first, then reopen presentation.
      captureProviderLives(self,frontWindow)
      if frontWindow then
        crystalFrontCaptureDepth=math.max(0,crystalFrontCaptureDepth-1)
        restoreCrystal(priorPref)
      end
      if not r[1] then error(r[2],0) end
      table.remove(r,1)
      if active() then applySelectedRepresentations(contextRef or {battle=self}) end
      return unpack_(r)
    end
    BattleState.__bcSpriteFacingDualActorInstalled=true
  end

  local function withWorldPlacement(fn,self,context,...)
    if type(fn)~="function" then return nil end
    if not active() then return fn(self,context,...) end
    depth=depth+1
    if depth==1 then setting.get=function() return false end end
    local r={pcall(fn,self,context,...)}
    depth=depth-1
    if depth==0 then setting.get=savedGet end
    if not r[1] then error(r[2],0) end
    table.remove(r,1)
    return unpack_(r)
  end

  for _,name in ipairs({"begin","update"}) do
    local original=provider[name]
    if type(original)=="function" then
      provider[name]=function(self,context,...)
        resetBattle(context and context.battle or nil)
        contextRef=context or contextRef
        syncMode(context)
        updateOrientation(context)
        captureProviderLives(context and context.battle)
        if active() and crystalFrontCaptureDepth==0 then applySelectedRepresentations(context) end
        updateScales(context and context.battle)
        local r={withWorldPlacement(original,self,context,...)}
        captureProviderLives(context and context.battle)
        if active() and crystalFrontCaptureDepth==0 then applySelectedRepresentations(context) end
        updateScales(context and context.battle)
        return unpack_(r)
      end
    end
  end

  local originalFinish=provider.finish
  if type(originalFinish)=="function" then
    provider.finish=function(self,...)
      battleRef=nil; contextRef=nil; imageCache={}
      local r={originalFinish(self,...)}
      return unpack_(r)
    end
  end

  local originalLocked=provider.cameraLocked
  provider.cameraLocked=function(self,...)
    if active() then return false end
    if type(originalLocked)=="function" then return originalLocked(self,...) end
    return false
  end

  local function matrixActor(x,z)
    local context=contextRef
    local arena=context and context.arena or nil
    if not arena then return nil end
    local function near(cell)
      if type(cell)~="table" then return false end
      local dx=(tonumber(x) or 0)-(tonumber(cell[1]) or 0)
      local dz=(tonumber(z) or 0)-(tonumber(cell[2]) or 0)
      return dx*dx+dz*dz<0.01
    end
    if near(arena.player) then return "player" end
    if near(arena.enemy) then return "enemy" end
    return nil
  end

  local function orientationMirror(name)
    local a=actor[name]
    local opponentRight=(a.turn=="right")
    local side=presentationSide(name)

    -- Runtime-proven handedness map:
    --   * BACK art for either battler uses Dramaless's ordinary convention.
    --   * ENEMY FRONT art (vanilla or Crystal) is intrinsically opposite.
    --   * PLAYER static FRONT art is also opposite.
    --   * Crystal's live PLAYER FRONT animation is the one front representation
    --     already proven to use the ordinary convention in 2L2.
    if side=="back" then return opponentRight end
    if name=="enemy" then return not opponentRight end
    if crystal and name=="player" and (dynamic() or crystalPref()==true) then
      return opponentRight
    end
    return not opponentRight
  end

  local okBB,Billboard=pcall(V.require,"BattleBillboard")
  if okBB and type(Billboard)=="table" and type(Billboard.matrix)=="function"
      and not Billboard.__bcSpriteFacingDualActorInstalled then
    local originalMatrix=Billboard.matrix
    Billboard.matrix=function(texture,anchorX,anchorY,x,y,z,mirror)
      if not active() then return originalMatrix(texture,anchorX,anchorY,x,y,z,mirror) end
      local name=matrixActor(x,z)
      if not name then return originalMatrix(texture,anchorX,anchorY,x,y,z,mirror) end
      local battle=battleRef
      if name=="player" and battle and (battle.showPlayerBack or battle.sendingOut) then
        return originalMatrix(texture,anchorX,anchorY,x,y,z,mirror)
      end
      if name=="enemy" and battle and (battle.showEnemyTrainer or battle.enemySendingOut) then
        return originalMatrix(texture,anchorX,anchorY,x,y,z,mirror)
      end
      local outMirror=orientationMirror(name)
      local factor=tonumber(actor[name].scale) or 1
      if not (factor>0 and factor<8) then factor=1 end
      if math.abs(factor-1)<0.001 then
        return originalMatrix(texture,anchorX,anchorY,x,y,z,outMirror)
      end
      local prior=tonumber(Billboard.FULL_W) or 16
      Billboard.FULL_W=prior*factor
      local r={pcall(originalMatrix,texture,anchorX,anchorY,x,y,z,outMirror)}
      Billboard.FULL_W=prior
      if not r[1] then error(r[2],0) end
      table.remove(r,1)
      return unpack_(r)
    end
    Billboard.__bcSpriteFacingDualActorInstalled=true

    -- Secondary View 2D portrait adapter. This intentionally lives beside the
    -- Dramaless sprite-facing adapter so it can consume the same renderer-owned
    -- sprite resolution (vanilla replacements and Crystal live fronts) while
    -- bypassing the primary-camera Billboard.matrix orientation wrapper.
    -- BC supplies only a second camera/view; the sprite art remains provider/
    -- engine-owned. The 56px normalization mirrors Dramaless's own world-card
    -- contract, giving every Gen1 battle sprite the same predictable world fit.
    do
      local portraitCanvas=nil
      local portraitW,portraitH=160,144
      local portraitAX,portraitAY=80,96
      local function canvasForImage(img)
        if not (img and love and love.graphics and type(love.graphics.newCanvas)=="function") then return nil end
        if not portraitCanvas then
          local ok,c=pcall(love.graphics.newCanvas,portraitW,portraitH,{dpiscale=1})
          if not (ok and c) then return nil end
          if type(c.setFilter)=="function" then pcall(c.setFilter,c,"nearest","nearest") end
          portraitCanvas=c
        end
        local w,h=dims(img)
        if not (w and h and w>0 and h>0) then return nil end
        local scale=56/math.max(w,h)
        if not (scale>0.01 and scale<32) then scale=1 end
        local g=love.graphics
        local prior=g.getCanvas()
        g.push("all")
        g.setCanvas(portraitCanvas); g.clear(0,0,0,0)
        if g.setShader then g.setShader() end
        g.setBlendMode("alpha"); g.setColor(1,1,1,1)
        g.draw(img,portraitAX-w*scale/2,portraitAY-h*scale,0,scale,scale)
        g.pop()
        if prior then g.setCanvas(prior) else g.setCanvas() end
        return portraitCanvas
      end

      local function frontImage()
        local battle=state.battle or battleRef
        if not battle then return nil,false end
        -- LEFT/RIGHT remain authored fixed Secondary View CAMERA positions.
        -- Crystal liveFront is still one FRONT representation: consuming it
        -- restores the provider's animation without allowing the primary
        -- Dynamic camera to choose PiP front/back state. PIP SIDE alone owns
        -- viewpoint and handedness. Static/vanilla fronts remain unchanged.
        if crystal and actor.player.liveFront then return actor.player.liveFront,true end
        return staticImage({battle=battle},"player","front"),false
      end

      local function mirrorForSecondary()
        -- Native/Crystal front sprites follow the ordinary battle-front
        -- convention. The Secondary View CAMERA supplies the authored arena-side
        -- grammar; this mirror only keeps the flat art's handedness
        -- coherent on the opposite side. It is independent from SPRITE FACING.
        return (mod.options:get("secondaryViewSide") or "left")=="left"
      end

      state.secondarySpriteSource={
        id="DRAMALESS_SHAPE:native-player-portrait",
        drawPlayer=function(view,arena,groundY,cam)
          local img,crystalLive=frontImage()
          local canvas=canvasForImage(img)
          local mesh=type(Billboard.mesh)=="function" and Billboard.mesh() or nil
          local Voxel3D=V.require("Voxel3D")
          if not (canvas and mesh and Voxel3D and type(Voxel3D.draw)=="function"
              and arena and type(arena.player)=="table") then return false end
          local mirror=mirrorForSecondary()
          -- The model-oriented Probe13 camera is intentionally close. A full
          -- Dramaless 56px world card is therefore too large in the PiP. Since
          -- Gen1 front sprites share a bounded 56px presentation contract, use
          -- one fixed portrait-card scale rather than species tuning.
          local priorFullW=tonumber(Billboard.FULL_W) or 16
          Billboard.FULL_W=priorFullW*0.58
          local okModel,model=pcall(originalMatrix,canvas,portraitAX,portraitAY,
            arena.player[1],tonumber(groundY) or 0,arena.player[2],mirror)
          Billboard.FULL_W=priorFullW
          if not (okModel and model) then return false end
          Voxel3D.seams(false); Voxel3D.glass(false)
          Voxel3D.draw(mesh,canvas,model,Billboard.PULL)
          Voxel3D.glass(true); Voxel3D.seams(true)
          return true
        end,
      }
      mod.log:info("[SECONDARY VIEW] Dramaless/native 2D portrait adapter registered")
    end
  end

  -- Diagnostics are now opt-in through BC's existing DIAGNOSTICS option so the
  -- product menu can be tested without a permanent development HUD.
  pcall(function()
    mod.hooks:wrap("render.hud",function(nextFn,game,viewport)
      local result=nextFn(game,viewport)
      if battleRef and active() and mod.options:get("diagnostics")=="on"
          and love and love.graphics then
        pcall(function()
          local g=love.graphics
          if not hudFont then hudFont=g.newFont(11) end
          local p,e=actor.player,actor.enemy
          local lines={
            string.format("BC SPRITE FACE DRAMALESS mode=%s crystal=%s",mode(),crystal and "Y" or "N"),
            string.format("P side=%s turn=%s scale=%.3f dx=%s",presentationSide("player"),p.turn,p.scale,p.screenDelta and string.format("%.3f",p.screenDelta) or "?"),
            string.format("E side=%s turn=%s scale=%.3f dx=%s",presentationSide("enemy"),e.turn,e.scale,e.screenDelta and string.format("%.3f",e.screenDelta) or "?"),
            string.format("hostBack=%s crystalFront=%s",hostBackEnabled() and "ON" or "OFF",tostring(crystalPref())),
          }
          g.push("all"); g.origin(); g.setFont(hudFont)
          g.setColor(0,0,0,.84); g.rectangle("fill",8,8,610,66,4,4)
          g.setColor(1,1,1,1)
          for i,line in ipairs(lines) do g.print(line,13,10+(i-1)*14) end
          g.pop()
        end)
      end
      return result
    end)
  end)

  provider.__bcSpriteFacingDualActorInstalled=true
  mod.log:warn("[BC SPRITE FACE] Dramaless dual-actor adapter armed")
end)()

-- Dramatic Shape Sprite Facing / Dual Actor Presentation -------------------
-- Dramatic Shape adapter consumes the host's own staged 2D-card seam. The host still
-- owns arena rendering, texture capture, shadows, lighting, move FX and camera
-- projection.  BC contributes only the same final-camera actor orientation
-- semantic already proven on Dramaless/Battle Art.  Stadium-model rungs are a
-- hard yield: real 3D models are never converted into sprite cards here.
;(function()
  local handle=mod.find("DRAMATIC_SHAPE")
  local gen2RecompedDramatic=false
  -- Gen2Recomped Dramatic Shapes exposes the same staged-card contract under
  -- its host-specific provider ID. Test1 proved the camera family can be
  -- normalized safely; do the same here so BC's existing renderer-neutral
  -- 4-Way Sprite View adapter can consume its FRONT/BACK card seam unchanged.
  if not handle then
    handle=mod.find("Gen2Recomped-DramaticShapes")
    gen2RecompedDramatic=handle and true or false
  end
  local exports=handle and handle.exports or nil
  local V=exports and exports.lib or nil
  if not (V and type(V.require)=="function") then return end

  local okOB,OverworldBattle=pcall(V.require,"OverworldBattle")
  if not okOB or type(OverworldBattle)~="table"
      or type(OverworldBattle.sideTexture)~="function"
      or type(OverworldBattle.backPinned)~="function" then return end
  if OverworldBattle.__bcSpriteFacingDramaticInstalled then return end

  local setting=OverworldBattle.backSetting
  local savedBackPinned=OverworldBattle.backPinned
  if type(setting)~="table" or type(setting.get)~="function" then return end
  local savedSettingGet=setting.get
  local unpack_=table.unpack or unpack

  local BattleState,Sprites,Assets,PaletteFX=nil,nil,nil,nil
  do
    local okBS,bs=pcall(require,"src.battle.BattleState")
    if okBS and type(bs)=="table" then BattleState=bs end
    local okSp,sp=pcall(require,"src.pokemon.Sprites")
    if okSp and type(sp)=="table" then Sprites=sp end
    local okAs,a=pcall(require,"src.render.Assets")
    if okAs and type(a)=="table" then Assets=a end
    local okPa,pal=pcall(require,"src.render.PaletteFX")
    if okPa and type(pal)=="table" then PaletteFX=pal end
  end
  if not (BattleState and Sprites and Assets) then return end

  local crystal=nil
  do
    local h=mod.find("crystal_animated_sprites_with_shiny_visuals")
    local ex=h and h.exports or nil
    if ex and type(ex.applyOption)=="function"
        and type(ex.frontPrefEnabled)=="function" then
      crystal={exports=ex}
    end
  end

  local actor={
    player={side="back",turn="right",screenDelta=nil,scale=1,liveFront=nil,liveBack=nil},
    enemy ={side="front",turn="left", screenDelta=nil,scale=1,liveFront=nil,liveBack=nil},
  }
  local battleRef=nil
  local imageCache={}
  local flipped={}

  local function mode()
    local v=mod.options:get("spriteFacing") or "dynamic"
    if v~="turn" and v~="dynamic" then return "host" end
    return v
  end

  local function isStadium()
    if type(OverworldBattle.stadium)~="function" then return false end
    local ok,v=pcall(OverworldBattle.stadium)
    return ok and v and true or false
  end

  local function active()
    if not enabled() or selectedPreset()=="external" or mode()=="host" then return false end
    if type(OverworldBattle.enabled)=="function" then
      local ok,v=pcall(OverworldBattle.enabled)
      if not ok or not v then return false end
    end
    if isStadium() then return false end
    return true
  end

  local function dynamic() return active() and mode()=="dynamic" end

  local function hostBackEnabled()
    local ok,v=pcall(savedSettingGet,setting)
    return ok and v and true or false
  end

  local function crystalPref()
    if not crystal then return nil end
    local ok,v=pcall(crystal.exports.frontPrefEnabled)
    return ok and (v and true or false) or nil
  end

  local function setCrystal(v)
    if not crystal then return false end
    return pcall(crystal.exports.applyOption,"crystalFront",v and true or false)
  end

  local function resetBattle(battle)
    if battle==battleRef then return end
    battleRef=battle
    imageCache={}
    actor.player.side,actor.player.turn="back","right"
    actor.enemy.side,actor.enemy.turn="front","left"
    for _,a in pairs(actor) do
      a.screenDelta=nil; a.scale=1; a.liveFront=nil; a.liveBack=nil
    end
  end

  local function updateOne(name,cell,other,cam)
    local a=actor[name]
    local eye=cam and cam.eye or nil
    local focus=cam and cam.focus or nil
    if not (type(cell)=="table" and type(other)=="table" and type(eye)=="table") then return end

    local fx=(tonumber(other[1]) or 0)-(tonumber(cell[1]) or 0)
    local fz=(tonumber(other[2]) or 0)-(tonumber(cell[2]) or 0)
    local vx=(tonumber(eye[1]) or 0)-(tonumber(cell[1]) or 0)
    local vz=(tonumber(eye[3]) or 0)-(tonumber(cell[2]) or 0)
    local fl=math.sqrt(fx*fx+fz*fz)
    local vl=math.sqrt(vx*vx+vz*vz)
    if fl>=0.001 and vl>=0.001 then
      local dot=(fx*vx+fz*vz)/(fl*vl)
      if a.side=="back" and dot>0.22 then a.side="front"
      elseif a.side=="front" and dot<(-0.22) then a.side="back" end
    end

    local screenDelta=nil
    if type(focus)=="table" then
      local cfx=(tonumber(focus[1]) or 0)-(tonumber(eye[1]) or 0)
      local cfz=(tonumber(focus[3]) or 0)-(tonumber(eye[3]) or 0)
      local cfl=math.sqrt(cfx*cfx+cfz*cfz)
      if cfl>=0.001 then
        cfx,cfz=cfx/cfl,cfz/cfl
        local rx,rz=cfz,-cfx
        local function screenX(pt)
          local dx=(tonumber(pt[1]) or 0)-(tonumber(eye[1]) or 0)
          local dz=(tonumber(pt[2]) or 0)-(tonumber(eye[3]) or 0)
          local dep=dx*cfx+dz*cfz
          local lat=dx*rx+dz*rz
          if dep>0.05 then return lat/dep end
        end
        local aa,oo=screenX(cell),screenX(other)
        screenDelta=(aa and oo) and (oo-aa) or (fx*rx+fz*rz)
      end
    end
    if screenDelta~=nil then
      a.screenDelta=screenDelta
      local dead=0.035
      if a.turn=="right" and screenDelta<(-dead) then a.turn="left"
      elseif a.turn=="left" and screenDelta>dead then a.turn="right" end
    end
  end

  local function updateOrientation()
    if not active() then return end
    local okA,arena=pcall(OverworldBattle.arena)
    if not okA or type(arena)~="table" then return end
    local p,e=arena.player,arena.enemy
    local cam=state.spriteFacingCamera
    if not (p and e and cam) then return end
    if dynamic() then
      updateOne("player",p,e,cam); updateOne("enemy",e,p,cam)
    else
      local ps,es=actor.player.side,actor.enemy.side
      updateOne("player",p,e,cam); updateOne("enemy",e,p,cam)
      actor.player.side,actor.enemy.side=ps,es
    end
  end

  local function hostPlayerSide()
    if not hostBackEnabled() then return "front" end
    if crystal and crystalPref()==true then return "front" end
    return "back"
  end

  local function presentationSide(name)
    if mode()=="dynamic" then return actor[name].side end
    if name=="enemy" then return "front" end
    return hostPlayerSide()
  end

  -- While BC is actively consuming sprite orientation, the player's card must
  -- remain in Dramatic's world-card pass.  The saved BACK SPRITES preference is
  -- still read above for TURN ONLY; only the host's pinning side effect yields.
  OverworldBattle.backPinned=function(...)
    if active() then return false end
    return savedBackPinned(...)
  end

  local nativeResolveScale=BattleState.resolveBattleScale

  local function temporarilyCrystalOff(fn)
    if not crystal then return fn() end
    local prior=crystalPref()
    if prior~=false then setCrystal(false) end
    local r={pcall(fn)}
    if prior~=nil then setCrystal(prior) end
    if not r[1] then error(r[2],0) end
    table.remove(r,1)
    return unpack_(r)
  end

  local function staticRep(name,side,battle)
    local battler=battle and battle[name] or nil
    local mon=battler and battler.mon or nil
    local species=mon and mon.species or nil
    if not species then return nil,1 end

    local function resolvePath()
      local ok,path,tc=pcall(Sprites.path,battle.data,species,side,{mon=mon,kind="battle"})
      if not ok or type(path)~="string" or path=="" then return nil,nil end
      return path,tc
    end
    local function resolveNativeSide()
      -- Dramatic-derived staged-battle hosts deliberately rewrite every
      -- battle BACK request to FRONT while their 2D-3D world-card mode is
      -- active (OverworldBattle.wantsFront).  TURN ONLY never notices because
      -- it keeps the host representation, but DYNAMIC must be able to request
      -- the genuine back asset when the final BC camera crosses behind an
      -- actor.  Suppress only that host-side rewrite for this one path lookup;
      -- the saved host setting and its normal renderer behaviour are untouched.
      local wf=OverworldBattle.wantsFront
      if side=="back" and type(wf)=="function" then
        OverworldBattle.wantsFront=function() return false end
      end
      local r={pcall(resolvePath)}
      if side=="back" and type(wf)=="function" then
        OverworldBattle.wantsFront=wf
      end
      if not r[1] then error(r[2],0) end
      return r[2],r[3]
    end

    local path,tc
    if crystal and side=="back" then path,tc=temporarilyCrystalOff(resolveNativeSide)
    else path,tc=resolveNativeSide() end
    if not path then return nil,1 end

    local scale=1
    local okS,v=pcall(nativeResolveScale,battle.data,side,path,species)
    if okS and tonumber(v) and tonumber(v)>0 then scale=tonumber(v) end

    local palName="truecolor"
    if not tc and PaletteFX and type(PaletteFX.monPalName)=="function" then
      local okN,n=pcall(PaletteFX.monPalName,battle.data,species,false)
      if okN and n then palName=tostring(n) end
    end
    local key=table.concat({tostring(path),palName,name,side},"#")
    if imageCache[key] then return imageCache[key],scale end

    local img=nil
    if tc or not (love and love.image and love.image.newImageData and love.graphics and love.graphics.newImage) then
      local okI,vv=pcall(Assets.image,path); if okI then img=vv end
    else
      local okD,id=pcall(Assets.imageData,path)
      if okD and id then
        local pal=PaletteFX and type(PaletteFX.monPal)=="function"
          and PaletteFX.monPal(battle.data,species,false) or nil
        if pal then
          local c=pal
          pcall(id.mapPixel,id,function(_,_,r,g,b,a)
            if a==0 then return r,g,b,a end
            local col=r>0.83 and c[1] or r>0.5 and c[2] or r>0.17 and c[3] or c[4]
            return col[1]/255,col[2]/255,col[3]/255,a
          end)
        end
        local okI,vv=pcall(love.graphics.newImage,id); if okI then img=vv end
      end
    end
    if img and type(img.setFilter)=="function" then pcall(img.setFilter,img,"nearest","nearest") end
    imageCache[key]=img
    return img,scale
  end

  local function captureLives(battle,frontAuthoritative)
    if not (crystal and battle) then return end
    local p,e=battle.player,battle.enemy
    -- Rebase56 ports the user-validated Potato Rebase54 ownership correction
    -- back to base Dramatic. battle.player.sprite is a presentation field: a
    -- Dynamic BACK borrowed for one staged-card capture must never become the
    -- next cached Crystal FRONT. Only the update window where BC explicitly
    -- enabled Crystal FRONT is authoritative for the player stream.
    if frontAuthoritative==true and p and p.__crystalAnimation and p.sprite then
      actor.player.liveFront=p.sprite
    end
    if e and e.__crystalAnimation and e.sprite then actor.enemy.liveFront=e.sprite end
  end

  local function applyRep(name,battle)
    if not (active() and battle) then return end
    if name=="player" and (battle.safari or battle.demo or battle.showPlayerBack or battle.sendingOut) then return end
    if name=="enemy" and (battle.showEnemyTrainer or battle.enemySendingOut) then return end
    local battler=battle[name]
    if not battler then return end
    local side=presentationSide(name)
    local img,scale=nil,1
    if crystal and side=="front" then
      img=actor[name].liveFront
      if not img then img,scale=staticRep(name,side,battle) end
    else
      img,scale=staticRep(name,side,battle)
    end
    if img then battler.sprite=img end
    actor[name].scale=(tonumber(scale) and tonumber(scale)>0) and tonumber(scale) or 1
  end

  -- Keep Crystal's real player-front animation alive under DYNAMIC without
  -- changing the user's saved Crystal option.  This is the same lifecycle
  -- ownership rule already proven on Dramaless.
  if crystal and type(BattleState.update)=="function"
      and not BattleState.__bcSpriteFacingDramaticInstalled then
    local innerUpdate=BattleState.update
    BattleState.update=function(self,dt,...)
      resetBattle(self)
      local prior=crystalPref()
      if dynamic() then
        if actor.player.liveFront and self.player and not self.showPlayerBack then
          self.player.sprite=actor.player.liveFront
        end
        if actor.enemy.liveFront and self.enemy and not self.showEnemyTrainer then
          self.enemy.sprite=actor.enemy.liveFront
        end
        setCrystal(true)
      end
      local r={pcall(innerUpdate,self,dt,...)}
      captureLives(self,dynamic())
      if dynamic() and prior~=nil then setCrystal(prior) end
      if not r[1] then error(r[2],0) end
      table.remove(r,1)
      -- Camera-selected art is now borrowed only inside sideTexture below; do
      -- not persist it back into provider battler state after the update.
      return unpack_(r)
    end
    BattleState.__bcSpriteFacingDramaticInstalled=true
  end

  local function desiredMirror(name)
    local side=presentationSide(name)
    local opponentRight=(actor[name].turn=="right")
    -- Dramatic's BattleScene documents raw FRONT art as facing left: its
    -- ordinary player card is mirrored and its enemy card is not. Native BACK
    -- art is authored in the opposite direction. Translate the universal BC
    -- turn semantic into that host convention; no species knowledge involved.
    if side=="front" then
      local want=not opponentRight
      -- Gen2Recomped Prism ships the PLAYER FRONT representation with the
      -- opposite native handedness from the shared Dramatic card convention.
      -- Prism runtime validation proved FRONT/BACK selection is correct; only
      -- the player FRONT horizontal orientation is reversed. Keep this scoped
      -- to Prism + Dynamic + player + FRONT so Crystal/Emerald/Gen1, enemy
      -- cards, BACK cards and Secondary View retain their accepted contracts.
      if gen2RecompedDramatic and dynamic() and name=="player" then
        local okGV,gv=pcall(require,"src.core.GameVersion")
        if okGV and type(gv)=="table" and type(gv.get)=="function" then
          local okId,id=pcall(gv.get)
          if okId and id=="prism" then want=not want end
        end
      end
      return want
    end
    return opponentRight
  end

  local function flipCanvas(src,key)
    if not (src and love and love.graphics and type(src.getDimensions)=="function") then return nil end
    local w,h=src:getDimensions()
    if not (w and h and w>0 and h>0) then return nil end
    local rec=flipped[key]
    if not rec or rec.w~=w or rec.h~=h then
      local ok,c=pcall(love.graphics.newCanvas,w,h,{dpiscale=1})
      if not ok or not c then return nil end
      if type(c.setFilter)=="function" then pcall(c.setFilter,c,"nearest","nearest") end
      rec={canvas=c,w=w,h=h}; flipped[key]=rec
    end
    local g=love.graphics
    local prev=g.getCanvas()
    local bm,ba=g.getBlendMode()
    local cr,cg,cb,ca=g.getColor()
    local ok=pcall(function()
      g.setCanvas(rec.canvas); g.clear(0,0,0,0); g.setBlendMode("alpha")
      g.setColor(1,1,1,1); g.draw(src,w,0,0,-1,1)
    end)
    if prev then g.setCanvas(prev) else g.setCanvas() end
    g.setBlendMode(bm or "alpha",ba); g.setColor(cr,cg,cb,ca)
    if not ok then return nil end
    return rec.canvas,w
  end

  local originalSideTexture=OverworldBattle.sideTexture
  OverworldBattle.sideTexture=function(battle,side)
    if not active() then return originalSideTexture(battle,side) end
    resetBattle(battle)
    updateOrientation()

    -- Rebase56: one-capture representation ownership. This is the exact
    -- Potato Rebase54 fix the user validated as removing PiP FRONT/BACK leak
    -- and the apparent stray/fifth Crystal back frame.
    local battler=battle and battle[side] or nil
    local repSide=presentationSide(side)
    local displayScale=1
    local priorSprite=nil
    local swapped=false
    local canBorrow=(side=="player" or side=="enemy") and battler~=nil
    if side=="player" and battle
        and (battle.safari or battle.demo or battle.showPlayerBack or battle.sendingOut) then
      canBorrow=false
    elseif side=="enemy" and battle
        and (battle.showEnemyTrainer or battle.enemySendingOut) then
      canBorrow=false
    end
    if canBorrow then
      local img=nil
      if crystal and repSide=="front" and actor[side].liveFront then
        img=actor[side].liveFront
      else
        img,displayScale=staticRep(side,repSide,battle)
      end
      displayScale=(tonumber(displayScale) and tonumber(displayScale)>0) and tonumber(displayScale) or 1
      actor[side].scale=displayScale
      if img then
        priorSprite=battler.sprite
        battler.sprite=img
        swapped=true
      end
    end

    local savedResolve=nil
    if dynamic() and not crystal and presentationSide(side)=="back"
        and type(BattleState.resolveBattleScale)=="function" then
      local factor=tonumber(actor[side].scale) or 1
      -- Test3: Gen2Recomped's unified BattleState.resolveBattleScale already
      -- distinguishes cartridge representation contracts: Gen1 BACK=2,
      -- Gen2/Gen3 BACK=1. A returned 1 is authoritative, not an unknown scale.
      -- The older Dramatic fallback inferred 56/32 => 2 whenever factor was 1,
      -- re-inflating full-size Johto/Hoenn backs only when Dynamic selected
      -- BACK. Preserve that legacy inference only on the already-accepted
      -- original DRAMATIC_SHAPE host; trust Gen2Recomped's resolver unchanged.
      if not gen2RecompedDramatic and factor<=1.001
          and type(OverworldBattle.SLOT_W)=="table" then
        local fw=tonumber(OverworldBattle.SLOT_W.front)
        local bw=tonumber(OverworldBattle.SLOT_W.back)
        if fw and bw and bw>0 then factor=math.max(1,math.floor(fw/bw+0.5)) end
      end
      if factor>1.001 and factor<8 then
        savedResolve=BattleState.resolveBattleScale
        BattleState.resolveBattleScale=function(...) return factor end
      end
    end
    local r={pcall(originalSideTexture,battle,side)}
    if savedResolve then BattleState.resolveBattleScale=savedResolve end
    if swapped then battler.sprite=priorSprite end
    if not r[1] then error(r[2],0) end
    local tex=r[2]
    if not (tex and not tex.trainer and tex.canvas) then return tex end

    local hostMirror=(side=="player")
    local want=desiredMirror(side)
    if hostMirror~=want then
      local c,w=flipCanvas(tex.canvas,side)
      if c then
        tex.canvas=c
        if tonumber(tex.ax) then tex.ax=w-tonumber(tex.ax) end
      end
    end
    return tex
  end

  -- Base Dramatic fixed-FRONT Secondary View producer. Crystal never samples
  -- battle.player.sprite here; that field may be the main camera's borrowed
  -- BACK. The authoritative animated FRONT cache above feeds the canonical
  -- 160x144 / X80 / Y96 / max-56px portrait directly.
  local secondaryCardCanvas=nil
  local secondaryCardW,secondaryCardH=nil,nil

  local function ensureSecondaryCanvas(w,h)
    if secondaryCardCanvas and secondaryCardW==w and secondaryCardH==h then return secondaryCardCanvas end
    if secondaryCardCanvas and type(secondaryCardCanvas.release)=="function" then pcall(secondaryCardCanvas.release,secondaryCardCanvas) end
    local okC,c=pcall(love.graphics.newCanvas,w,h,{dpiscale=1})
    if not (okC and c) then return nil end
    if type(c.setFilter)=="function" then pcall(c.setFilter,c,"nearest","nearest") end
    secondaryCardCanvas,secondaryCardW,secondaryCardH=c,w,h
    return c
  end

  -- Test8: keep Prism's runtime-accepted Secondary View polarity exactly as
  -- Test7, but invert the flat FRONT portrait handedness on the other
  -- Gen2Recomped cartridges. Red/Crystal/Emerald all proved the same reversed
  -- LEFT/RIGHT semantic at runtime, while Prism proved correct.  This helper
  -- changes only the portrait mirror decision; camera position, actor source,
  -- FRONT/BACK ownership and the original DRAMATIC_SHAPE host are untouched.
  local function secondaryPortraitMirror()
    local side=(mod.options:get("secondaryViewSide") or "left")
    if not gen2RecompedDramatic then return side=="right" end
    local id=nil
    local okGV,gv=pcall(require,"src.core.GameVersion")
    if okGV and type(gv)=="table" and type(gv.get)=="function" then
      local okId,v=pcall(gv.get)
      if okId then id=v end
    end
    if id=="prism" then return side=="right" end
    return side=="left"
  end

  local function copyProviderCard(tex)
    if not (tex and tex.canvas and type(tex.canvas.getDimensions)=="function") then return nil,"provider card unavailable" end
    local w,h=tex.canvas:getDimensions()
    if not (w and h and w>0 and h>0) then return nil,"provider card dimensions unavailable" end
    local out=ensureSecondaryCanvas(w,h); if not out then return nil,"private card canvas unavailable" end
    local g=love.graphics
    local prior=nil; if type(g.getCanvas)=="function" then local okP,v=pcall(g.getCanvas); if okP then prior=v end end
    local pushed=false
    local okCopy,errCopy=pcall(function()
      g.push("all"); pushed=true; g.origin(); g.setCanvas(out); g.clear(0,0,0,0)
      if g.setShader then g.setShader() end
      g.setBlendMode("alpha"); g.setColor(1,1,1,1)
      if secondaryPortraitMirror() then g.draw(tex.canvas,w,0,0,-1,1) else g.draw(tex.canvas,0,0) end
    end)
    if pushed then pcall(g.pop) end
    if prior~=nil then pcall(g.setCanvas,prior) else pcall(g.setCanvas) end
    if not okCopy then return nil,"private card copy failed: "..tostring(errCopy) end
    local ax=tonumber(tex.ax) or tonumber(OverworldBattle.TEX_AX) or 80
    if secondaryPortraitMirror() then ax=w-ax end
    return {canvas=out,ax=ax,ay=tonumber(tex.ay) or tonumber(OverworldBattle.TEX_AY) or 96,trainer=false},"provider_front"
  end

  local function crystalFrontCard(img)
    if not (img and type(img.getDimensions)=="function") then return nil,"Crystal FRONT frame unavailable" end
    local okD,iw,ih=pcall(img.getDimensions,img); iw,ih=tonumber(iw),tonumber(ih)
    if not (okD and iw and ih and iw>0 and ih>0) then return nil,"Crystal FRONT dimensions unavailable" end
    local out=ensureSecondaryCanvas(160,144); if not out then return nil,"private Crystal card canvas unavailable" end
    local scale=56/math.max(iw,ih)
    local mirror=secondaryPortraitMirror()
    local dx=mirror and -scale or scale
    local x=80-(iw*dx)/2; local y=96-ih*scale
    local g=love.graphics
    local prior=nil; if type(g.getCanvas)=="function" then local okP,v=pcall(g.getCanvas); if okP then prior=v end end
    local pushed=false
    local okDraw,errDraw=pcall(function()
      g.push("all"); pushed=true; g.origin(); g.setCanvas(out); g.clear(0,0,0,0)
      if g.setShader then g.setShader() end
      g.setBlendMode("alpha"); g.setColor(1,1,1,1); g.draw(img,x,y,0,dx,scale)
    end)
    if pushed then pcall(g.pop) end
    if prior~=nil then pcall(g.setCanvas,prior) else pcall(g.setCanvas) end
    if not okDraw then return nil,"Crystal FRONT card draw failed: "..tostring(errDraw) end
    return {canvas=out,ax=80,ay=96,trainer=false},"crystal_live_front_locked"
  end

  -- Test7: Gen2Recomped Gen1/Gen3 do not need the host's PLAYER-side
  -- battle-slot compositor to manufacture a FRONT portrait. That compositor is
  -- inherently authored around the player's BACK slot, and Test6 proved that
  -- reusing it for a forced FRONT can yield a valid private world with no
  -- visible subject on Red/Emerald. Build the already-resolved FRONT image into
  -- BC's established canonical 160x144 / X80 / Y96 / max-56px portrait instead.
  --
  -- Keep Gen2/Prism on the accepted provider-card route byte-for-byte: Prism's
  -- private actor/framing is runtime-accepted and Crystal's remaining issue is
  -- side polarity, not actor availability. This is representation ownership
  -- only; live action-state mirroring remains deliberately pinned.
  local function canonicalStaticFrontCard(img)
