    local minZ,maxZ=tonumber(b.minZ),tonumber(b.maxZ); local modelH=tonumber(m.height)
    if not (minX and maxX and minY and maxY and minZ and maxZ and modelH and modelH>1e-4 and maxY>minY) then return nil end
