    if type(g.getColor)=="function" then cr,cg,cb,ca=g.getColor() end
    local dm,dw=nil,nil
    if type(g.getDepthMode)=="function" then dm,dw=g.getDepthMode() end
    local cull=type(g.getMeshCullMode)=="function" and g.getMeshCullMode() or nil

    local rw,rh=P.renderResolution()
    local oldCamera=V3.camera
    local oldTint=V3.tint
    local oldFog=V3.fog
    local oldGlassMask,oldGlassNight=V3.glassMask,V3.glassNight
    local oldGlassPhase,oldGlassGlint=V3.glassPhase,V3.glassGlint
    local oldShadowAlpha=V3.SHADOW_ALPHA
    local oldReady=VState.ready
    local oldEnd=V3.endScene
    local canvas=nil
    local actorDrawn=false
    local actorErr=nil

    local function drawNative()
      local okD,accepted=pcall(nativeActor.rig.draw,nativeActor.rig,nativeActor.model_matrix,BB.PULL)
      if not okD then actorErr=tostring(accepted); return false end
      if accepted==false then actorErr="native Colosseum rig declined private draw"; return false end
      actorDrawn=true
      return true
    end

    local okRender,errRender=pcall(function()
      V3.camera=cam
      if arena.discs then
        local host=arena.map or world.map
        local sky=type(VS.skyColor)=="function" and VS.skyColor(host,1) or nil
        if not sky and type(VS.skyShade)=="function" then sky=VS.skyShade(4,1) end
        if sky and type(Sky.dress)=="function" then
          local okDress,dressed=pcall(Sky.dress,sky)
          if okDress and dressed then sky=dressed end
        end
        if not V3.beginScene(rw,rh,arena.mid[1],arena.mid[2],160,90,sky,
            "bc_secondary_dramatic_colosseum") then
          error("Dramatic private Colosseum beginScene declined: "..tostring(V3.beginFailure),0)
        end
        Stage.draw(arena,groundY)
        if not drawNative() then error("Colosseum actor in-scene draw failed: "..tostring(actorErr),0) end
        canvas=V3.endScene()
        if not canvas then error("Dramatic private Colosseum endScene returned nil",0) end
      else
