      and type(OB.enabled)=="function" and type(OB.stage)=="function"
      and type(OB.worldCards)=="function" and type(BS.render)=="function") then
    P.g2rDramaticPipFailure="Gen2Recomped staged-world contract incomplete"
    return
  end

  local backend=nil
  for _,b in ipairs(backends) do
    if b.id=="DRAMATIC_SHAPE" and b.providerId=="Gen2Recomped-DramaticShapes" then
