    end
  end
  if not backend then
    P.g2rDramaticPipFailure="Gen2Recomped Dramatic BattleCam backend unavailable"
    return
  end

  local function lifecycleEligible()
    return type(P.liveLifecycleEligible)=="function" and P.liveLifecycleEligible() or false
  end

  P.dramaticEligible=function()
    if not lifecycleEligible() then return false end
    local okE,on=pcall(OB.enabled)
    if not (okE and on) then return false end
    local okS,arena=pcall(OB.stage)
    return okS and type(arena)=="table"
      and type(arena.player)=="table" and type(arena.enemy)=="table"
