    if okRender and type(shot)=="table" and shot.canvas then
      P.shot={canvas=shot.canvas}
      P.frames=(P.frames or 0)+1
      P.failure=nil
      P.g2rDramaticPipFrames=(P.g2rDramaticPipFrames or 0)+1
    else
      P.shot=nil
