    local originalInvalidate=OverworldBattle.invalidate
    OverworldBattle.invalidate=function(...)
      clear()
      return originalInvalidate(...)
    end
    OverworldBattle.__bcSpriteFacingGen2InvalidateInstalled=true
  end

