    -- Keep this hosted main-world render out of Dramaless' ordinary "battle"
    -- canvas slot, and out of Secondary View's private slot. The call remains
    -- synchronous and graphics-state-safe inside VoxelBattleScene.render().
    local oldBegin,oldResolve=V3.beginScene,AA.resolve
    V3.beginScene=function(rw,rh,cx,cy,vw,vh,sky,slot,...)
      if slot=="battle" then slot="bc_dramaless_importer_main" end
      return oldBegin(rw,rh,cx,cy,vw,vh,sky,slot,...)
    end
    AA.resolve=function(canvas,w,h,slot,...)
      if slot=="battle" then slot="bc_dramaless_importer_main" end
      return oldResolve(canvas,w,h,slot,...)
    end
    local okRender,canvas=pcall(Scene.render,world,arena,function() end,
      {pose=cam,pitch=pitch})
    V3.beginScene,AA.resolve=oldBegin,oldResolve
    if not (okRender and canvas) then
      return nil,okRender and "Dramaless render returned nil" or tostring(canvas)
    end
    if not drawCanvas(ctx,canvas) then return nil,"Importer target composite failed" end
    bridge.lastCanvas=canvas
    bridge.suppressBattle=battle
    bridge.successes=bridge.successes+1
    bridge.lastError=nil
    return ctx.marks or true
  end

  local function environment(next,ctx)
    local battle=ctx and ctx.scene and ctx.scene.battle or nil
    if not importerActive(battle) then return next(ctx) end
    local ok,result,err=pcall(renderEnvironment,ctx)
    if ok and result then return result end
    bridge.failures=bridge.failures+1
    bridge.lastError=ok and err or tostring(result)
    bridge.suppressBattle=nil
    return next(ctx)
  end

  local okHook=pcall(sceneApi.register,mod,"environment",environment,120)
  if not okHook then return end

  -- Dramaless' standalone wrapper may still be below Importer's BattleState.draw
  -- wrapper. It remains valuable for lifecycle/update state, but its completed
  -- world is invisible once Importer's render.compose wins. Suppress only that
  -- redundant draw on frames where the environment bridge already succeeded.
  if standalone and type(standalone.draw)=="function" and not standalone.__bcImporterArenaWrapped then
