      return originalDraw(battle,...)
    end
    standalone.__bcImporterArenaWrapped=true
  end

  if mod.events and type(mod.events.on)=="function" then
    mod.events:on("battle.ended",function()
      bridge.lastBattle,bridge.lastArena,bridge.lastCanvas,bridge.suppressBattle=nil,nil,nil,nil
    end)
  end
