    local ex,ez=tonumber(arena.enemy[1]),tonumber(arena.enemy[2])
    wx,wz=tonumber(wx),tonumber(wz)
    if not (px and pz and ex and ez and wx and wz) then return nil end
    local half=(tonumber(BattleScene.CELL) or 16)/2
    if near(wx,px) and near(wz,pz) then return "PC","player" end
    if near(wx,ex) and near(wz,ez) then return "EC","enemy" end
    if near(wx,px-half) and near(wz,pz) then return "PL","player" end
    if near(wx,px+half) and near(wz,pz) then return "PR","player" end
    if near(wx,px) and near(wz,pz-half) then return "PN","player" end
    if near(wx,px) and near(wz,pz+half) then return "PS","player" end
    if near(wx,ex-half) and near(wz,ez) then return "EL","enemy" end
    if near(wx,ex+half) and near(wz,ez) then return "ER","enemy" end
    if near(wx,ex) and near(wz,ez-half) then return "EN","enemy" end
    if near(wx,ex) and near(wz,ez+half) then return "ES","enemy" end
