    if bridge.hostedBattle~=nil then pcall(OW.providerFinish) end
    bridge.hostedBattle=nil
  end

  local function ensureHosted(battle)
    if bridge.hostedBattle==battle then return true end
    finishHosted()
    local ok,up=pcall(OW.providerBegin,battle)
    if ok and up then bridge.hostedBattle=battle; return true end
    return false
  end

  local function cameraRig(ctx,arena,groundY)
    local c=ctx and ctx.camera or nil
    local eye=c and c.eye or nil
    local focus=c and c.focus or nil
    local projection=c and c.projection or nil
    local f=type(projection)=="table" and math.abs(tonumber(projection[6]) or 0) or 0
    if not (type(eye)=="table" and type(focus)=="table" and f>1e-6
        and arena and type(arena.mid)=="table") then return nil end

    local desiredFov=2*math.atan(1/f)
    local okLB,lx,ly,s,pw,ph=pcall(BattleScene.letterbox)
    if not (okLB and tonumber(s) and tonumber(ph) and s>0 and ph>0) then return nil end
