    -- inverse here so its final renderer-facing FOV equals Importer's camera.
    local rawFov=2*math.atan(math.tan(desiredFov/2)*span/ph)

    local mx,mz=tonumber(arena.mid[1]) or 0,tonumber(arena.mid[2]) or 0
    local gy=tonumber(groundY) or 0
    local cam={
      eye={ (tonumber(eye[1]) or 0)+mx,(tonumber(eye[2]) or 0)+gy,(tonumber(eye[3]) or 0)+mz },
      focus={ (tonumber(focus[1]) or 0)+mx,(tonumber(focus[2]) or 0)+gy,(tonumber(focus[3]) or 0)+mz },
      up={0,1,0}, fov=rawFov, curve=0,
    }
