    if not (g and type(g.setCanvas)=="function" and target and target.color) then return false end
    local binding=target.depth and {target.color,depthstencil=target.depth}
      or {target.color,depth=true}
    return pcall(g.setCanvas,binding)
  end

  local function drawCanvas(ctx,canvas)
    local g,target=ctx and ctx.graphics,ctx and ctx.target
    if not (g and target and canvas and type(canvas.getDimensions)=="function"
        and type(g.draw)=="function") then return false end
    local ok,cw,ch=pcall(canvas.getDimensions,canvas)
    if not (ok and tonumber(cw) and tonumber(ch) and cw>0 and ch>0) then return false end
    if not bindTarget(g,target) then return false end
    if g.setShader then g.setShader() end
    if g.setDepthMode then g.setDepthMode("always",false) end
    if g.setBlendMode then g.setBlendMode("alpha","alphamultiply") end
    if g.setColor then g.setColor(1,1,1,1) end
    g.draw(canvas,0,0,0,target.width/cw,target.height/ch)
    return true
  end

  local function renderEnvironment(ctx)
    local battle=ctx and ctx.scene and ctx.scene.battle or nil
    if not importerActive(battle) then return nil,"inactive" end
    if not ensureHosted(battle) then return nil,"Dramatic providerBegin unavailable" end
    local okInfo,arena,groundY=pcall(OW.arenaInfo)
    if not (okInfo and type(arena)=="table") then return nil,"Dramatic arena unavailable" end
    local cam,pitch=cameraRig(ctx,arena,groundY)
