      local x,y=originalToGB(vp,wx,wy,wz,lx,ly,scale,pw,ph)
      if x~=nil then return x,y end
      local kind,side=classifyProjection(arena,wx,wz)
      if not kind then return x,y end
      local a=(side=="player") and anchors.player or anchors.enemy
      if type(a)~="table" then return x,y end
      recovered=recovered+1
      kinds[kind]=(kinds[kind] or 0)+1
      return tonumber(a[1]) or 0,tonumber(a[2]) or 0
    end
    local okRender,canvas=pcall(OW.providerRender,battle,function() end)
    BattleScene.toGB=originalToGB
    BattleCam.rig=originalRig
    bridge.recovered=recovered
    bridge.recoveryKinds=kinds
    if not (okRender and canvas) then
      return nil,okRender and "Dramatic providerRender returned nil" or tostring(canvas)
    end
    if not drawCanvas(ctx,canvas) then return nil,"Importer target composite failed" end
    bridge.successes=bridge.successes+1
    bridge.lastError=nil
    return ctx.marks or true
  end

  local function environment(next,ctx)
    local battle=ctx and ctx.scene and ctx.scene.battle or nil
    if not importerActive(battle) then
      if bridge.hostedBattle~=nil then finishHosted() end
      return next(ctx)
    end
    local ok,result,err=pcall(renderEnvironment,ctx)
    if ok and result then return result end
    bridge.failures=bridge.failures+1
    bridge.lastError=ok and err or tostring(result)
    finishHosted()
    return next(ctx)
  end

  local okHook=pcall(sceneApi.register,mod,"environment",environment,115)
  if not okHook then return end
  if mod.events and type(mod.events.on)=="function" then
    mod.events:on("battle.ended",function() finishHosted() end)
  end
  bridge.installed=true
end)()


