    local view=type(battle._view)=="table" and battle._view or nil
    local model=type(battle._model)=="table" and battle._model or nil
    local source=type(battle.__gen3Source)=="table" and battle.__gen3Source or nil
    for _,obj in ipairs({battle,view or false,model or false,source or false}) do
      if type(obj)=="table" then
        if obj.__mtbHub==true then return "CBE HUB" end
        if obj.__cbeDoublesActive==true then return "CBE DOUBLES" end
        if obj.__cbeBossIntroActive==true then return "CBE BOSS INTRO" end
      end
    end
    -- Public, read-only live boss contract; no private namespace lookup.
    local boss=X.exports and X.exports.bossIntro
    if type(boss)=="table" and type(boss.active)=="function" then
      local ok,value=pcall(boss.active,battle)
      if not ok then return "CBE BOSS STATUS UNAVAILABLE" end
      if value then return "CBE BOSS INTRO" end
    end
    local priority=false
    if C and C.provider and type(C.provider.cameraOwnership)=="function" then
      local ok,policy=pcall(C.provider.cameraOwnership,C.provider)
      priority=ok and type(policy)=="table" and policy.protocol==1 and policy.authority=="priority"
    end
    if not priority then
      local game=ctx.game or battle.game
      local prefs=game and game.save and game.save.colosseumBattle
      if type(prefs)~="table" or prefs.cameraEnabled~=false then return "CBE CAMERA ON" end
    end
    return nil
  end
  -- The published V is Terrarium's voxel namespace. Only PokemonActors is
  -- aliased into it from the integrated arena runtime; CurrentSpriteModels and
  -- BattleDirector are NOT. Capture the actual CurrentSpriteModels argument
  -- when the resident PokemonActors.install is called normally on mods.loaded.
  -- Do not invoke install ourselves or reconstruct another namespace.
  local attach
  local function copyPose(p)
    if not poseOK(p) then return nil end
    return {eye={p.eye[1],p.eye[2],p.eye[3]},focus={p.focus[1],p.focus[2],p.focus[3]},
      fov=p.fov,curve=p.curve or 0,up=p.up and {p.up[1],p.up[2],p.up[3]} or nil}
  end
  local function presentationReady(P,ctx)
    return P==X.CurrentSprites and liveStandalone(ctx) and P.mode=="stadium"
      and P.modeId=="cbe:colosseum-pokemon" and P.actorApi==X.api
      and type(P.stadiumActors)=="table"
  end
  local function memoryFor(P,ctx)
    if not presentationReady(P,ctx) then return nil end
    if not attach(ctx) then return nil end
    local rec=X.live
    if not rec.clock then
      rec.clock={attacks={},faints={},pending={},seen=setmetatable({},{__mode="k"}),events=0}
    end
    return rec.clock
  end
  local function noteError(err)
    X.errors=X.errors+1;X.reason=tostring(err)
  end
  -- Test35: bridge BC's existing semantic move classification across the host's
  -- move-ID translation. The logic event may name SUNNY_DAY/RECOVER while the
  -- resident Colosseum actor stores the resolved numeric source index. Match the
  -- queued/current BC move through its moveDef id/index contract instead of
  -- comparing those two representations literally. No move-name table is added.
  local function semanticEntry35(entry,side,actor)
    if not (type(entry)=="table" and entry.side==side and type(actor)=="table") then return nil end
    local actorId=actor.lastMove
    local actorDef=actor.lastMoveDef
    local def=entry.moveDef
    if actorDef~=nil and def~=nil and actorDef==def then return entry.mode end
    local function same(v)
      return v~=nil and actorId~=nil and tostring(v)==tostring(actorId)
    end
    if same(entry.moveId) then return entry.mode end
    if type(def)=="table" then
      if same(def.index) or same(def.id) or same(def.number) then return entry.mode end
      if type(actorDef)=="table" then
        local ai=actorDef.index or actorDef.id or actorDef.number
        local di=def.index or def.id or def.number
        if ai~=nil and di~=nil and tostring(ai)==tostring(di) then return entry.mode end
      end
    end
    return nil
  end
  local function semanticMode35(side,actor)
    local mode
    mode=semanticEntry35(C and C.currentAttack,side,actor)
    if mode=="self" or mode=="field" or mode=="target" then return mode,"current" end
    local q=C and C.attackQueue
    if type(q)=="table" then
      for _,entry in ipairs(q) do
        mode=semanticEntry35(entry,side,actor)
        if mode=="self" or mode=="field" or mode=="target" then return mode,"queue" end
      end
    end
    local A=state.attack
    if A and A.side==side and actor and actor.lastMove~=nil
        and tostring(A.moveId)==tostring(actor.lastMove) then
      mode=A.mode
      if mode=="self" or mode=="field" or mode=="target" then return mode,"state" end
    end
    -- Final capability fallback: classify the exact move definition Terrarium
    -- attached to the actor. This reuses BC's existing generation classifier.
    local def=actor and actor.lastMoveDef
    if type(def)=="table" then
      if C and C.generation==2 and backends.__gold and type(backends.__gold.classifyAttackMove)=="function" then
        local ok,m=pcall(backends.__gold.classifyAttackMove,state.battle,def)
        if ok and (m=="self" or m=="field" or m=="target") then return m,"actor-def-gen2" end
      end
      local ok,m=pcall(classifyAttackMove,state.battle,def)
      if ok and (m=="self" or m=="field" or m=="target") then return m,"actor-def" end
    end
    return "target","fallback"
  end
  local function captureStart(memory,side,actor)
    local age=actor and tonumber(actor.actionAge)
    if not (actor and actor.action=="attack" and actor.state=="attack"
        and actor.nativeAction and finite(age) and age>=0) then return false end
    local slot=actor.nativeSlot
    local timing=type(slot)=="table" and slot.timing
    local key1=type(timing)=="table" and tonumber(timing[1]) or nil
    local endpoint=type(timing)=="table" and tonumber(timing[2]) or nil
    local source="PKX"
    if not (finite(endpoint) and endpoint>0) then
      endpoint=tonumber(actor.nativeDuration);source="BODY FALLBACK"
    end
    if not (finite(endpoint) and endpoint>0) then
      X.lastClock=side:sub(1,1).." started / timing unavailable"
      return false
    end
    X.serial=X.serial+1;X.clockMoves=X.clockMoves+1
    local semanticMode,semanticSource=semanticMode35(side,actor)
    memory.attacks[side]={side=side,actor=actor,slot=slot,token=X.serial,moveId=actor.lastMove,
      key1=finite(key1) and key1 or nil,endpoint=endpoint,source=source,
      animationSlot=slot and slot.index or actor.nativeClip,
      animationName=actor.nativeActionName or actor.requestedNativeSlot,
      mode=semanticMode,semanticSource=semanticSource}
    X.lastSemantic=side:sub(1,1)..":"..tostring(semanticMode).."/"..tostring(semanticSource)
    memory.pending[side]=nil
    X.lastClock=side:sub(1,1).." native start / "..source
    X.hudUntil=math.max(X.hudUntil or 0,now()+8)
    return true
  end
  local function beforeMove(P,ctx,name)
    if not presentationReady(P,ctx)
        or (name~="battle.presentation_move" and name~="battle.move_used") then return nil end
    local before={}
    for _,side in ipairs({"player","enemy"}) do
      local actor=P.stadiumActors[side] and P.stadiumActors[side].actor
      before[side]={actor=actor,action=actor and actor.action,
        age=actor and actor.actionAge,pending=actor and actor.pendingAttack}
    end
    return before
  end
  local function afterMove(P,ctx,name,payload,before)
    if name~="battle.presentation_move" and name~="battle.move_used" then return end
    local memory=memoryFor(P,ctx)
    if not memory then return end
    -- Match the provider's Gen2 semantic/visible boundary distinction. Its own
    -- handler has already processed this call; BC never emits the event again.
    local battle=ctx.battle
    if name=="battle.move_used" and battle.__cbeGeneration==2
        and battle.__cbePresentationQueueSync==true then return end
    if type(payload)=="table" then
      if memory.seen[payload]==name then return end
      memory.seen[payload]=name
    end
    memory.events=memory.events+1;X.moveEvents=X.moveEvents+1
    local started,queued=false,false
    for _,side in ipairs({"player","enemy"}) do
      local actor=P.stadiumActors[side] and P.stadiumActors[side].actor
      local old=before and before[side]
      local pending=actor and actor.pendingAttack
      if pending and (not old or old.actor~=actor or old.pending~=pending) then
        -- The provider owns this queued request. Observe it; do not replace
        -- its onStarted callback or advance the target's Damage animation.
        memory.pending[side]={actor=actor,request=pending,moveId=pending.moveId}
        X.queuedMoves=X.queuedMoves+1;queued=true
      elseif actor and actor.action=="attack" and actor.actionAge==0
          and (not old or old.actor~=actor or old.action~="attack"
            or old.age~=0 or not memory.attacks[side]) then
        started=captureStart(memory,side,actor) or started
      end
    end
    if not started then
      X.lastClock=queued and "event received / waiting for Damage -> Attack"
        or "event received / no new native attack start"
    end
    X.hudUntil=math.max(X.hudUntil or 0,now()+8)
  end
  local function afterUpdate(P,ctx)
    local memory=X.live and X.live.context==ctx and X.live.clock
    if not memory or not presentationReady(P,ctx) then return end
    for _,side in ipairs({"player","enemy"}) do
      local pending=memory.pending[side]
      if pending then
        local actor=P.stadiumActors[side] and P.stadiumActors[side].actor
        if actor~=pending.actor then
          memory.pending[side]=nil
        elseif actor.pendingAttack~=pending.request then
          if actor.action=="attack" and tostring(actor.lastMove)==tostring(pending.moveId) then
            captureStart(memory,side,actor)
          end
          memory.pending[side]=nil
        end
      end
    end
  end
  -- Test32: Gen3/raw damage presentation gate. The semantic battle event has
  -- already happened upstream. This wrapper delays only CurrentSpriteModels'
  -- visual consumption of battle.damage_dealt while one real source PKX attack
  -- is still inside its authored camera endpoint. No target parsing, HP/input,
  -- actor method, Waza/PKX choice or camera geometry is changed.
  local function priorityColosseum32()
    if attackCameraStyle()~="colosseum" or not enabled() then return false end
    if not (C and C.provider and type(C.provider.cameraOwnership)=="function") then return false end
    local ok,p=pcall(C.provider.cameraOwnership,C.provider)
    return ok and type(p)=="table" and p.protocol==1 and p.authority=="priority"
      and type(p.claims)=="table" and p.claims.attack==true
  end
  local function activeSourceAttack32(P,ctx)
    local memory=memoryFor(P,ctx);if not memory then return nil,"no source clock" end
    local found
    for _,side in ipairs({"player","enemy"}) do
      local shot=memory.attacks[side]
      local actor=P.stadiumActors[side] and P.stadiumActors[side].actor
      local age=actor and tonumber(actor.actionAge)
      if shot and shot.actor==actor and actor.action=="attack" and actor.state=="attack"
          and actor.nativeSlot==shot.slot and finite(age) and age>=0 and age<shot.endpoint then
        if found then return nil,"ambiguous simultaneous attacks" end
        found={side=side,shot=shot,actor=actor,age=age}
      end
    end
    return found,found and nil or "no active source attack"
  end
  local function shouldGateRawDamage32(P,ctx,name,payload)
    if name~="battle.damage_dealt" or not presentationReady(P,ctx) or not priorityColosseum32() then
      return nil,"not gated route"
    end
    local b=ctx and ctx.battle
    -- Exact live R31 route: queueSync is active, but this is NOT Gen2, so
    -- CurrentSpriteModels consumes raw semantic damage immediately. Gen2 keeps
    -- its provider-owned presentation_* boundary and is never touched here.
    if not (b and b.__cbePresentationQueueSync==true and b.__cbeGeneration~=2) then
      return nil,"not non-Gen2 queue-sync raw route"
    end
    if type(payload)=="table" and X.rawDamageSeen[payload] then
      return false,"duplicate queued payload"
    end
    return activeSourceAttack32(P,ctx)
  end
  local function replayRawDamage32(item,reason)
    if not item or item.released then return true end
    item.released=true
    if type(item.payload)=="table" then X.rawDamageSeen[item.payload]=nil end
    local r=pack(pcall(item.original,item.P,item.ctx,item.name,item.payload,unpack_(item.args,1,item.args.n)))
    if not r[1] then noteError(r[2]);return false end
    X.rawDamageReleased=X.rawDamageReleased+1
    X.rawDamageLast=(item.attackSide or "?").." release "..tostring(reason or "endpoint")
    X.hudUntil=math.max(X.hudUntil or 0,now()+8)
    return true
  end
  local function releaseRawDamage32(P,ctx)
    if #X.rawDamagePending==0 then return end
    local keep={}
    for _,item in ipairs(X.rawDamagePending) do
      if item.P~=P or item.ctx~=ctx then
        replayRawDamage32(item,"context changed")
      else
        local shot=item.shot;local actor=item.actor;local age=actor and tonumber(actor.actionAge)
        local still=shot and actor and shot.actor==actor and actor.nativeSlot==shot.slot
          and actor.action=="attack" and actor.state=="attack" and finite(age) and age>=0
        if not still then
          replayRawDamage32(item,"attack ended")
        elseif age>=shot.endpoint then
          replayRawDamage32(item,"PKX +0x14")
        else
          keep[#keep+1]=item
        end
      end
    end
    X.rawDamagePending=keep
  end
  local function flushRawDamage32(reason)
    local q=X.rawDamagePending;X.rawDamagePending={}
    for _,item in ipairs(q) do replayRawDamage32(item,reason or "flush") end
  end

  local function bindDispatcher(P)
    if type(P)~="table" or type(P.event)~="function" or type(P.update)~="function"
        or type(P.stadiumActors)~="table" then
      X.namespaceReason="runtime install supplied no compatible presentation dispatcher"
      return false
    end
    if X.CurrentSprites==P and X.restoreDispatcher then return true end
    if X.restoreDispatcher then X.restoreDispatcher() end
    local eventOriginal,updateOriginal=P.event,P.update
    local eventWrapped,updateWrapped
    eventWrapped=function(self,ctx,name,payload,...)
      if name=="battle.damage_dealt" then
        X.rawDamageEvents=X.rawDamageEvents+1
        local gate,why=shouldGateRawDamage32(self,ctx,name,payload)
        if gate==false then
          X.rawDamageDuplicates=X.rawDamageDuplicates+1
          X.rawDamageLast=tostring(why)
          return nil
        elseif type(gate)=="table" then
          local args=pack(...)
          local item={P=self,ctx=ctx,name=name,payload=payload,args=args,original=eventOriginal,
            attackSide=gate.side,shot=gate.shot,actor=gate.actor,queuedAge=gate.age}
          X.rawDamagePending[#X.rawDamagePending+1]=item
          if type(payload)=="table" then X.rawDamageSeen[payload]=true end
          X.rawDamageHeld=X.rawDamageHeld+1
          X.rawDamageLast=string.format("%s hold %.2f/%.2f",gate.side,gate.age,gate.shot.endpoint)
          X.hudUntil=math.max(X.hudUntil or 0,now()+8)
          return nil
        else
          X.rawDamagePassed=X.rawDamagePassed+1
          X.rawDamageLast=tostring(why or "raw pass")
        end
      end
      local ok,before=pcall(beforeMove,self,ctx,name)
      if not ok then noteError(before);before=nil end
      local result=pack(eventOriginal(self,ctx,name,payload,...))
      local good,err=pcall(afterMove,self,ctx,name,payload,before)
      if not good then noteError(err) end
      return unpack_(result,1,result.n)
    end
    updateWrapped=function(self,ctx,...)
      local result=pack(updateOriginal(self,ctx,...))
      local good,err=pcall(afterUpdate,self,ctx)
      if not good then noteError(err) end
      local released,why=pcall(releaseRawDamage32,self,ctx)
      if not released then noteError(why) end
      return unpack_(result,1,result.n)
    end
    X.CurrentSprites=P;X.runtimeCaptures=X.runtimeCaptures+1
    P.event=eventWrapped;P.update=updateWrapped
    X.restoreDispatcher=function()
      flushRawDamage32("dispatcher restore")
      if P.event==eventWrapped then P.event=eventOriginal end
      if P.update==updateWrapped then P.update=updateOriginal end
      X.CurrentSprites=nil;X.restoreDispatcher=nil
    end
    X.namespaceReason="live arena dispatcher captured from resident install"
    return true
  end
  local function presentationTiming(ctx)
    local P=X.CurrentSprites
    if not P or not presentationReady(P,ctx) then
      X.lastClock=P and "resident arena actor service not selected" or "WAIT live runtime install (restart required)"
      return nil
    end
    -- Test89: switch/capture/exit remain outside this source clock, but faint
    -- now uses the resident actor's actual faintAge. RC 1.7.2 starts that clock
    -- only when the authored faint bank genuinely begins (after pending Damage).
    local phase=ctx.phase
    if phase=="switch" or phase=="capture" or phase=="exit" then return nil end
    local memory=memoryFor(P,ctx)
    if not memory then return nil end
    local attacks,detail={},nil
    for _,side in ipairs({"player","enemy"}) do
      local shot=memory.attacks[side]
      local actor=P.stadiumActors[side] and P.stadiumActors[side].actor
      local age=actor and tonumber(actor.actionAge)
      if shot and shot.actor==actor and actor.action=="attack" and actor.state=="attack"
          and actor.nativeSlot==shot.slot and finite(age) and age>=0 then
        X.clockFrames=X.clockFrames+1
        local active=age<shot.endpoint
        if active then
          attacks[side]={token=shot.token,side=side,moveId=shot.moveId,
            progress=math.max(0,math.min(1,age/shot.endpoint)),
            phase=shot.key1 and age<shot.key1 and "approach" or "action",
            animationSlot=shot.animationSlot,animationName=shot.animationName}
        elseif not shot.released then
          shot.released=true;X.endpointReleases=X.endpointReleases+1
        end
        if not detail or shot.token>(X.detailToken or -1) then
          detail=string.format("%s %.2f/%.2f %s%s",side:sub(1,1),age,shot.endpoint,
            shot.source,active and "" or " RELEASE")
          X.detailToken=shot.token
        end
      end
    end
    X.detailToken=nil
    local faints={}
    memory.faints=memory.faints or {}
    for _,side in ipairs({"player","enemy"}) do
      local row=memory.faints[side] or {}
      local actor=P.stadiumActors[side] and P.stadiumActors[side].actor
      local age=actor and tonumber(actor.faintAge)
      if finite(age) and age>=0 then
        local new=not row.active or row.actor~=actor
          or (finite(row.age) and age+1e-6<row.age)
        if new then X.serial=X.serial+1;row.token=X.serial end
        row.active=true;row.actor=actor;row.age=age
        faints[side]={token=row.token,side=side,age=age}
        local fd=side:sub(1,1).." faint "..string.format("%.2f",age)
        detail=detail and (detail.." | "..fd) or fd
      else
        row.active=false;row.age=nil
      end
      memory.faints[side]=row
    end
    if detail then X.lastClock=detail end
    -- An empty attack contract remains intentional: a logical move memento must
    -- not start the lens before visible dispatch or resurrect after +0x14.
    return {version=1,source="terrarium-live-presentation-event",attacks=attacks,faints=faints}
  end

  -- Exact resident faint visibility for BC's existing sustained Faint Camera.
  -- No provider update/remove call occurs here: terminalComplete/stateDuration
  -- are read-only queries on the already-running actor.
  C.faintStatus=function(side)
    local P=X.CurrentSprites
    local rec=P and P.stadiumActors and P.stadiumActors[side]
    local actor=rec and rec.actor
    if not actor then
      if C.currentFaintSide==side and state.faint.active then return "faint",false end
      return nil,nil
    end
    local age=tonumber(actor.faintAge)
    if finite(age) and age>=0 then
      local done=false
      if type(actor.terminalComplete)=="function" then
        local ok,v=pcall(actor.terminalComplete,actor);done=ok and v==true
      else
        local duration
        if type(actor.terminalDuration)=="function" then
          local ok,v=pcall(actor.terminalDuration,actor,"faint");if ok then duration=tonumber(v) end
        elseif type(actor.stateDuration)=="function" then
          local ok,v=pcall(actor.stateDuration,actor,"faint");if ok then duration=tonumber(v) end
        end
        done=finite(duration) and age>=duration
      end
      return "faint",not done
    end
    if C.currentFaintSide==side and state.faint.active then
      return "faint",tostring(actor.state or "")~="removal" and actor.scene~=nil
    end
    return nil,nil
  end
  -- Test23: live presented-bounds framing, not a claim of retail GSmodel parity.
  -- Normalization is derived from the same row-major matrix and figureScale as
  -- the resident renderer. No optional exact-bound/timing/yaw helper is required.
  local FOV23=math.rad(39.090270996) -- accepted Test12 fallback lens
  local FILL23=.52 -- BC window: approximately 22%-74% screen height; not a retail constant
  local OFFSET23=.04 -- fit between upper status bars and lower dialogue in the supplied Android view
  local function other23(s) return s=="player" and "enemy" or "player" end
  local function v23(x) return type(x)=="table" and finite(x[1]) and finite(x[2]) and finite(x[3]) end
  local function sub23(a,b) return {a[1]-b[1],a[2]-b[2],a[3]-b[3]} end
  local function add23(a,b) return {a[1]+b[1],a[2]+b[2],a[3]+b[3]} end
  local function mul23(a,k) return {a[1]*k,a[2]*k,a[3]*k} end
  local function dot23(a,b) return a[1]*b[1]+a[2]*b[2]+a[3]*b[3] end
  local function cross23(a,b) return {a[2]*b[3]-a[3]*b[2],a[3]*b[1]-a[1]*b[3],a[1]*b[2]-a[2]*b[1]} end
  local function unit23(a)
    if not v23(a) then return nil end
    local n=math.sqrt(dot23(a,a));if n<1e-8 then return nil end
    return mul23(a,1/n),n
  end
  local function point23(m,p,k)
    return {((m[1]*p[1]+m[2]*p[2]+m[3]*p[3])+m[4])*k,
      ((m[5]*p[1]+m[6]*p[2]+m[7]*p[3])+m[8])*k,
      ((m[9]*p[1]+m[10]*p[2]+m[11]*p[3])+m[12])*k}
  end
  local function framingState23(ctx)
    local r=X.live
    if not r or r.context~=ctx then return nil end
    if not r.framing23 then r.framing23={bounds=setmetatable({},{__mode="k"}),
      passiveSide="player",passiveAge=0,lastProgress=tonumber(ctx.progress),lastToken=0} end
    return r.framing23
  end
  local function actor23(side)
    local P=X.CurrentSprites
    local r=P and P.stadiumActors and P.stadiumActors[side]
    return r and r.actor
  end
  local function subject23(ctx,side,R)
    local a=actor23(side)
    if not a or not a.scene or a.state=="faint" or a.recallAge or a.faintAge then return nil,"actor absent/retiring" end
    local m=a.worldMatrix
    if type(m)~="table" then return nil,"matrix not yet rendered" end
    for i=1,12 do if not finite(m[i]) then return nil,"invalid matrix" end end
    -- Follow the actual actorVP contract, never stageScale. Matrices already
    -- contain worldScale; multiplying that a second time was never appropriate.
    local k=(X.api and X.api.worldUnits==true) and 1 or tonumber(ctx.arena.figureScale)
    if not finite(k) or k<=0 then return nil,"figureScale unavailable" end
    local b=a.scene.bounds
    if not (b and v23(b.min) and v23(b.max)) then return nil,"resident bounds unavailable" end
    local cache=R.bounds[a]
    if not cache or cache.scene~=a.scene or cache.bounds~=b then
      local center={(b.min[1]+b.max[1])*.5,(b.min[2]+b.max[2])*.5,(b.min[3]+b.max[3])*.5}
      local corners={}
      for ix=0,1 do for iy=0,1 do for iz=0,1 do
        corners[#corners+1]={ix==0 and b.min[1] or b.max[1],iy==0 and b.min[2] or b.max[2],iz==0 and b.min[3] or b.max[3]}
      end end end
      cache={scene=a.scene,bounds=b,center=center,corners=corners};R.bounds[a]=cache
    end
