  local function aspect23(ctx)
    local s=ctx.services and ctx.services.renderSize
    local w,h=s and tonumber(s.width),s and tonumber(s.height)
    if finite(w) and finite(h) and w>0 and h>0 then return w/h end
    if love and love.graphics and type(love.graphics.getDimensions)=="function" then
      w,h=love.graphics.getDimensions();if w and h and w>0 and h>0 then return w/h end
    end
