  end
  local function posed23(ctx,g,outward,distance)
    local fit,d,up=fit23(g,outward,aspect23(ctx),FILL23)
    if not fit then return nil end
    -- A locked source-path scale avoids breath/pumping through a body clip;
    -- required frustum distance still provides the generic silhouette safety.
    local dist=math.max(fit,tonumber(distance) or fit)
    local focus=sub23(g.center,mul23(up,OFFSET23*math.tan(FOV23*.5)*dist))
    local pose={eye=add23(focus,mul23(d,dist)),focus=focus,fov=FOV23,curve=0}
