        pose={eye=add23(focus,mul23(d2,dist)),focus=focus,fov=FOV23,curve=0} end
    end
    return poseOK(pose) and pose or nil
  end
  -- Test39 reusable subject-centric adaptation layer. The authored camera still
  -- decides direction, cadence and lens. BC only replaces the arena-scale subject
  -- relationship with a stable presented-Pokemon envelope. Snapshots are per
  -- authored phrase/shot so idle animation and PKX breathing move THROUGH the
  -- frame instead of dragging the camera with them.
  local function copySubject39(g)
    if not g then return nil end
    local offsets={}
    for i,p in ipairs(g.offsets or {}) do offsets[i]={p[1],p[2],p[3]} end
    return {actor=g.actor,side=g.side,center={g.center[1],g.center[2],g.center[3]},
      offsets=offsets,radius=g.radius,forward={g.forward[1],g.forward[2],g.forward[3]},
      right={g.right[1],g.right[2],g.right[3]},source=g.source,scale=g.scale}
  end
  local function fitFov39(g,outward,aspect,fill,fov)
    local d=unit23(outward);if not d then return nil end
    fov=tonumber(fov);if not finite(fov) or fov<math.rad(8) or fov>math.rad(120) then fov=FOV23 end
    fill=math.max(.20,math.min(.86,tonumber(fill) or FILL23))
    local right=unit23(cross23({0,1,0},d));if not right then return nil end
    local up=cross23(d,right);local tan=math.tan(fov*.5);local dist=.05
    for _,p in ipairs(g.offsets) do
      local z=dot23(p,d);local x=dot23(p,right);local y=dot23(p,up)
      dist=math.max(dist,z+math.abs(x)/(tan*aspect*fill),
        z+math.abs(y/tan+OFFSET23*z)/fill,z+.05)
