  end
  local function posedFov39(ctx,g,outward,fov,fill,distance,curve)
    local fit,d,up,lens=fitFov39(g,outward,aspect23(ctx),fill,fov)
    if not fit then return nil end
    local dist=math.max(fit,tonumber(distance) or fit)
    local focus=sub23(g.center,mul23(up,OFFSET23*math.tan(lens*.5)*dist))
    local pose={eye=add23(focus,mul23(d,dist)),focus=focus,fov=lens,curve=tonumber(curve) or 0}
    if pose.eye[2]<(tonumber(ctx.groundY) or 0)+.05 then
      local out={d[1],math.max(.12,d[2]),d[3]}
      local f,d2,u2,l2=fitFov39(g,out,aspect23(ctx),fill,lens)
