        dist=math.max(f,dist);focus=sub23(g.center,mul23(u2,OFFSET23*math.tan(l2*.5)*dist))
        pose={eye=add23(focus,mul23(d2,dist)),focus=focus,fov=l2,curve=tonumber(curve) or 0}
      end
