  -- Test40 Intro refinement: keep BC Hero's camera anchor stable, but keep
  -- observing the live presented envelope for APB/silhouette safety.  Test39
  -- froze both anchor and envelope; large animated displacement could therefore
  -- leave the first snapshot (Pidgeotto/Mewtwo).  Here live displacement is
  -- expressed as envelope offsets around the stable phrase anchor, so the body
  -- moves THROUGH the shot.  Required optical distance may expand, never shrink,
  -- during the phrase; the focus itself never chases chest bobbing.
  local function introEnvelope40(snap,live)
    if not (snap and snap.g and live and live.offsets) then return nil end
    local delta=sub23(live.center,snap.g.center)
    local offsets={}
    for i,p in ipairs(live.offsets) do offsets[i]=add23(p,delta) end
    return {actor=live.actor,side=live.side,center=snap.g.center,offsets=offsets,
      radius=live.radius,forward=snap.g.forward,right=snap.g.right,
      source="stable Hero anchor + live APB envelope",scale=live.scale}
  end
  local function introClose39(ctx,basePose,side,chain)
    local R=framingState23(ctx);if not R then return nil end
    local live=subject23(ctx,side,R);if not live then return nil end
    local introTime=tonumber(state.intro.time) or 0
    local snap=R.intro39
    local restart=not snap or snap.side~=side or snap.actor~=live.actor
      or ((not chain) and finite(snap.lastTime) and introTime+0.03<snap.lastTime)
    if restart then
      snap={side=side,actor=live.actor,g=copySubject39(live),lastTime=introTime,fit=0};R.intro39=snap
    else snap.lastTime=introTime end
    local g=introEnvelope40(snap,live) or snap.g
    local outward=poseOK(basePose) and sub23(basePose.eye,basePose.focus) or nil
    if chain then
      local t=now();local c=R.chain39
      if not c or c.side~=side or c.actor~=live.actor then
        c={side=side,actor=live.actor,start=t,base=R.introDirection39 or outward};R.chain39=c
      end
      local d=unit23(c.base or outward or add23(add23(g.forward,mul23(g.right,.7)),{0,.22,0}))
      if not d then return nil end
      local a=math.sin((t-c.start)*.85)*.055
      outward={d[1]*math.cos(a)+d[3]*math.sin(a),math.max(.12,math.min(.45,d[2])),
        d[3]*math.cos(a)-d[1]*math.sin(a)}
    else
      R.chain39=nil
      outward=outward or R.introDirection39 or add23(add23(g.forward,mul23(g.right,.7)),{0,.22,0})
    end
    local d=unit23(outward);if not d then return nil end
    R.introDirection39=d
    local fit=fit23(g,d,aspect23(ctx),FILL23)
    if finite(fit) then snap.fit=math.max(tonumber(snap.fit) or 0,fit) end
    return posed23(ctx,g,d,(snap.fit or 0)>0 and snap.fit or nil)
  end
  -- Test76: doubles subject resolver for the existing authored passive presets.
  -- Stadium 64 / DW3 / Hero already publish one semantic PLAYER or ENEMY subject
  -- per close beat. On a four-position Terrarium battle that old side abstraction
  -- is insufficient: the provider owns two independently presented actors per side.
  -- Keep the preset's authored direction/cadence/lens exactly as-is and resolve
  -- only its semantic subject to one live doubles slot. Environmental / BOTH beats
  -- never enter this resolver and therefore remain the original broad-field pose.
  --
  -- Lane cadence is intentionally derived from the preset's existing cycle token:
  -- even cycle -> left lane, odd cycle -> right lane. Thus a normal Hero
  -- player->enemy cycle photographs one opposing pair, and the next cycle reaches
  -- the other pair. Stadium/DW3 close beats follow the same pair for that cycle
  -- while their wide/orbit vocabulary remains untouched. No random stream, move,
  -- species or provider presentation state is invented or mutated here.
  local function doublesSession76(ctx)
    local N=X.doublesNamespace55
    if not (type(N)=="table" and type(N.DoublesRuntime)=="table"
        and type(N.DoublesPresenter)=="table" and type(N.DoublesPresenter.anchor)=="function"
        and type(ctx)=="table" and type(ctx.battle)=="table") then return nil,nil end
    local s=N.DoublesRuntime.presentation and N.DoublesRuntime.presentation(ctx.battle)
    if not s and N.DoublesRuntime.combat then s=N.DoublesRuntime.combat(ctx.battle) end
    if not (type(s)=="table" and type(s.core)=="table" and type(s.core.slots)=="table"
        and type(s.actors)=="table") then return N,nil end
    return N,s
  end
  local function doublesLane76(token)
    local cycle=tonumber(tostring(token or ""):match("^[^:]+:(%-?%d+):")) or 0
    return (cycle%2==0) and "left" or "right",cycle
  end
  local function doublesSubject76(ctx,side,R,token)
    local N,s=doublesSession76(ctx)
    if not N then return nil,"not a doubles-capable provider",false end
    if not s then return nil,"doubles session unavailable",false end
    if side~="player" and side~="enemy" then return nil,"non-side subject",true end
    local preferred=doublesLane76(token)
    local function liveRecord(lane)
      local id=side.."-"..lane
      local slot=s.core.slots[id]
      local rec=slot and slot.battlerId and s.actors[slot.battlerId]
      local a=rec and rec.actor
      if not (slot and slot.mon and rec and a and rec.visible~=false and rec.structuralHidden~=true) then
        return nil,nil,nil
      end
      if a.state=="faint" or a.recallAge or a.faintAge then return nil,nil,nil end
      return id,slot,a
    end
    local id,slot,a=liveRecord(preferred)
    if not a then
      id,slot,a=liveRecord(preferred=="left" and "right" or "left")
    end
    if not a then return nil,"no live doubles actor for "..side,true end

    local m=a.worldMatrix
    if type(m)~="table" then return nil,"doubles matrix not yet rendered",true end
    for i=1,12 do if not finite(m[i]) then return nil,"invalid doubles matrix",true end end
    local k=(X.api and X.api.worldUnits==true) and 1 or tonumber(ctx.arena and ctx.arena.figureScale)
    if not finite(k) or k<=0 then return nil,"doubles figureScale unavailable",true end
    local b=a.scene and a.scene.bounds
    if not (b and v23(b.min) and v23(b.max)) then return nil,"doubles resident bounds unavailable",true end
    local cache=R.bounds[a]
    if not cache or cache.scene~=a.scene or cache.bounds~=b then
      local center={(b.min[1]+b.max[1])*.5,(b.min[2]+b.max[2])*.5,(b.min[3]+b.max[3])*.5}
      local corners={}
      for ix=0,1 do for iy=0,1 do for iz=0,1 do
        corners[#corners+1]={ix==0 and b.min[1] or b.max[1],iy==0 and b.min[2] or b.max[2],iz==0 and b.min[3] or b.max[3]}
      end end end
      cache={scene=a.scene,bounds=b,center=center,corners=corners};R.bounds[a]=cache
    end
    local center=point23(m,cache.center,k)
    local delta={0,0,0};local anchorKind="doubles resident model centre"
    if type(a.attachment)=="function" then
      local ok,at=pcall(a.attachment,a,"chest")
      local j=ok and type(at)=="table" and tonumber(at.boneIndex)
      local bind=j and a.scene.jointPositions and a.scene.jointPositions[j+1]
      if ok and at and v23(at.position) and v23(bind) then
        delta=sub23(mul23(at.position,k),point23(m,bind,k))
