    if n>0 then forward=unit23({ax/n-center[1],0,az/n-center[3]}) end
    if not forward then
      local c,o=ctx.arena and ctx.arena[side],ctx.arena and ctx.arena[other]
      if type(c)=="table" and type(o)=="table" then
        forward=unit23({o[1]-c[1],0,o[2]-c[2]})
      end
    end
    if not forward then forward=unit23({m[3],0,m[11]}) end
    if not forward then return nil,"doubles fight axis unavailable",true end
    return {actor=a,side=side,slot=id,center=center,offsets=offsets,radius=radius,
      forward=forward,right=cross23({0,1,0},forward),source=anchorKind,scale=k},nil,true
  end

  -- Test41 extends the already accepted Stadium 64 subject-centric adapter to
  -- DW3 Classic without changing either preset's authored pose builder.  The
  -- preset remains the author of direction/cadence/lens; only player/enemy
  -- subject shots are refit around one snapshotted presented Pokemon.  Wide,
  -- both and environmental beats remain the exact authored base pose.  If a
  -- subject beat cannot be represented, the continuity compositor salvages the
  -- gap instead of silently replacing the preset wholesale.
  local function subjectPreset39(ctx,basePose)
    local preset=selectedPreset()
    -- Test42: trust BC's own authored passive-shot token, not the host's coarse
    -- phase label.  Terrarium/CBE can leave ctx.phase=="attack" after the real
    -- PKX/BC attack sentence has ended; the core preset engine has already
    -- returned to Stadium/DW3 at that point and proves it by publishing a fresh
    -- passiveShotToken.  The continuity compositor is only a salvage layer when
    -- no authored preset shot exists this frame.
    if (preset~="stadium" and preset~="dw3" and preset~="portrait_test")
        or state.passiveShotToken==nil then
      return nil,nil,false
    end
    local label=(preset=="stadium") and "STADIUM"
        or ((preset=="dw3") and "DW3" or "HERO PORTRAIT")
    if not poseOK(basePose) then return nil,label.." GAP",true end
    local intent=state.passiveShotIntent
    if intent~="player" and intent~="enemy" then
      return basePose,label.." AUTHORED "..tostring(intent or "wide"),true
    end
    local R=framingState23(ctx);if not R then return nil,"no framing state",true end
    local token=tostring(state.passiveShotToken or (preset..":unknown"))
    local live,why76,doublesActive=doublesSubject76(ctx,intent,R,token)
    if not doublesActive then live=subject23(ctx,intent,R) end
    if not live then return nil,why76 or "subject unavailable",true end
    local slot76=live.slot
    local snap=R.preset39
    if not snap or snap.token~=token or snap.side~=intent or snap.actor~=live.actor
        or snap.slot~=slot76 then
      snap={token=token,side=intent,slot=slot76,actor=live.actor,g=copySubject39(live),fit=0};R.preset39=snap
    end
    local outward=sub23(basePose.eye,basePose.focus)
    local g=snap.g
    local distance=nil
    if preset=="portrait_test" then
      -- Hero Portrait has long 9.4 s subject phrases, so use the same stable-
      -- anchor/live-APB principle accepted for BC Hero Intro.  The focus anchor
      -- does not chase bobbing, but the live envelope may expand the required
      -- fit during the phrase to protect large animated rigs.
      g=introEnvelope40(snap,live) or snap.g
      local fit=fitFov39(g,outward,aspect23(ctx),FILL23,basePose.fov)
      if finite(fit) then snap.fit=math.max(tonumber(snap.fit) or 0,fit) end
      if (tonumber(snap.fit) or 0)>0 then distance=snap.fit end
    end
    local p=posedFov39(ctx,g,outward,basePose.fov,FILL23,distance,basePose.curve)
    if not p then return nil,"subject fit unavailable",true end
    return p,label.." SUBJECT "..tostring(slot76 or intent),true
  end

  -- Test41 continuity bridge for the initial enemy->player Intro seam.  Test39
  -- proved that keeping the completed enemy as a close Hero subject can turn a
  -- host send-out wait into an overlong opponent side-view.  The older BC chain
  -- already retained a proven opening/inter-Intro return camera.  Reuse that
  -- safe camera as a neutral bridge, keep its eye/FOV fixed, ease its LOOK target
  -- toward arena midfield, then add only a tiny target pan.  This is deliberately
  -- the continuity compositor: it fills the gap without becoming either Hero or
  -- the selected passive preset, and without moving the physical eye through CBE.
  local function chainBridge41(ctx,basePose)
    local source=poseOK(state.intro.openingChainCamera) and state.intro.openingChainCamera or basePose
    if not poseOK(source) then return nil end
    local R=framingState23(ctx);if not R then return nil end
    local t=now();local c=R.chain41
    -- openingChainCamera may be refreshed by the core inter-Intro tracker every
    -- frame.  Key the continuity phrase to the semantic enemy->player gap, not
    -- the camera table identity, otherwise the pan would restart every frame.
    local key=tostring(state.intro.openingChainSide39 or "enemy")..">"..tostring(state.intro.pendingPlayer==true)
    if not c or c.key~=key then
      c={key=key,start=t,eye={source.eye[1],source.eye[2],source.eye[3]},
        focus={source.focus[1],source.focus[2],source.focus[3]},fov=source.fov,curve=source.curve}
      R.chain41=c
    end
    local arena=ctx.arena or {};local mid=arena.mid
    local target={c.focus[1],c.focus[2],c.focus[3]}
    if type(mid)=="table" and finite(tonumber(mid[1])) and finite(tonumber(mid[2])) then
      target[1],target[3]=tonumber(mid[1]),tonumber(mid[2])
    end
    local age=math.max(0,t-c.start);local q=smoothstep(math.min(1,age/.85))
    local focus={c.focus[1]+(target[1]-c.focus[1])*q,c.focus[2]+(target[2]-c.focus[2])*q,
      c.focus[3]+(target[3]-c.focus[3])*q}
    -- Fixed eye means no new wall/roof traversal.  Move only the look target,
    -- analogous to the successful Phenac HOLD pan, with amplitude scaled to the
    -- live battlefield span when available.
    if type(arena.player)=="table" and type(arena.enemy)=="table" then
      local dx=(tonumber(arena.enemy[1]) or 0)-(tonumber(arena.player[1]) or 0)
      local dz=(tonumber(arena.enemy[2]) or 0)-(tonumber(arena.player[2]) or 0)
      local span=math.sqrt(dx*dx+dz*dz)
      if span>1e-4 then
        local rx,rz=-dz/span,dx/span;local pan=math.sin(age*.55)*span*.035
        focus[1],focus[3]=focus[1]+rx*pan,focus[3]+rz*pan
      end
    end
    local p={eye={c.eye[1],c.eye[2],c.eye[3]},focus=focus,fov=c.fov,curve=c.curve or 0}
    return poseOK(p) and p or nil
  end

  local function flagBit23(v,m) return math.floor(v/m)%2==1 end
