  local function contact23(shot)
    local a=shot.actor;local name=tostring(shot.animationName or "")
    local flags=SOURCE_ATTACK_FLAGS[tonumber(shot.moveId)]
    if not flags or flagBit23(flags,1) then return false end
    local masked=flagBit23(flags,8) or flagBit23(flags,16) or flagBit23(flags,32) or flagBit23(flags,64)
    return name:match("^physical[ABCDE]$")~=nil and (tonumber(a.lastMoveDef and a.lastMoveDef.power) or 0)>0
      and (not masked or flagBit23(flags,32))
  end
  local function modeVector23(g,u)
    -- Accepted Test12 Mode1 shape; its unit is fitted ONCE to the real rendered
    -- body envelope instead of pretending normalized meshes retain retail units.
    return add23(add23(mul23(g.forward,-35),mul23(g.right,10+30*u)),{0,5.5,0})
  end
  local function shotPose23(ctx,R,g,shot,age)
    local unit=R.unit
    if R.planToken~=shot.token then
      R.planToken=shot.token;R.contact=contact23(shot);R.planForward=g.forward;R.planRight=g.right
      R.unit=nil;unit=nil
      if R.contact then
        unit=0
        local basis={forward=R.planForward,right=R.planRight}
        for i=0,4 do
          local vector=modeVector23(basis,i/4);local _,length=unit23(vector)
          local distance=fit23(g,vector,aspect23(ctx),FILL23)
          if not distance or not length then return nil end
          unit=math.max(unit,distance/length)
        end
        R.unit=unit
      end
    end
    if R.contact then
      local u=math.max(0,math.min(1,age/shot.endpoint))
      local vector=modeVector23({forward=R.planForward,right=R.planRight},u)
      local _,length=unit23(vector)
      return posed23(ctx,g,vector,length*unit),"CONTACT"
    end
    -- Unknown/excluded source families keep a readable subject camera, rather
    -- than being mislabelled as Mode1 or falling back to a whole-arena master.
    local outward=add23(add23(mul23(g.forward,-1),mul23(g.right,.7)),{0,.22,0})
    return posed23(ctx,g,outward),"SUBJECT"
  end
  -- A source self/field visual may legally outlive the Pokemon's body clip.
  -- CurrentSpriteModels owns these already-running attack-role VMs. Reading this
  -- table never starts/advances Waza; it only prevents BC's close passive
  -- selector from cutting to the opponent while the user's own effect is still
  -- being presented.
  local function attackFxAlive34(shot)
    local P=X.CurrentSprites
    if not (shot and P and type(P.moveFxActive)=="table") then return false end
    for _,fx in ipairs(P.moveFxActive) do
      if type(fx)=="table" and fx.role=="attack" and fx.side==shot.side
          and (fx.moveId==nil or tostring(fx.moveId)==tostring(shot.moveId)) then
        local vm=fx.vm
        local inst=fx.wazaInstance
        if (type(vm)=="table" and vm.done~=true)
            or (type(inst)=="table" and inst.done~=true and inst.cancelled~=true) then
          return true
        end
      end
    end
    return false
  end
  local function semanticOutward34(R,g,basePose)
    local outward=poseOK(basePose) and sub23(basePose.eye,basePose.focus) or nil
    if outward then
      R.semanticDirection=outward
    else
      outward=R.semanticDirection
    end
    return outward or add23(add23(g.forward,mul23(g.right,.62)),{0,.22,0})
  end
  local function liveFraming23(ctx,basePose,claims)
    if not presentationReady(X.CurrentSprites,ctx) then return nil end
    local R=framingState23(ctx);if not R then return nil end
    local phase=tostring(ctx.phase or "")
    if phase=="intro" or phase=="switch" or phase=="faint" or phase=="capture" or phase=="exit"
        or (state.intro and state.intro.active) or (state.faint and state.faint.active)
        or (state.battleOpening and state.battleOpening.active) then return nil end
    local t=tonumber(ctx.progress);local dt=0
    if finite(t) and finite(R.lastProgress) then dt=math.max(0,math.min(.25,t-R.lastProgress)) end
    if finite(t) then R.lastProgress=t end
    local memory=X.live.clock;local latest,latestSide
    if memory then for _,side in ipairs({"player","enemy"}) do
      local q=memory.attacks[side]
      if q and (not latest or q.token>latest.token) then latest,latestSide=q,side end
    end end
    if latest and latest.token~=R.lastToken then
      R.lastToken=latest.token
      -- Self/field moves remain visually owned by their user after the body
      -- bank ends; target moves keep Test23's recipient-first passive handoff.
      if latest.mode=="self" or latest.mode=="field" then
        R.passiveSide=latestSide
      else
        R.passiveSide=other23(latestSide)
      end
      R.passiveAge=0;R.semanticDirection=nil
    end
    if latest then
      local semantic=latest.mode=="self" or latest.mode=="field"
      local a=actor23(latestSide);local age=a and tonumber(a.actionAge)
      if claims.attack and a==latest.actor and a.nativeSlot==latest.slot
          and a.action=="attack" and a.state=="attack"
          and finite(age) and age>=0 and age<latest.endpoint then
        local g,why=subject23(ctx,latestSide,R)
        if g then
          local p,kind
          if semantic then
            -- Preserve the existing BC self/field camera direction, but refit it
            -- to the same close live bounds as the accepted Test23 camera.
            local outward=semanticOutward34(R,g,basePose)
            p=posed23(ctx,g,outward);kind=string.upper(latest.mode)
          else
            p,kind=shotPose23(ctx,R,g,latest,age)
          end
          if p then X.frame23Attacks=(X.frame23Attacks or 0)+1;return p,kind.." "..latestSide end
        else X.frame23Missing=why end
      end
      -- Do not let the custom passive selector steal a self/field visual merely
      -- because its PKX body bank reached +0x14. Keep the user's close semantic
      -- direction until the resident source attack FX is actually finished.
      if semantic and (claims.attack or claims.passive) and attackFxAlive34(latest) then
        local g,why=subject23(ctx,latestSide,R)
        if g then
          local p=posed23(ctx,g,semanticOutward34(R,g,basePose))
          if p then
            X.frame23Attacks=(X.frame23Attacks or 0)+1
            return p,string.upper(latest.mode).." FX HOLD "..latestSide
          end
        else X.frame23Missing=why end
      end
      if claims.attack then
        -- Test36: keep Test23's preferred front reaction language, but bound how
        -- far the camera follows the live chest. Ordinary/small reactions retain
        -- full tracking; large recoil/backflip displacement moves THROUGH the
        -- frame once the per-axis tracking allowance is exhausted. This only
        -- changes camera geometry and never touches Actor:hit / native playback.
        local side=other23(latestSide);local target=actor23(side)
        if target and target.state=="hit" and finite(tonumber(target.hitAge)) then
          local g=subject23(ctx,side,R)
          if g then
            local age=tonumber(target.hitAge) or 0
            local rx=R.reaction36
            local restart=(not rx) or rx.actor~=target or rx.side~=side
              or (finite(rx.lastAge) and age+0.02<rx.lastAge)
            if restart then
              rx={actor=target,side=side,center={g.center[1],g.center[2],g.center[3]},
                forward={g.forward[1],g.forward[2],g.forward[3]},
                right={g.right[1],g.right[2],g.right[3]},radius=g.radius,lastAge=age}
              R.reaction36=rx
            end
            rx.lastAge=age
            local delta=sub23(g.center,rx.center)
            local up={0,1,0}
            local function clamp36(v,lim) return math.max(-lim,math.min(lim,v)) end
            local r=math.max(.02,tonumber(rx.radius) or tonumber(g.radius) or .02)
            -- Full-follow allowance before dramatic displacement is allowed to
            -- become visible relative to the camera. Ratios are BC presentation
            -- bounds, not retail/source constants.
            local limR,limU,limF=r*.38,r*.30,r*.48
            local dr=dot23(delta,rx.right);local du=dot23(delta,up);local df=dot23(delta,rx.forward)
            local tracked=add23(rx.center,add23(add23(mul23(rx.right,clamp36(dr,limR)),
              mul23(up,clamp36(du,limU))),mul23(rx.forward,clamp36(df,limF))))
            local cg={actor=g.actor,side=g.side,center=tracked,offsets=g.offsets,radius=g.radius,
              forward=rx.forward,right=rx.right,source=g.source,scale=g.scale}
            local outward=add23(add23(mul23(cg.forward,1),mul23(cg.right,-.65)),{0,.22,0})
            local p=posed23(ctx,cg,outward)
            if p then
              X.frame36Reaction={side=side,age=age,dr=dr,du=du,df=df,
                limR=limR,limU=limU,limF=limF,bounded=(math.abs(dr)>limR or math.abs(du)>limU or math.abs(df)>limF)}
              X.frame23Reactions=(X.frame23Reactions or 0)+1
              return p,(X.frame36Reaction.bounded and "REACTION BOUND " or "REACTION TRACK ")..side
            end
          end
        else
          R.reaction36=nil
        end
      end
    end
    if not claims.passive then return nil end
    -- A coarse phase remaining 'attack' does not own this clock. Finite PKX
    -- ownership ends above; close normal framing resumes immediately afterward.
    R.passiveAge=R.passiveAge+dt
    if R.passiveAge>=200/60 then R.passiveAge=R.passiveAge%(200/60);R.passiveSide=other23(R.passiveSide) end
    local g,why=subject23(ctx,R.passiveSide,R)
    if not g then g,why=subject23(ctx,other23(R.passiveSide),R) end
    if not g then X.frame23Missing=why;return nil end
    local outward
    if poseOK(basePose) and not (state.attack and (state.attack.active or state.attack.pending)) then
      outward=sub23(basePose.eye,basePose.focus);R.passiveDirection=outward
    end
    outward=outward or R.passiveDirection
    if not outward then outward=add23(add23(g.forward,mul23(g.right,.7)),{0,.22,0}) end
    -- Preserve the selected BC preset's azimuth when provided, but not its
    -- arena-wide radius. A stale attack phase uses a bounded gentle subject pan.
    local d=unit23(outward) or {0,.2,1};local angle=math.sin(R.passiveAge*.6)*.07
    outward={d[1]*math.cos(angle)+d[3]*math.sin(angle),math.max(.12,math.min(.45,d[2])),
      d[3]*math.cos(angle)-d[1]*math.sin(angle)}
    local p=posed23(ctx,g,outward)
    if p then X.frame23Passive=(X.frame23Passive or 0)+1;X.frame23Missing=nil;return p,"PASSIVE "..g.side end
    return nil
  end

  local function continuityPose(ctx,base)
    if not (C and C.provider and type(C.provider.cameraOwnership)=="function") then return nil end
    local ok,policy=pcall(C.provider.cameraOwnership,C.provider)
    if not (ok and type(policy)=="table" and policy.protocol==1
        and policy.authority=="priority" and type(policy.claims)=="table") then return nil end
    local claims=policy.claims
    local rec=X.live
    if not rec or rec.context~=ctx then return nil end
    local phase=tostring(ctx.phase or "")
    if phase=="intro" and claims.intro then
      return copyPose(rec.introPose or base),"INTRO HOLD"
    end
    if phase=="passive" and claims.passive then
      return copyPose(rec.passivePose or base),"PASSIVE HOLD"
    end
    if (phase=="attack" or phase=="damage" or phase=="reaction") and claims.attack
        and rec.clock and rec.clock.events>0 and presentationReady(X.CurrentSprites,ctx) then
      -- No attacker-idle gate, and no replay of a native attack camera during
      -- the gaps. Use the last passive/base composition, NOT a frozen attacker
      -- close-up. Full source receiver composition remains a separate test.
      return copyPose(rec.passivePose or base),"BETWEEN-SHOT HOLD"
    end
    return nil
  end

  -- Test55: first BC-owned doubles topology proof.  Do not reuse the singles
  -- player/enemy subject model and do not invoke Terrarium's doubles camera.
  -- Read the provider's four-slot session/anchors, keep the neutral arena eye
  -- exactly on CBE's vetted base-camera position, and fit all occupied slots by
  -- widening the lens only.  This proves four-actor camera ownership without
  -- changing combat, actor presentation, targets, Waza, input, PiP or arena.
  local function doublesMaster55(ctx,base)
    local N=X.doublesNamespace55
    if not (type(N)=="table" and type(N.DoublesRuntime)=="table"
        and type(N.DoublesPresenter)=="table" and type(N.DoublesPresenter.anchor)=="function"
        and type(base)=="table" and poseOK(base)) then return nil,"doubles namespace unavailable" end
    local s=N.DoublesRuntime.presentation and N.DoublesRuntime.presentation(ctx.battle)
    if not s and N.DoublesRuntime.combat then s=N.DoublesRuntime.combat(ctx.battle) end
    if not (type(s)=="table" and type(s.core)=="table" and type(s.core.slots)=="table") then
      return nil,"doubles session unavailable"
    end
    local ids={"player-left","player-right","enemy-left","enemy-right"}
    local points={};local maxH=5
    local ground=tonumber(ctx.groundY) or 0
    local scale=tonumber((ctx.services or {}).figureScale) or tonumber((ctx.arena or {}).figureScale) or .38
    for _,id in ipairs(ids) do
      local slot=s.core.slots[id]
      if slot and slot.mon then
        local ok,x,z=pcall(N.DoublesPresenter.anchor,ctx,id)
        if ok and finite(x) and finite(z) then
          local h=7
          local rec=s.actors and slot.battlerId and s.actors[slot.battlerId]
          local a=rec and rec.actor
          if a then
            h=math.max(3,math.min(26,(tonumber(a.height) or 16)*(tonumber(a.worldScale) or 1)*scale))
          end
          points[#points+1]={x,ground+h*.52,z};maxH=math.max(maxH,h)
        end
      end
    end
    if #points<2 then return nil,"fewer than two doubles slots" end
    local minx,maxx,minz,maxz=points[1][1],points[1][1],points[1][3],points[1][3]
    local y=0
    for _,q in ipairs(points) do
      minx=math.min(minx,q[1]);maxx=math.max(maxx,q[1])
      minz=math.min(minz,q[3]);maxz=math.max(maxz,q[3]);y=y+q[2]
    end
    local focus={(minx+maxx)*.5,y/#points,(minz+maxz)*.5}
    local size=(ctx.services or {}).renderSize or {}
    local aspect=(tonumber(size.width) or 1280)/math.max(1,tonumber(size.height) or 720)
    local fov=math.max(tonumber(base.fov) or .8,math.rad(aspect<1 and 56 or 49))
    return {eye={base.eye[1],base.eye[2],base.eye[3]},focus=focus,fov=fov,curve=0},
      "FOUR-SLOT MASTER "..tostring(#points)
  end

  -- Test56: first doubles action-language proof.  Consume the provider's
  -- resolved move event rather than inferring an opponent from side.  A move
  -- with exactly one DISTINCT live target gets a source->target axis shot; the
  -- same axis hands to the receiving end when Terrarium's actual source chapter
  -- reaches impact.  Self/field/side and multi-target moves intentionally stay
  -- on the accepted Test55 four-slot master until separately proven.
  local function doublesSingleTarget56(ctx,base)
    local N=X.doublesNamespace55
    if not (type(N)=="table" and type(N.DoublesRuntime)=="table"
        and type(N.DoublesPresenter)=="table" and type(N.DoublesPresenter.anchor)=="function"
        and type(base)=="table" and poseOK(base)) then return nil,"doubles namespace unavailable" end
    local s=N.DoublesRuntime.presentation and N.DoublesRuntime.presentation(ctx.battle)
    if not s and N.DoublesRuntime.combat then s=N.DoublesRuntime.combat(ctx.battle) end
    local e=s and s.core and s.core.currentEvent
    if not (type(e)=="table" and e.kind=="move" and type(e.slot)=="string"
        and type(e.targets)=="table" and #e.targets==1 and e.targets[1]~=e.slot) then
      return nil,"not a distinct single-target move"
    end
    local targetId=e.targets[1]
    local sourceSlot=s.core.slots and s.core.slots[e.slot]
    local targetSlot=s.core.slots and s.core.slots[targetId]
    if not (sourceSlot and targetSlot and sourceSlot.mon and targetSlot.mon) then return nil,"move slot unavailable" end
    local okS,sx,sz=pcall(N.DoublesPresenter.anchor,ctx,e.slot)
    local okT,tx,tz=pcall(N.DoublesPresenter.anchor,ctx,targetId)
    if not (okS and okT and finite(sx) and finite(sz) and finite(tx) and finite(tz)) then return nil,"move anchor unavailable" end
    local ground=tonumber(ctx.groundY) or 0
    local scale=tonumber((ctx.services or {}).figureScale) or tonumber((ctx.arena or {}).figureScale) or .38
    local function actorHeight(slot)
      local rec=s.actors and slot.battlerId and s.actors[slot.battlerId]
      local a=rec and rec.actor
      return math.max(3,math.min(26,(tonumber(a and a.height) or 16)*(tonumber(a and a.worldScale) or 1)*scale))
    end
    local sh,th=actorHeight(sourceSlot),actorHeight(targetSlot)
    local source={sx,ground+sh*.52,sz};local target={tx,ground+th*.52,tz}
    local dx,dz=target[1]-source[1],target[3]-source[3]
    local axis=math.sqrt(dx*dx+dz*dz);if axis<.001 then return nil,"degenerate move axis" end
    local fx,fz=dx/axis,dz/axis;local rx,rz=-fz,fx
    local mid={(source[1]+target[1])*.5,(source[2]+target[2])*.5,(source[3]+target[3])*.5}
    local sideDot=(base.eye[1]-mid[1])*rx+(base.eye[3]-mid[3])*rz
    local sign=sideDot<0 and -1 or 1
    local m=s.movePresentation
    local impact=m and m.event==e and m.impactStarted==true
    local focus,range,fov,back,side,lift
    local size=(ctx.services or {}).renderSize or {};local aspect=(tonumber(size.width) or 1280)/math.max(1,tonumber(size.height) or 720)
    if impact then
      -- Receiver-owned edit on the SAME action axis.  Do not guess from side;
      -- an ally target is therefore photographed as an ally target naturally.
      focus={target[1],target[2],target[3]}
      range=math.max(22,th*3.05,axis*.72);fov=math.rad(aspect<1 and 47 or 38.5)
      back=-.12;side=.70;lift=.25
    else
      -- Hold the attacker/effect origin while keeping the chosen recipient in
      -- the sentence.  This leaves room for native run-up/projectile body motion
      -- instead of chasing the actor across the field every frame.
      focus={source[1]+dx*.18,source[2]+(target[2]-source[2])*.18,source[3]+dz*.18}
      range=math.max(23,sh*3.05,axis*.78);fov=math.rad(aspect<1 and 47.5 or 39.5)
      back=.28;side=.74;lift=.27
    end
    range=math.min(range,46)
    local eye={focus[1]-fx*range*back+rx*range*side*sign,
      focus[2]+math.max(3,range*lift),focus[3]-fz*range*back+rz*range*side*sign}
    return {eye=eye,focus=focus,fov=fov,curve=0},
      "SINGLE AXIS "..e.slot.." -> "..targetId..(impact and " IMPACT" or " LAUNCH")
  end

  -- Test57: self-owned doubles presentation.  A provider-resolved SELF move
  -- deserves a one-Pokemon camera sentence rather than dropping to the four-slot
  -- master.  The same subject-owned composition also covers unowned vitality
  -- events such as confusion/recoil/self-cost damage and self-healing.  FIELD and
  -- SIDE remain on Test55's master; multi-target/all-other remain untouched.
  local function doublesSelfOwned57(ctx,base)
    local N=X.doublesNamespace55
    if not (type(N)=="table" and type(N.DoublesRuntime)=="table"
        and type(N.DoublesPresenter)=="table" and type(N.DoublesPresenter.anchor)=="function"
        and type(base)=="table" and poseOK(base)) then return nil,"doubles namespace unavailable" end
    local s=N.DoublesRuntime.presentation and N.DoublesRuntime.presentation(ctx.battle)
    if not s and N.DoublesRuntime.combat then s=N.DoublesRuntime.combat(ctx.battle) end
    local e=s and s.core and s.core.currentEvent
    if type(e)~="table" or type(e.slot)~="string" then return nil,"not a self-owned event" end

    local selfOwned=false
    local label=nil
    if e.kind=="move" and type(e.eventId)=="number" then
      -- Core's bounded target trace is the semantic truth.  SELF/FIELD/SIDE all
      -- intentionally resolve to the source slot, so do not infer SELF merely
      -- because targets[1] == slot.
      for i=#(s.core.targetTrace or {}),1,-1 do
        local row=s.core.targetTrace[i]
        if row and row.presentationEventId==e.eventId then
          if row.mode=="self" then selfOwned=true;label="SELF MOVE" end
          break
        end
      end
    elseif (e.kind=="damage" or e.kind=="heal") and (e.sourceSlot==nil or e.sourceSlot==e.slot) then
      -- Core deliberately leaves recoil/confusion/cost/self-destruction without
      -- an opposing receiving-Waza owner.  Treat that vitality event as belonging
      -- to the affected Pokemon itself.  Target-owned enemy/ally impacts have a
      -- real sourceSlot and therefore never enter this branch.
      selfOwned=true;label=e.kind=="damage" and "SELF DAMAGE" or "SELF HEAL"
    end
    if not selfOwned then return nil,"not a self-owned event" end

    local slot=s.core.slots and s.core.slots[e.slot]
    if not (slot and slot.mon) then return nil,"self slot unavailable" end
    local ok,x,z=pcall(N.DoublesPresenter.anchor,ctx,e.slot)
    if not (ok and finite(x) and finite(z)) then return nil,"self anchor unavailable" end
    local ground=tonumber(ctx.groundY) or 0
    local scale=tonumber((ctx.services or {}).figureScale) or tonumber((ctx.arena or {}).figureScale) or .38
    local rec=s.actors and slot.battlerId and s.actors[slot.battlerId]
    local a=rec and rec.actor
    local h=math.max(3,math.min(26,(tonumber(a and a.height) or 16)*(tonumber(a and a.worldScale) or 1)*scale))
    local focus={x,ground+h*.54,z}

    -- Preserve the arena's established viewing side, but tighten to one subject.
    -- No arbitrary fight target is invented for a SELF action.
    local vx=(base.eye[1] or 0)-focus[1]
    local vz=(base.eye[3] or 0)-focus[3]
    local vl=math.sqrt(vx*vx+vz*vz)
    if vl<.001 then vx,vz,vl=0,1,1 end
    vx,vz=vx/vl,vz/vl
    local rx,rz=-vz,vx
    local range=math.max(18,math.min(34,h*3.15))
    local sideSign=((e.slot=="player-right" or e.slot=="enemy-left") and -1 or 1)
    local eye={focus[1]+vx*range+rx*range*.22*sideSign,
      focus[2]+math.max(3.5,range*.24),focus[3]+vz*range+rz*range*.22*sideSign}
    local size=(ctx.services or {}).renderSize or {}
    local aspect=(tonumber(size.width) or 1280)/math.max(1,tonumber(size.height) or 720)
    local fov=math.rad(aspect<1 and 45 or 37.5)
    return {eye=eye,focus=focus,fov=fov,curve=0},label.." "..e.slot
  end

