      if not (type(parent)=="table" and type(pev)=="table" and type(pev.slot)=="string"
          and type(pev.targets)=="table" and #pev.targets>=1
          and track.source==pev.slot and listed and track.target~=pev.slot) then
        return nil,"retail receiver is not a resolved parent impact"
      end
      if #pev.targets>1 then multiTargets=pev.targets;multiMode="multi-receiver" end
    end
    local phase=Retail59.phase(track,N);if not phase or phase.cameraActive==false then return nil,"source camera phase unavailable" end
    local embedded=math.max(0,math.floor(tonumber(phase.root and phase.root.embeddedSize) or 0))
    if embedded>0 then return nil,"embedded retail camera deferred" end
    local kind=tonumber(phase.sequenceKind);if kind==nil or kind<0 or kind>10 or kind~=math.floor(kind) then return nil,"unsupported retail sequence kind" end

    -- Retail Waza owner: attacker for attack chapter, receiver for damage chapter.
    local ownerId=(track.role=="damage") and track.target or track.source
    local ownerSlot,ownerRec=Retail59.record(s,ownerId);local actor=ownerRec and ownerRec.actor
    local dex=actor and tonumber(actor.dex)
    if not (ownerSlot and ownerSlot.mon and actor and dex) then return nil,"retail source owner unavailable" end
    local selector,bound,timing,cameraEnd,retailHeight=Retail59.bound(dex,kind)
    if selector==nil then return nil,"retail owner metadata unavailable" end

    local ox,oz,odx,odz=N.DoublesPresenter.actorAnchor(ctx,ownerId)
    if not (finite(ox) and finite(oz) and finite(odx) and finite(odz)) then return nil,"retail owner anchor unavailable" end
    local olen=math.sqrt(odx*odx+odz*odz);if olen<.001 then return nil,"retail owner facing unavailable" end
    local ownerYaw=Retail59.atan2(odx/olen,odz/olen)
    local flags=math.max(0,math.floor(tonumber(phase.sequenceFlags) or 0))
    local paramFn=N.WazaHandlers._test.sourceParamsFlags
    if type(paramFn)~="function" then return nil,"retail parameter-mask helper unavailable" end
    local paramsFlags=paramFn(flags,{ox,tonumber(ctx.groundY) or 0,oz})
    local params,why=N.WazaCameraParams.calculate(paramsFlags,selector,bound,ownerYaw)
    if not (type(params)=="table" and params.exact==true) then return nil,"retail CalculateParams: "..tostring(why) end
    local mode,motionKey=Retail59.motion(N,track,phase,dex,flags);if mode==nil then return nil,"retail motion unavailable" end
    local ownerSide=tostring(ownerId):match("^player") and "player" or "enemy"
    local reverse=(ownerSide=="player") and not Retail59.has(flags,0x80) or false
    local sample,whyMotion=N.WazaCameraParams.sampleMotion(mode,params,function(key)return Retail59.rand(motionKey,key) end,
      {rotationBase=ownerYaw,reverse=reverse})
    if not (type(sample)=="table" and sample.scalarFormulaExact==true) then return nil,"retail DoPosition: "..tostring(whyMotion) end

    -- Camera target is source root variant -> the current owner's exact PKX body-map joint.
    local root=phase.root;if type(root)~="table" then return nil,"retail camera root unavailable" end
    local targetSlot=(tonumber(root.mode)==5) and tonumber(root.variant) or 2
    if targetSlot==nil or targetSlot<0 or targetSlot>=16 or targetSlot~=math.floor(targetSlot) then return nil,"retail camera target slot unavailable" end
    local map=type(actor.bodyMap)=="function" and actor:bodyMap() or nil
    local key=Retail59.bodyKeys[targetSlot+1];local bone=key and map and map[key]
    if bone==nil or bone<0 or type(actor.attachmentIndex)~="function" then return nil,"retail camera target joint unavailable" end
    local okAtt,att=pcall(actor.attachmentIndex,actor,bone)
    if not (okAtt and att and type(att.position)=="table") then return nil,"retail camera target unresolved" end
    local focus={att.position[1],att.position[2],att.position[3]}

    -- Keep the complete sentence on the attacker's action axis. Damage is target-owned
    -- for owner-local retail transforms, but does not invert the sentence at impact.
    -- For proven SELF/FIELD/SIDE source-owned moves source==target; the degenerate
    -- action axis intentionally falls back to the live owner's facing basis. Thus
    -- left/right placement is transformed by real slot/facing geometry, not a fixed BC side.
    local asx,asz,afx,afz=N.DoublesPresenter.actorAnchor(ctx,track.source)
    local atx,atz=N.DoublesPresenter.actorAnchor(ctx,track.target)
    local fx,fz
    if role=="attack" and multiTargets and #multiTargets>1 then
      -- A spread action has no single recipient axis. Instantiate the recovered
      -- owner camera from the live attacker's own facing rather than inventing
      -- a BC centroid camera.
      fx,fz=afx,afz
    elseif finite(asx) and finite(asz) and finite(atx) and finite(atz) then
      fx,fz=atx-asx,atz-asz
    else fx,fz=afx,afz end
    local alen=math.sqrt((fx or 0)^2+(fz or 0)^2)
    if alen<.001 then fx,fz=odx,odz;alen=olen end
    fx,fz=fx/alen,fz/alen;local rx,rz=-fz,fx

    -- Test62 generic receiver-displacement safety. Test36 already proved that
    -- ordinary reactions should remain fully live while dramatic recoil/backflip
    -- travel must be allowed to move THROUGH the frame instead of dragging the
    -- camera past the subject. Apply the same geometric law to the retail DAMAGE
    -- sentence's live target joint. No species/move names and no Actor mutation.
    local receiverBounded=false
    if role=="damage" then
      local evId=track.event and track.event.eventId or "?"
      local keyBound=table.concat({tostring(evId),tostring(track.source),tostring(track.target),tostring(kind)},":")
      local db=Retail59.damageBound
      if not db or db.key~=keyBound then
        db={key=keyBound,focus={focus[1],focus[2],focus[3]},forward={fx,0,fz},right={rx,0,rz}}
        Retail59.damageBound=db
      end
      local dxF,dyF,dzF=focus[1]-db.focus[1],focus[2]-db.focus[2],focus[3]-db.focus[3]
      local function clamp62(v,lim) return math.max(-lim,math.min(lim,v)) end
      local ext=bound and bound.source and bound.source.extent or nil
      local radius=math.max(1,((ext and math.max(tonumber(ext[1]) or 0,tonumber(ext[2]) or 0,tonumber(ext[3]) or 0)) or retailHeight or 2)*.5)
      local limR,limU,limF=radius*.38,radius*.30,radius*.48
      local dr=dxF*db.right[1]+dzF*db.right[3]
      local du=dyF
      local df=dxF*db.forward[1]+dzF*db.forward[3]
      receiverBounded=math.abs(dr)>limR or math.abs(du)>limU or math.abs(df)>limF
      focus={db.focus[1]+db.right[1]*clamp62(dr,limR)+db.forward[1]*clamp62(df,limF),
        db.focus[2]+clamp62(du,limU),
