    local axisSign=tostring(track.source):match("^enemy") and -1 or 1
    local frame=math.max(0,multiFrame or (tonumber(track.chapterAge) or 0)*60)
    -- The recovered PKX +0x0C/+0x10/+0x14 contract owns a finite camera
    -- sentence. Do not hold the final source pose through body recovery; 91.9%
    -- of physical rows end camera ownership before the body animation ends.
    if frame>cameraEnd+.001 then return nil,"retail source camera endpoint:"..role end
    local p=math.max(0,math.min(1,frame/cameraEnd))
    local distance=tonumber(sample.distance0) or tonumber(params.distanceMin) or 40
    local angle=tonumber(sample.rotation0) or 0;local lateral
    if mode==0 then distance=(sample.distance0 or distance)+((sample.distance1 or distance)-(sample.distance0 or distance))*p
    elseif mode==1 then
      lateral=(sample.lateral0 or 10)+((sample.lateral1 or sample.lateral0 or 10)-(sample.lateral0 or 10))*p
      angle=math.atan(lateral/math.max(1,distance))
    elseif mode==2 then angle=(sample.rotation0 or angle)+((sample.rotation1 or angle)-(sample.rotation0 or angle))*p end
    local height=tonumber(sample.height) or tonumber(params.heightMin) or 6
    local eye
    if mode~=1 and sample.worldRotationFormulaExact and tonumber(sample.worldRotation0) and tonumber(sample.worldRotation1) then
      local wa=sample.worldRotation0+(sample.worldRotation1-sample.worldRotation0)*p
      eye={focus[1]+math.sin(wa)*distance,focus[2]+height,focus[3]+math.cos(wa)*distance}
    elseif lateral then
