    if type(fovFn)=="function" then
      local decision={retailParams=params,sequenceKind=kind,paramsFlags=paramsFlags,motion=mode,motionSample=sample}
      local okF,value=pcall(fovFn,decision,retailHeight,sample.fovRange or distance,
