    -- established figureScale is the provider-neutral affine for owner-relative Waza cameras.
    local k=tonumber((ctx.services or {}).figureScale) or tonumber(ctx.arena and ctx.arena.figureScale)
    if not (finite(k) and k>0) then return nil,"CBE figureScale unavailable" end
    eye={eye[1]*k,eye[2]*k,eye[3]*k};focus={focus[1]*k,focus[2]*k,focus[3]*k}
    local pose={eye=eye,focus=focus,fov=fov,curve=0}
    if role=="damage" and type(track.target)=="string" then
      Retail59.lastDamagePose[track.target]={pose=copyPose(pose),
        parentEventId=track.parent and track.parent.event and track.parent.event.eventId,
        targetBattlerId=track.targetBattlerId}
    end
    local sourceLabel=semanticMode or multiMode or tostring(track.role or "attack")
    local multiLabel=multiTargets and (" x"..tostring(#multiTargets)) or ""
    return pose,
      "RETAIL SOURCE M"..tostring(mode).." "..sourceLabel..multiLabel.." "..tostring(ownerId)..(receiverBounded and " BOUND" or "")
  end


