  RetailIntro68.ownerScale={[-2]=0.5,[-1]=0.75,[0]=1.0,[1]=1.333299994468689,[2]=2.0,[3]=3.25}

  local function intro68Sample(frame)
    local f=math.max(0,math.min(#RetailIntro68.samples-1,tonumber(frame) or 0))
    local i0=math.floor(f)+1;local i1=math.min(#RetailIntro68.samples,i0+1);local t=f-math.floor(f)
    local a,b=RetailIntro68.samples[i0],RetailIntro68.samples[i1]
    if not (a and b) then return nil end
    local function q(n)return a[n]+(b[n]-a[n])*t end
    return {eye={q(1),q(2),q(3)},focus={q(4),q(5),q(6)},fov=math.rad(55)}
  end
  local function intro68Point(origin,p,figureScale,stageScale,ownerScale,yaw,reverse)
    local ox,oy,oz=origin[1]*figureScale,origin[2]*figureScale,origin[3]*figureScale
    local q=stageScale*ownerScale
    local x,y,z=p[1]*q,p[2]*q,p[3]*q
    if reverse then x=-x end
    local cs,sn=math.cos(yaw),math.sin(yaw)
    return {ox+cs*x+sn*z,oy+y,oz-sn*x+cs*z}
  end
  function RetailIntro68.state(ctx)
    local N=X.doublesNamespace55
    local D=N and N.DoublesRuntime
    local s=D and D.presentation and D.presentation(ctx and ctx.battle)
    if not s and D and D.presentation then s=D.presentation() end
    if not s and D and D.combat then s=D.combat(ctx and ctx.battle) end
    if not s and D and D.combat then s=D.combat() end
    if not s then return nil end
    local current=s.core and s.core.currentEvent
    local openingCurrent=type(current)=="table" and current.kind=="send" and current.opening==true
    local chosen
    -- Exact Terrarium 1.7.1 / RC 1.7.2 load the source module as
    -- namespace.DoublesRelease, while Presenter.lua checks V.ReleasePresentation.
    -- Consequently r.release is never created on these builds.  The provider's
    -- releaseStarted/releaseAge clock is nevertheless unconditional and is the
    -- exact lifecycle boundary immediately after trainer throw.  Observe that
    -- real provider clock directly; do not patch/mutate the provider namespace.
    for _,rec in ipairs(s.actorOrder or {}) do
      local send=rec and rec.sendout
      local ev=send and send.event
      if type(ev)=="table" and ev.kind=="send" and ev.opening==true
          and send.releaseStarted==true and finite(tonumber(send.releaseAge)) then
        if ev==current then chosen={rec=rec,send=send,event=ev};break end
        if not chosen then chosen={rec=rec,send=send,event=ev} end
      end
    end
    local providerPhase=s.doublesCamera and s.doublesCamera.phase or nil
    if chosen then return s,chosen.event,chosen.rec,chosen.send,providerPhase,true end
    return s,current,nil,nil,providerPhase,openingCurrent
  end
  local function intro71RevealPlan(ctx,r,send,actor,dex,selector,ownerYaw)
    local N=X.doublesNamespace55
    if not (N and N.WazaCameraParams and type(N.WazaCameraParams.calculate)=="function"
        and type(N.WazaCameraParams.sampleMotion)=="function"
        and type(N.WazaCameraParams.motionOptionsForPokemonDex)=="function") then
      return nil,"retail owner camera helpers unavailable"
    end
    -- sequence=NULL / passive-owner retail grammar.  GC6E01 passes camera params
    -- flag 0x4 here and admits the same finite 3/0/1/2 owner-camera vocabulary.
    -- The shared HSD RNG seed/interleaving is still unknown, exactly as in
    -- accepted Test59; choose deterministically *inside* the exact legal family
    -- and preserve non-repeat behaviour rather than inventing a BC shot.
    local _,bound,timing,cameraEnd,retailHeight=Retail59.bound(dex,0) -- source idle/current-owner bound
    if not (bound and timing and finite(cameraEnd)) then return nil,"retail idle owner metadata unavailable" end
    local params,why=N.WazaCameraParams.calculate(4,selector,bound,ownerYaw)
    if not (type(params)=="table" and params.exact==true) then
      return nil,"retail owner CalculateParams: "..tostring(why)
    end
    local ev=send and send.event
    local key=table.concat({tostring(ev and ev.eventId or "opening"),tostring(r and r.slot or "?"),tostring(dex),tostring(selector)},":")
    local cached=RetailIntro68.revealPlan
    if cached and cached.key==key then return cached end
    local options=N.WazaCameraParams.motionOptionsForPokemonDex(4,dex)
    if type(options)~="table" or #options<1 then return nil,"retail owner motion set unavailable" end
    local pool={}
    for _,mode in ipairs(options) do
      if #options==1 or mode~=RetailIntro68.lastRevealMode then pool[#pool+1]=mode end
    end
    if #pool==0 then pool=options end
    local idx=math.min(#pool,math.floor(Retail59.rand(key,"intro-owner-mode")*#pool)+1)
    local mode=pool[idx]
    local sample,whyMotion=N.WazaCameraParams.sampleMotion(mode,params,
      function(drawKey)return Retail59.rand(key,"intro-owner:"..tostring(drawKey))end,
      {rotationBase=ownerYaw,reverse=tostring(r.slot or ""):match("^player")~=nil})
    if not (type(sample)=="table" and sample.scalarFormulaExact==true) then
      return nil,"retail owner DoPosition: "..tostring(whyMotion)
    end
    cached={key=key,mode=mode,sample=sample,params=params,bound=bound,timing=timing,
      cameraEnd=cameraEnd,retailHeight=retailHeight}
    RetailIntro68.revealPlan=cached;RetailIntro68.lastRevealMode=mode
    return cached
  end

  local function intro71OwnerReveal(ctx,r,send,clock)
    local N=X.doublesNamespace55
    local actor=r and r.actor;local dex=actor and tonumber(actor.dex)
    local sm=actor and actor.sourceMetadata
    local selector=sm and tonumber(sm.scaleSelector~=nil and sm.scaleSelector or sm.sequenceKind) or nil
    local md=dex and Retail59.meta[dex]
    if selector==nil then selector=md and tonumber(md[1]) end
    if not (actor and dex and selector~=nil) then return nil,"retail reveal owner unavailable" end

    local okA,ox,oz,dx,dz=pcall(N.DoublesPresenter.actorAnchor,ctx,r.slot)
    if not (okA and finite(ox) and finite(oz) and finite(dx) and finite(dz)) then
      return nil,"retail reveal owner anchor unavailable"
    end
    local olen=math.sqrt(dx*dx+dz*dz);if olen<.001 then return nil,"retail reveal owner facing unavailable" end
    local fx,fz=dx/olen,dz/olen;local rx,rz=-fz,fx
    local ownerYaw=Retail59.atan2(fx,fz)
    local plan,why=intro71RevealPlan(ctx,r,send,actor,dex,selector,ownerYaw)
    if not plan then return nil,why end

    -- sequence=NULL targets cameraParams+0x54: the owner's chest body slot.
    local map=type(actor.bodyMap)=="function" and actor:bodyMap() or nil
    local bone=map and map[Retail59.bodyKeys[3]] -- chest
    if bone==nil or bone<0 or type(actor.attachmentIndex)~="function" then
      return nil,"retail reveal chest unavailable"
    end
    local okAtt,att=pcall(actor.attachmentIndex,actor,bone)
    if not (okAtt and att and type(att.position)=="table"
        and finite(tonumber(att.position[1])) and finite(tonumber(att.position[2])) and finite(tonumber(att.position[3]))) then
      return nil,"retail reveal chest unresolved"
    end
    local focus={tonumber(att.position[1]),tonumber(att.position[2]),tonumber(att.position[3])}

    -- Retail ball_open owns the optical opening through frame 50: the authored
    -- HSD eye/focus curve itself ends at 35 and is held while the remaining
    -- energy chapter completes.  The Pokemon owner becomes visible at frame 50.
    -- From that exact provider/source boundary onward, photograph the live owner
    -- with the recovered sequence=NULL Colowaza camera grammar rather than
    -- stretching the ball camera into the model volume.
    local revealFrame=math.max(0,(tonumber(clock) or 50)-50)
    local frame=math.min(revealFrame,plan.cameraEnd)
    local raw=math.max(0,math.min(1,frame/math.max(1,plan.cameraEnd)))
    local sample=plan.sample
    local distance=tonumber(sample.distance0) or tonumber(plan.params.distanceMin) or 40
    if sample.mode==0 and tonumber(sample.distance1) then
      distance=distance+(sample.distance1-distance)*raw
    end
    local height=tonumber(sample.height) or tonumber(plan.params.heightMin) or 6
    local eye
    if sample.mode==1 and tonumber(sample.lateral0) and tonumber(sample.lateral1) then
      local lateral=sample.lateral0+(sample.lateral1-sample.lateral0)*raw
      -- Test74: actorAnchor points TOWARD the other side. The old negative
      -- forward component photographed the back of every mode-1 intro owner.
      -- Keep the source lateral/range/height sample, on the visible front side.
      eye={focus[1]+fx*distance+rx*lateral,focus[2]+height,focus[3]+fz*distance+rz*lateral}
    elseif tonumber(sample.worldRotation0) and tonumber(sample.worldRotation1) then
      local theta=sample.worldRotation0+(sample.worldRotation1-sample.worldRotation0)*raw
      eye={focus[1]+math.sin(theta)*distance,focus[2]+height,focus[3]+math.cos(theta)*distance}
    else
      return nil,"retail reveal rotation unavailable"
    end

    -- Test74 intro-only presentation guard. Source world-yaw/reverse samples
    -- can land behind a normalized/rotated provider owner. Reflect only that
    -- backward component through the live owner plane: preserve radius, height
    -- and chosen lateral side, rather than inventing a left/right preset. This
    -- is a BC front-reveal policy, not a new claim about every retail Waza shot.
    local vx,vz=eye[1]-focus[1],eye[3]-focus[3]
    local flat=math.sqrt(vx*vx+vz*vz)
    local front=vx*fx+vz*fz
    local lateral=vx*rx+vz*rz
    if flat>.001 then
      -- Test77 intro-only presentation policy: a send-in is a reveal, never a
      -- profile/rear study. Keep the source-selected radius, height and lateral
      -- sign, but require the forward component to be at least as strong as the
      -- lateral component. The translated provider shot therefore stays inside
      -- the exact front quarter-plane (<=45 degrees from owner-facing), so no
      -- send-in becomes side-dominant. Attack/passive Waza cameras retain their
      -- complete source-admitted 3/0/1/2 vocabulary.
      local minFront=flat*math.cos(math.pi*.25)
      if front<minFront then
        front=minFront
        local lat=math.sqrt(math.max(0,flat*flat-front*front))
        if lateral<0 then lat=-lat end
        eye[1]=focus[1]+fx*front+rx*lat
        eye[3]=focus[3]+fz*front+rz*lat
      end
    end

    local fov=math.rad(39.090270996)
    local fovFn=N.WazaHandlers and N.WazaHandlers._test and N.WazaHandlers._test.sourceCameraFov
    if type(fovFn)=="function" then
      local decision={retailParams=plan.params,sequenceKind=0,paramsFlags=4,motion=plan.mode,motionSample=sample}
      local okF,value=pcall(fovFn,decision,plan.retailHeight,sample.fovRange or distance,
        Retail59.hash(plan.key),frame,plan.timing)
      if okF and finite(value) then fov=value end
    end

    -- Same proven source->CBE affine used by Test59–63 owner cameras: live
    -- owner/joint geometry remains pre-figure-scale, then eye+interest are moved
    -- together into final CBE camera space.  No guessed intro distance/zoom.
    local k=tonumber((ctx.services or {}).figureScale) or tonumber(ctx.arena and ctx.arena.figureScale)
    if not (finite(k) and k>0) then return nil,"CBE figureScale unavailable" end
    eye={eye[1]*k,eye[2]*k,eye[3]*k};focus={focus[1]*k,focus[2]*k,focus[3]*k}
    return {eye=eye,focus=focus,fov=fov,curve=0},
      "RETAIL OWNER REVEAL M"..tostring(plan.mode).." "..tostring(r.slot or "?").." F"..string.format("%.1f",frame)
  end

  function RetailIntro68.pose(ctx,r,send)
    if not (send and send.releaseStarted and finite(tonumber(send.releaseAge)) and r) then
      return nil,"provider release clock unavailable"
    end
    local N=X.doublesNamespace55
    if not (N and N.DoublesPresenter and type(N.DoublesPresenter.anchor)=="function") then
      return nil,"provider release anchor unavailable"
    end
    local actor=r.actor;local dex=actor and tonumber(actor.dex)
    local sm=actor and actor.sourceMetadata
    local selector=sm and tonumber(sm.scaleSelector~=nil and sm.scaleSelector or sm.sequenceKind) or nil
    local md=dex and Retail59.meta[dex]
    if selector==nil then selector=md and tonumber(md[1]) end
    local ownerScale=selector~=nil and RetailIntro68.ownerScale[selector] or nil
    if selector~=nil and ownerScale==nil then ownerScale=1.0 end
    if not (dex and selector~=nil and ownerScale) then return nil,"retail owner selector unavailable" end

    local figureScale=tonumber(ctx and ctx.arena and ctx.arena.figureScale)
      or tonumber(ctx and ctx.services and ctx.services.figureScale)
    local stageScale=tonumber(ctx and ctx.arena and ctx.arena.stageScale) or .25
    if not (finite(figureScale) and figureScale>0 and finite(stageScale) and stageScale>0) then
      return nil,"source scale unavailable"
    end

    local clock=math.max(0,tonumber(send.releaseAge) or 0)*60
    if clock>=50 then
      return intro71OwnerReveal(ctx,r,send,clock)
    end

    -- Frames 0..50 are the exact ItemBallData ball_open optical sentence.  The
    -- embedded HSD camera curve ends at frame 35; hold its authored endpoint
    -- only until the source release-energy boundary at frame 50, never through
    -- the Pokemon reveal.  Keep Test69's corrected owner/model orientation and
    -- ball/release origin for this ball-owned phase.
    local okA,x,z,dx,dz=pcall(N.DoublesPresenter.anchor,ctx,r.slot)
    if not (okA and finite(x) and finite(z) and finite(dx) and finite(dz)) then
      return nil,"provider release anchor unavailable"
    end
    local sourceOrigin={x/figureScale,((tonumber(ctx.groundY) or 0)+3.85)/figureScale,z/figureScale}
    local fl=math.sqrt(dx*dx+dz*dz);if fl<.0001 then return nil,"release facing unavailable" end
    local fx,fz=dx/fl,dz/fl
    local yaw=Retail59.atan2(fx,fz)
    local side=tostring(r.slot or ""):match("^player") and "player" or "enemy"
    local reverse=(side=="player")
    local sample=intro68Sample(math.min(35,clock));if not sample then return nil,"ball_open camera sample unavailable" end
    local eye=intro68Point(sourceOrigin,sample.eye,figureScale,stageScale,ownerScale,yaw,reverse)
    local focus=intro68Point(sourceOrigin,sample.focus,figureScale,stageScale,ownerScale,yaw,reverse)
    if not (eye and focus) then return nil,"ball_open transform unavailable" end
    return {eye=eye,focus=focus,fov=sample.fov,curve=0},
      "RETAIL BALL_OPEN "..tostring(r.slot or "?").." F"..string.format("%.1f",math.min(35,clock))
  end

  -- Test75: Test74 opening owner with visible throw completion and pre-reveal staging.
  -- Only camera state is cached here. No provider events, clocks, input,
