  -- below without modification after the last initial send.
  local Opening74={}
  local function intro73Upvalue(fn,key,indices)
    if type(fn)~="function" or not (debug and type(debug.getupvalue)=="function") then return nil end
    local i=indices[key]
    if i then
      local name,v=debug.getupvalue(fn,i)
      if name==key then return v end
      indices[key]=nil
    end
    for n=1,64 do
      local name,v=debug.getupvalue(fn,n)
      if not name then break end
      if name==key then indices[key]=n;return v end
    end
    return nil
  end
  function Opening74.session(s)
    local core=s and s.core
    if not core then Opening74.current=nil;return nil end
    local b=Opening74.current
    if not b or b.core~=core then
