    if type(e)=="table" and e.kind=="send" and e.opening==true then return true end
    -- Core.new queues the encounter message before the actual opening sends.
    -- Inspect event semantics, never localized message text or species names.
    if e==nil or (type(e)=="table" and e.kind=="message") then
