    end
    if not rec.verified then return nil,"trainer source contract unavailable" end
    local active=intro73Upvalue(rec.status,"activeNow",rec.si)
    local scene=intro73Upvalue(rec.status,"scene",rec.si)
    local k=intro73Upvalue(rec.status,"MODEL_SCALE",rec.si)
    if not active or type(scene)~="table" or not finite(k) or k<=0 then return nil,"trainer not rendered" end
    local entry=side=="enemy" and obj.entryPose or intro73Upvalue(rec.draw,"entryPose",rec.di)
    if type(entry)~="function" then return nil,"trainer entry pose unavailable" end
    local ok,p=pcall(entry,obj)
    if not (ok and type(p)=="table" and finite(p.x) and finite(p.y) and finite(p.z)
        and finite(p.yaw) and (tonumber(p.progress) or 0)>=.03) then return nil,"trainer entering" end
    local bounds=scene.bounds
    if rec.scene~=scene or rec.scale~=k or rec.bounds~=bounds then
      local mn=type(bounds)=="table" and bounds.min
      local mx=type(bounds)=="table" and bounds.max
