    local q=rec.center;local cs,sn=math.cos(p.yaw),math.sin(p.yaw)
    local lift=(X.providerContract=="RC-1.7.2" or X.providerContract=="1.7.4")
      and ctx.arena.liveField and tonumber(ctx.arena.groundY) or 0
    local focus={p.x+cs*q[1]+sn*q[3],p.y+q[2]+(lift or 0),p.z-sn*q[1]+cs*q[3]}
    local pokemon=ctx.arena.pokemon
    local own=pokemon and pokemon[side]
    local other=pokemon and pokemon[side=="player" and "enemy" or "player"]
    -- Context.arena also exposes the already-normalized battle axis directly.
    own=own or (side=="player" and ctx.arena.visualPlayer or ctx.arena.visualEnemy)
    other=other or (side=="player" and ctx.arena.visualEnemy or ctx.arena.visualPlayer)
    if not (type(own)=="table" and type(other)=="table") then return nil,"trainer facing unavailable" end
    local dx,dz=(tonumber(other[1]) or 0)-(tonumber(own[1]) or 0),
      (tonumber(other[2]) or 0)-(tonumber(own[2]) or 0)
    local len=math.sqrt(dx*dx+dz*dz)
    if len<.0001 then return nil,"trainer facing degenerate" end
    local fov=math.rad(39.090270996)
    local aspect=1
    if love and love.graphics and type(love.graphics.getDimensions)=="function" then
      local okD,w,h=pcall(love.graphics.getDimensions)
      if okD and finite(w) and finite(h) and w>0 and h>0 then aspect=w/h end
    end
    local halfAngle=math.min(fov*.5,math.atan(math.tan(fov*.5)*aspect))
    local range=rec.radius/math.sin(halfAngle)
    return {eye={focus[1]+dx/len*range,focus[2],focus[3]+dz/len*range},
      focus=focus,fov=fov,curve=0},"BC OPENING "..string.upper(side).." TRAINER HOLD"
  end

  function Opening74.clock(s)
    local t=tonumber(s and s.visualClock)
    if not finite(t) then t=tonumber(s and s.core and s.core.clock) end
    t=finite(t) and math.max(0,t) or 0
    -- Test77's pre-native gate intentionally prevents Terrarium's own visual/core
    -- clocks from advancing. Keep BC's camera-only establishing motion alive on
    -- the same fixed-step dt without writing either provider clock.
    local b=Opening74.current
    if b and s and b.core==s.core then t=t+(tonumber(b.clockOffset77) or 0) end
    return t
  end
  function Opening74.pan(p,age,degrees,period)
    if not poseOK(p) then return nil end
    local out=copyPose(p)
    local dx,dz=p.focus[1]-p.eye[1],p.focus[3]-p.eye[3]
    local flat=math.sqrt(dx*dx+dz*dz)
    if flat<.001 then return out end
    local dist=math.sqrt(flat*flat+(p.focus[2]-p.eye[2])^2)
    local a=math.min(math.rad(degrees),p.fov*.045)
    local phase=math.max(0,tonumber(age) or 0)*2*math.pi/period
    local sway=math.sin(phase)*dist*math.tan(a)
    out.focus[1]=out.focus[1]-dz/flat*sway
    out.focus[3]=out.focus[3]+dx/flat*sway
    out.focus[2]=out.focus[2]+math.sin(phase*.73)*dist*math.tan(a*.22)
    -- A moving optical pan, not an eye orbit through unknown arena geometry.
    -- Re-evaluate from RAW pose on every call; never accumulate camera drift.
    return out
  end
  function Opening74.wide(ctx,s,b)
    if not poseOK(b.wideRaw) then
      local base=baseCamera(ctx.arena)
      local p=doublesMaster55(ctx,base)
      local raw=copyPose(poseOK(p) and p or base)
      local arena=ctx.arena or {}
      local a=arena.visualPlayer or arena.player or (arena.pokemon and arena.pokemon.player)
      local z=arena.visualEnemy or arena.enemy or (arena.pokemon and arena.pokemon.enemy)
      local mid=arena.mid
      if not (type(mid)=="table" and finite(tonumber(mid[1])) and finite(tonumber(mid[2])))
          and type(a)=="table" and type(z)=="table" then
        mid={(tonumber(a[1]) or 0)+(tonumber(z[1]) or 0),(tonumber(a[2]) or 0)+(tonumber(z[2]) or 0)}
        mid[1],mid[2]=mid[1]*.5,mid[2]*.5
      end
      if type(a)=="table" and type(z)=="table" and type(mid)=="table"
          and finite(tonumber(mid[1])) and finite(tonumber(mid[2])) then
        local ax=(tonumber(z[1]) or 0)-(tonumber(a[1]) or 0)
        local az=(tonumber(z[2]) or 0)-(tonumber(a[2]) or 0)
        local al=math.sqrt(ax*ax+az*az)
        local ex=raw.eye[1]-tonumber(mid[1]);local ez=raw.eye[3]-tonumber(mid[2])
        local er=math.sqrt(ex*ex+ez*ez)
        if al>.001 and er>.001 then
          ax,az=ax/al,az/al
          local rx,rz=-az,ax
          if ex*rx+ez*rz<0 then rx,rz=-rx,-rz end
          raw.eye[1]=tonumber(mid[1])+rx*er
          raw.eye[3]=tonumber(mid[2])+rz*er
          raw.focus[1]=tonumber(mid[1]);raw.focus[3]=tonumber(mid[2])
          b.wideMid={tonumber(mid[1]),tonumber(mid[2])};b.wideRadius=er
          b.wideAngle=Retail59.atan2(raw.eye[1]-tonumber(mid[1]),raw.eye[3]-tonumber(mid[2]))
        end
      end
      b.wideRaw=raw;b.wideAt=Opening74.clock(s)
    end
    local out=copyPose(b.wideRaw)
    if out and b.wideMid and finite(b.wideRadius) and b.wideRadius>.001 and finite(b.wideAngle) then
      local age=Opening74.clock(s)-(b.wideAt or 0)
      -- Retail's ordinary opening begins with a low arena-establishing lateral
      -- sweep rather than a fixed high corner. Preserve the proven master
      -- range/height/lens, rotate only its stage-relative bearing, and keep the
      -- movement bounded for an indefinitely held manual encounter prompt.
      local orbit=math.sin(age*2*math.pi/12.0)*math.rad(7.0)
      local ang=b.wideAngle+orbit
      out.eye[1]=b.wideMid[1]+math.sin(ang)*b.wideRadius
      out.eye[3]=b.wideMid[2]+math.cos(ang)*b.wideRadius
    else
      out=Opening74.pan(b.wideRaw,Opening74.clock(s)-(b.wideAt or 0),3.0,10.0)
    end
    return out,"BC BASIC BATTLE INTRO - ARENA ORBIT"
  end
  function Opening74.owner(s,b)
    return Opening74.pan(b.ownerRaw,Opening74.clock(s)-(b.ownerAt or 0),1.1,8.2)
  end
  function Opening74.encounterView(ctx,s,b)
    -- The provider clears native single-battle trainer flags at doubles entry.
    -- Core's real encounter message now owns that semantic phase. Translate
    -- it into a BC-PRIVATE view for the existing Phenac director/input guard;
    -- never restore flags or insert messages in the actual provider screen.
    local src=ctx.battle or s.screen or {}
    local view=b.fullSource or {};b.fullSource=view
    for k in pairs(view) do view[k]=nil end
    for k,v in pairs(src) do view[k]=v end
    view.game=src.game or ctx.game or (s.screen and s.screen.game)
    view.kind="trainer";view.wild=false
    view.showEnemyTrainer=true;view.showPlayerBack=true
    view.enemySendingOut=false;view.sendingOut=false;view.phase="intro"
    return view
  end
  function Opening74.full(ctx,s,b)
    local full=state.battleOpening
    if not full or (b.fullConsidered and not b.fullOwned) then return nil end
    local view=Opening74.encounterView(ctx,s,b)
    if not b.fullConsidered then
      b.fullConsidered=true
      local style,class=full.optionStyle(view)
      local game=view.game
      -- Read the already-existing provider preference table without invoking
      -- BattleSettings.prefs(), whose default-initialisation path writes saves.
      local prefs
      if game and game.save then
        prefs=type(game.save.terrariumBattle)=="table" and game.save.terrariumBattle
          or (type(game.save.colosseumBattle)=="table" and game.save.colosseumBattle or nil)
      end
      local known=X.providerContract=="1.7.1" or X.providerContract=="RC-1.7.2"
        or X.providerContract=="1.7.4"
      local staged=known and ctx.services and ctx.services.cbeStandalone==true
        and ctx.arena and not ctx.arena.liveField
        and type(ctx.arena.visualPlayer)=="table" and type(ctx.arena.visualEnemy)=="table"
      -- The first staged draw can precede Runtime's first assignment to Core.
      -- Preserve the explicit saved manual preference as the fallback for unknown
      -- providers. Test77's exact-provider native gate below also makes AUTO flow
      -- safe without changing the user's setting: it holds only the pre-native
      -- presentation interval, then resumes the untouched provider update.
      local manual=s.core.autoProgress==false or (s.core.autoProgress==nil
        and prefs and prefs.autoProgressEnabled==false)
      -- Test77: exact supported Terrarium builds may keep AUTO BATTLE FLOW on.
      -- The outer native gate below prevents synthetic acknowledgement while
      -- Phenac's swoop owns the pre-native interval, then releases unchanged
      -- Core progression at HOLD. Unknown providers still require manual flow.
      local flowSafe=manual or state.cbeOpeningAutoGate77==true
      -- Yield only when Boss Intro ACTUALLY owned this encounter. Its saved ON
      -- toggle also covers ordinary trainers where Boss Intro correctly declines;
      -- suppressing Phenac merely because that global toggle is enabled would
      -- leave those ordinary battles with no selected full intro at all.
      local bossSeen=state.cbeBossIntroSeen77 and s.screen and state.cbeBossIntroSeen77[s.screen]
      local allowed=staged and flowSafe and not bossSeen
      if style~="off" and allowed then
        if not (full.active or full.pending) then
          -- Late admission after the real standalone arena is known. The
          -- battle.started path may only have seen the unrelated indoor map.
          full.clear();full.style=style;full.scopeClass=class
          full.pending=true;full.duration=13.20
          full.releaseScopeReason="TERRARIUM DOUBLES NATIVE STAGE"
          state.intro.fullOpeningStyle=style;state.intro.fullOpeningClass=class
          state.intro.suppressOpeningWildEnemy=false
        end
        b.fullOwned=true
      elseif full.active or full.pending then
        -- Do not leave an invisible legacy gate behind default photography.
        full.clear()
      end
    end
    if b.fullOwned and (full.active or full.pending) then
      local req={protocol=1,battle=view,context=ctx,phase="intro",
        progress=ctx.progress or 0,groundY=ctx.groundY or 0,arena=ctx.arena,
        base=baseCamera(ctx.arena),nativeOwner=nil}
      local ok,p=pcall(C.provider.frame,C.provider,req)
      if ok and poseOK(p) then
        b.lastPose=copyPose(p);b.lastKind="full";b.lastSide="enemy"
        return p,"SELECTED FULL BATTLE INTRO",true
      end
      -- First rig may only arm pending Phenac. Keep its priority and private
      -- encounter view; show the neutral stage for that readiness frame only.
      local fallback=poseOK(b.lastPose) and copyPose(b.lastPose) or Opening74.wide(ctx,s,b)
      return fallback,"SELECTED FULL INTRO - RIG READY",true
    end
    if b.fullOwned and b.lastKind=="full" and poseOK(b.lastPose) then
      -- The same A edge can release Phenac one tick before Core consumes it.
      -- Never stack the default arena intro into this acknowledgement handoff.
      return copyPose(b.lastPose),"FULL INTRO -> NATIVE ACKNOWLEDGEMENT",true
