      end
      if held and ok and finite(x) and finite(z) then
        local age=math.max(0,Opening74.clock(s)-(b.launchAt or 0))
        local q=smootherstep(math.min(1,age/.18))
        local gy=tonumber(ctx.groundY) or 0
        held.focus[1]=mix(held.focus[1],x,q)
        held.focus[2]=mix(held.focus[2],gy+4.5,q)
        held.focus[3]=mix(held.focus[3],z,q)
        b.lastKind="launch-slot"
        return held,"BC THROW RELEASE -> SEND-IN SLOT PAN"
      end
      return held,"BC THROW RELEASE -> OWNER STAGE WAIT"
    end
    local p=Opening74.pan(b.launchRaw,Opening74.clock(s)-(b.launchAt or 0),.8,9.0)
    b.lastPose=copyPose(p or b.launchRaw);b.lastKind="launch"
    return p or b.launchRaw,"BC THROW RELEASE -> PRE-STAGED OWNER REVEAL"
  end
  function Opening74.pose(ctx,s,e)
    local b=Opening74.session(s)
    if not b then return nil,"opening unavailable" end
    local sendEvent=type(e)=="table" and e.kind=="send" and e.opening==true
    if not sendEvent and not b.sawSend then
      local p,why,keep=Opening74.full(ctx,s,b)
      if p or keep then return p,why,keep end
      return Opening74.wide(ctx,s,b)
    end
    if sendEvent then
      if not b.sawSend then
        b.sawSend=true
        -- Native Core actually advanced. The old full intro must never cover
        -- a throw or restart between individual Pokemon acknowledgement beats.
        state.battleOpening.clear()
        if b.fullOwned then
          -- Retire the synthetic encounter view through the existing native
          -- owner cleanup, so its trainer flags cannot leak into later play.
          pcall(C.provider.frame,C.provider,{protocol=1,battle=ctx.battle,
            context=ctx,phase=ctx.phase,arena=ctx.arena,base=baseCamera(ctx.arena),
            nativeOwner="CBE DOUBLES"})
        end
      end
    end
    local side=type(e)=="table" and type(e.slot)=="string" and e.slot:match("^(%a+)%-") or b.lastSide or "enemy"
    if side~="enemy" and side~="player" then return nil,"opening side unavailable" end
    local r,send=intro73Record(s,e)
    local release=r and r.release
    local hasBall=type(release)=="table" and release.done~=true
    if send and send.releaseStarted and finite(tonumber(send.releaseAge)) then
      local frame=math.max(0,tonumber(send.releaseAge))*60
      if frame>=50 or hasBall then
        local p,why=RetailIntro68.pose(ctx,r,send)
        if poseOK(p) then
          if frame>=50 then
            if b.ownerEvent~=e then b.ownerEvent=e;b.ownerAt=Opening74.clock(s) end
            b.ownerRaw=copyPose(p);b.ownerSide=side
            b.lastSide=side;b.lastEvent=e;b.lastKind="owner"
            b.lastPose=copyPose(p)
            return Opening74.owner(s,b),why
          end
          return p,why
        end
        if hasBall and frame<50 then return nil,"PROVIDER RELEASE PRESENTATION",true end
      end
    elseif hasBall then
      return nil,"PROVIDER RELEASE PRESENTATION",true
    end
    if send and not send.releaseOnly and not send.releaseStarted
        and finite(tonumber(send.phase)) and tonumber(send.phase)<.76 then
      local p,why=intro73Trainer(ctx,b,side)
      if poseOK(p) then
        b.lastPose=copyPose(p);b.lastSide=side;b.lastEvent=e;b.lastKind="trainer"
        return p,why
      end
      -- Missing trainer geometry keeps the safe arena, never a guessed trainer.
      return Opening74.wide(ctx,s,b)
    end
    if sendEvent then
      return Opening74.launch(ctx,s,b,e,r,send)
    end
    if poseOK(b.ownerRaw) and b.ownerSide==side then
      return Opening74.owner(s,b),"BC MOVING OWNER HOLD -> "..tostring(e and e.slot or side)
    end
    if poseOK(b.ownerRaw) then return Opening74.owner(s,b),"BC MOVING OWNER TAIL" end
    return Opening74.wide(ctx,s,b)
  end
  -- End Test75 moving opening ---------------------------------------------

  -- Test77: native opening gate + real doubles passive preset scheduler ------
  -- BossIntro proves the safe integration pattern: an outer BattleState.update
  -- owner may HOLD the native opening queue while a presentation-only prelude
  -- runs, then release the untouched provider update. Test77 uses that principle
  -- only on exact pinned Terrarium/CBE doubles sessions. It never writes provider
  -- preferences, Core clocks/events, actors, HP, targeting or animation state.
  state.cbeBossIntroSeen77=state.cbeBossIntroSeen77 or setmetatable({},{__mode="k"})
  local OpeningGate77={basicDuration=1.55,installed=false,lastReason=nil,holds=0,
    bossSeen=state.cbeBossIntroSeen77}
  local Passive77={core=nil,idle=0,time=0,last=nil,preset=nil,claims=0,resets=0}

  local function providerBossActive77(N,screen)
    local B=N and N.BossIntro
    if not (type(B)=="table" and type(B.active)=="function") then return false end
    local ok,v=pcall(B.active,screen)
    return ok and v~=nil
  end

  local function resetPassive77(reason)
    if Passive77.core~=nil then Passive77.resets=Passive77.resets+1 end
    Passive77.core=nil;Passive77.idle=0;Passive77.time=0;Passive77.last=nil
    Passive77.preset=nil;Passive77.reason=reason
  end

  local function doublesRig77(arena)
    local src=type(arena)=="table" and arena.camera or nil
    src=type(src)=="table" and src or {side=58,back=17,height=20,lookX=0,lookY=6,frameH=50}
    return {side=tonumber(src.side) or 58,back=tonumber(src.back) or 17,
      height=tonumber(src.height) or 20,lookX=tonumber(src.lookX) or 0,
      lookY=tonumber(src.lookY) or 6,frameH=tonumber(src.frameH) or 50,
      __bcActorScale=1.0}
  end
  local DoublesPresetCamera77={rigFor=doublesRig77}

  local function doublesPassive77(ctx,basePose)
    local N,s=doublesSession76(ctx)
    if not s then resetPassive77("no doubles session");return nil,nil,false end
    local core=s.core
    local preset=selectedPreset()
    local eligible=enabled() and state.cameraAuthority.priority()
      and (preset=="stadium" or preset=="dw3" or preset=="portrait_test")
      and core and core.phase=="command" and core.currentEvent==nil
      and not state.battleOpening.active and not state.battleOpening.pending
      and not state.intro.active and not state.attack.active and not state.faint.active
    if not eligible then resetPassive77("not passive command phase");return nil,nil,false end

    local t=now()
    if Passive77.core~=core or Passive77.preset~=preset then
      Passive77.core=core;Passive77.preset=preset;Passive77.idle=0;Passive77.time=0
      Passive77.last=t;Passive77.reason="arming"
    end
    local dt=math.max(0,math.min(.10,t-(Passive77.last or t)));Passive77.last=t
    if Passive77.idle<idleDelay() then
      Passive77.idle=math.min(idleDelay(),Passive77.idle+dt)
      if Passive77.idle<idleDelay() then return nil,"BC DOUBLES PRESET ARM",false end
      Passive77.time=0
    else
      Passive77.time=Passive77.time+dt
    end

    -- Borrow only the existing preset author's presentation clock/metadata for
    -- this synchronous camera solve. The normal singles scheduler is not started
    -- and its state is restored before returning. APB's old one-actor-per-side
    -- resolver is suppressed while authoring the base pose; Test76 then refits
    -- close beats against the actual four provider actors.
    local savedTime=state.time
    local savedToken,savedIntent=state.passiveShotToken,state.passiveShotIntent
    local savedApb=state.apb
    state.time=Passive77.time;state.passiveShotToken=nil;state.passiveShotIntent=nil;state.apb=nil
    local ok,p,pitch,w
    if preset=="stadium" then ok,p,pitch,w=pcall(stadiumClassicPose,ctx.arena,ctx.groundY,DoublesPresetCamera77)
    elseif preset=="dw3" then ok,p,pitch,w=pcall(cinematicPose,ctx.arena,ctx.groundY,DoublesPresetCamera77)
    else ok,p,pitch,w=pcall(portraitTestPose,ctx.arena,ctx.groundY,DoublesPresetCamera77) end
    state.apb=savedApb
    local out,why,handled=nil,nil,false
    if ok and poseOK(p) then
      local okS,a,b,c=pcall(subjectPreset39,ctx,p)
      if okS then out,why,handled=a,b,c else X.errors=(X.errors or 0)+1;why="subjectPreset39: "..tostring(a) end
      if not handled then out=p;why="BC DOUBLES AUTHORED PRESET" end
    elseif not ok then
      X.errors=(X.errors or 0)+1;why="preset author: "..tostring(p)
    else
      -- Hero's authored neutral pauses deliberately return no camera. Let the
      -- structural four-slot master punctuate that gap exactly as intended.
      why=(preset=="portrait_test") and "HERO PORTRAIT AUTHORED GAP" or "PRESET GAP"
    end
    state.time=savedTime;state.passiveShotToken=savedToken;state.passiveShotIntent=savedIntent
    if poseOK(out) then
      local age=math.max(0,Passive77.time)
      local blend=math.max(0,math.min(1,age/math.max(.001,BLEND_TIME)))
      if blend<1 and poseOK(basePose) then out=mixCamera(basePose,out,smootherstep(blend)) end
      Passive77.claims=Passive77.claims+1;Passive77.reason=why
      return out,why or "BC DOUBLES PRESET",true
    end
    Passive77.reason=why
    return nil,why,false
  end

  local function installOpeningGate77(residentV)
    if OpeningGate77.installed then return true end
    local req=require
    local V=residentV or (X.exports and X.exports.lib)
    if V and type(V.engineRequire)=="function" then req=V.engineRequire end
    local ok,class=pcall(req,"src.battle.BattleState")
    if not (ok and type(class)=="table" and type(class.update)=="function") then
      OpeningGate77.lastReason="BattleState unavailable";return false
    end
    if class.__bcOpeningGate77Installed then
      OpeningGate77.lastReason="existing Test77 gate";state.cbeOpeningAutoGate77=true
      OpeningGate77.installed=true;return true
    end
    local old=class.update
    local wrapper
    wrapper=function(screen,dt,...)
      local N=X.doublesNamespace55
      if not (N and N.DoublesRuntime) or not enabled() or not state.cameraAuthority.priority() then
        return old(screen,dt,...)
      end
      if providerBossActive77(N,screen) then
        OpeningGate77.bossSeen[screen]=true
        return old(screen,dt,...)
      end
      local D=N.DoublesRuntime
      local s=type(D.presentation)=="function" and D.presentation(screen) or nil
      if not s and type(D.combat)=="function" then s=D.combat(screen) end
      if not (s and s.core and s.screen==screen) then return old(screen,dt,...) end
      if OpeningGate77.bossSeen[screen] then return old(screen,dt,...) end
      local b=Opening74.session(s)
      if not (b and Opening74.scope(s)) then return old(screen,dt,...) end
      local ctx=s.context
      if not (type(ctx)=="table" and type(ctx.services)=="table" and ctx.services.cbeStandalone==true
          and type(ctx.arena)=="table" and not ctx.arena.liveField) then
        return old(screen,dt,...)
      end

      local step=math.max(0,math.min(.10,tonumber(dt) or 0))
      local hold,reason=false,nil
      -- Give the camera seam one rendered opportunity to arbitrate Phenac versus
      -- the basic intro before Core can synthetically acknowledge its first text.
      if not b.fullConsidered then
        hold=true;reason="BC INTRO ARBITRATION"
      elseif b.fullOwned or state.battleOpening.pending or state.battleOpening.active then
        hold=state.battleOpening.pending
          or (state.battleOpening.active and state.battleOpening.phase=="swoop")
        reason=hold and "PHENAC PRE-NATIVE HOLD" or nil
      else
        b.basicGate77=tonumber(b.basicGate77) or 0
        if b.basicGate77<OpeningGate77.basicDuration then
          b.basicGate77=math.min(OpeningGate77.basicDuration,b.basicGate77+step)
          hold=true;reason="BC BASIC PRE-NATIVE HOLD"
        end
      end
      if hold then
        b.clockOffset77=(tonumber(b.clockOffset77) or 0)+step
        OpeningGate77.holds=OpeningGate77.holds+1;OpeningGate77.lastReason=reason
        -- Exact BossIntro ownership principle: do not call the wrapped native
        -- BattleState.update at all. Auto-progress therefore cannot synthesize A,
        -- while the rest of the game/render loop and BC's own camera clock live.
        return
      end
      return old(screen,dt,...)
    end
    class.update=wrapper;class.__bcOpeningGate77Installed=true
    state.cbeOpeningAutoGate77=true
    OpeningGate77.installed=true;OpeningGate77.lastReason="armed"
    X.restoreOpeningGate77=function()
      if class.update==wrapper then class.update=old end
      if class.__bcOpeningGate77Installed then class.__bcOpeningGate77Installed=nil end
      state.cbeOpeningAutoGate77=false;OpeningGate77.installed=false
    end
    return true
  end
  -- End Test77 native gate + passive scheduler -------------------------------

  -- Test78: subsequent doubles send-in continuity ----------------------------
  -- Test77 is the locked opening/passive parent.  This module owns ONLY later
  -- provider send events (opening~=true): voluntary switches and post-faint
  -- replacements.  It never changes Core, trainer, actor, HP, input or timing.
  -- The same real provider sendout clock already proven in the opening is
  -- photographed through trainer throw -> ball_open -> finite owner reveal.
  local Subsequent78={current=nil,claims=0,lastReason=nil}
  function Subsequent78.session(s)
    local core=s and s.core
    if not core then Subsequent78.current=nil;return nil end
    local b=Subsequent78.current
    if not b or b.core~=core then
      b={core=core,trainers={},lastPose=nil,lastEvent=nil,lastSide=nil,launchEvent=nil,launchAt=nil,launchRaw=nil}
      Subsequent78.current=b
    end
    return b
  end
  function Subsequent78.state(ctx)
    local N,s=doublesSession76(ctx)
    if not s then return nil end
    local e=s.core and s.core.currentEvent
    if not (type(e)=="table" and e.kind=="send" and e.opening~=true and type(e.slot)=="string") then
      return nil
    end
    local r,send=intro73Record(s,e)
    if not (r and type(send)=="table") then return s,e,nil,nil end
    return s,e,r,send
  end
  local function subsequentSlotStage78(ctx,s,b,e,r,send)
    if b.launchEvent~=e then
      b.launchEvent=e;b.launchAt=Opening74.clock(s);b.launchRaw=nil
    end
    -- Use the exact already-accepted Test71 owner-camera start whenever the live
    -- actor exposes its chest.  This is only photography of the real incoming
    -- battler; it does not reveal, spawn or advance it early.
    if r then
      local staged=select(1,intro71OwnerReveal(ctx,r,send,50))
      if poseOK(staged) then b.launchRaw=copyPose(staged) end
    end
    if poseOK(b.launchRaw) then
      local p=Opening74.pan(b.launchRaw,Opening74.clock(s)-(b.launchAt or 0),.8,9.0)
      b.lastPose=copyPose(p or b.launchRaw)
      return p or b.launchRaw,"BC SUBSEQUENT SEND-IN -> PRE-STAGED OWNER REVEAL"
    end
    -- The actor can legitimately still be hidden between trainer follow-through
    -- and release.  Keep the last safe trainer eye and redirect only its focus to
    -- the provider's actual receiving slot.  No guessed master, fake ball path or
    -- provider wait is introduced.
    local held=poseOK(b.lastPose) and copyPose(b.lastPose) or nil
    local N=X.doublesNamespace55
    local ok,x,z=false,nil,nil
    if N and N.DoublesPresenter and type(N.DoublesPresenter.anchor)=="function" then
      ok,x,z=pcall(N.DoublesPresenter.anchor,ctx,e.slot)
    end
    if held and ok and finite(x) and finite(z) then
      local age=math.max(0,Opening74.clock(s)-(b.launchAt or 0))
      local q=smootherstep(math.min(1,age/.18))
      local gy=tonumber(ctx.groundY) or 0
      held.focus[1]=mix(held.focus[1],x,q)
      held.focus[2]=mix(held.focus[2],gy+4.5,q)
      held.focus[3]=mix(held.focus[3],z,q)
      b.lastPose=copyPose(held)
      return held,"BC SUBSEQUENT SEND-IN -> SLOT PAN"
    end
    return held,"BC SUBSEQUENT SEND-IN -> OWNER STAGE WAIT"
  end
  function Subsequent78.pose(ctx,s,e,r,send)
    local b=Subsequent78.session(s)
    if not b then return nil,"subsequent send session unavailable" end
    local side=e.slot:match("^(%a+)%-")
    if side~="player" and side~="enemy" then return nil,"subsequent send side unavailable" end
    b.lastSide=side
    if not (r and send) then return nil,"subsequent send presenter record pending" end

    -- Same provider-authored trainer performance boundary accepted in Test77:
    -- retain the real trainer through throw + follow-through and leave before
    -- recovery.  Later sends are NOT an opening and never invoke Basic/Phenac.
    if not send.releaseOnly and not send.releaseStarted
        and finite(tonumber(send.phase)) and tonumber(send.phase)<.76 then
      local p,why=intro73Trainer(ctx,b,side)
      if poseOK(p) then
        b.lastPose=copyPose(p);b.lastEvent=e
        return p,"BC SUBSEQUENT TRAINER THROW / "..tostring(why or side)
      end
    end

    -- After trainer follow-through, stage the real destination immediately.
    if not send.releaseStarted then
      return subsequentSlotStage78(ctx,s,b,e,r,send)
    end

    -- Provider releaseAge is the exact source ownership clock used by Test71.
    -- Reuse the accepted ball_open -> owner grammar, including Test77's generic
    -- front-quarter reveal guard.  No opening-only arbitration is re-entered.
    local p,why=RetailIntro68.pose(ctx,r,send)
    if poseOK(p) then
      b.lastPose=copyPose(p);b.lastEvent=e
      Subsequent78.claims=Subsequent78.claims+1
      Subsequent78.lastReason=why
      return p,"BC SUBSEQUENT SEND-IN / "..tostring(why or "source reveal")
    end
    return subsequentSlotStage78(ctx,s,b,e,r,send)
  end
  -- End Test78 subsequent doubles send-in continuity -------------------------

  function Retail59.faintHold(ctx)
    local N=X.doublesNamespace55
    local s=N and N.DoublesRuntime and N.DoublesRuntime.presentation and N.DoublesRuntime.presentation(ctx.battle)
    if not s and N and N.DoublesRuntime and N.DoublesRuntime.combat then s=N.DoublesRuntime.combat(ctx.battle) end
    local e=s and s.core and s.core.currentEvent
    if not (type(e)=="table" and e.kind=="faint" and type(e.slot)=="string") then return nil end
    local saved=Retail59.lastDamagePose[e.slot]
    if not (saved and poseOK(saved.pose)) then return nil end
    if saved.targetBattlerId and e.battlerId and saved.targetBattlerId~=e.battlerId then return nil end
    local trace=s.core.targetTrace and s.core.targetTrace[#s.core.targetTrace]
    if saved.parentEventId and trace and trace.presentationEventId
        and saved.parentEventId~=trace.presentationEventId then return nil end
    return copyPose(saved.pose),"RETAIL RECEIVER -> FAINT HOLD "..e.slot
  end

  -- Test87: staged Terrarium/CBE singles resident-reveal parity ---------------
  -- Tests82-86 are discarded experiments. Test87 is rebased from locked Test81
  -- and carries only the proven presentation law back into staged singles:
  -- actual trainer throw -> finite source-admitted owner camera -> authored idle.
  -- There is deliberately NO BC-owned ball-flight/empty-slot state. If the live
  -- resident actor is not drawable yet, BC yields those transient frames to the
  -- provider rather than manufacturing or latching a bridge.
  --
  -- Camera grammar remains source-derived (CalculateParams flag 4, legal
  -- 3/0/1/2 family, source FOV, retail bound/timing). Translation geometry uses
  -- BC's already-proven resident actor envelope/fight axis (`subject23`) because
  -- that is the geometry actually rendered in staged singles. This avoids the
  -- failed strict Waza-basis assumption from Test82-86 and keeps send-in views
  -- inside the accepted front-quarter reveal policy without species exceptions.
  local Singles87={battle=nil,sides={},trainers={},subjectR=nil,lastMode=nil,
    currentSide=nil,started=false,fullConsidered=false,fullOwned=false,bossSeen=false,
    basicStart=nil,basicWide=nil,
    claims=0,trainerClaims=0,revealClaims=0,lastReason=nil}

  local function singles87Reset(ctx)
    if Singles87.battle==ctx.battle then return Singles87 end
    Singles87.battle=ctx.battle;Singles87.sides={};Singles87.trainers={}
    Singles87.subjectR={bounds=setmetatable({},{__mode="k"})}
    Singles87.lastMode=nil;Singles87.currentSide=nil;Singles87.started=false
    Singles87.fullConsidered=false;Singles87.fullOwned=false;Singles87.bossSeen=false
    Singles87.basicStart=nil;Singles87.basicWide=nil
    Singles87.claims=0;Singles87.trainerClaims=0;Singles87.revealClaims=0;Singles87.lastReason=nil
    return Singles87
  end
  local function singles87Staged(ctx)
    if not liveStandalone(ctx) or type(ctx.arena)~="table" then return false end
    if ctx.arena.liveField~=true then return true end
    local id=tostring(ctx.arena._cbeArenaId or ctx.arena.selectedArena or ""):lower()
    return id=="overworld"
  end
  local function singles87Wild(ctx)
    local b=ctx and ctx.battle or nil;local e=ctx and ctx.encounter or nil
    local bk=tostring(b and b.kind or ""):lower();local ek=tostring(e and e.kind or ""):lower()
    return bk=="wild" or ek=="wild" or (b and b.wild==true)
  end
  local function singles87Side(S,ctx,side)
    local b=S.sides[side]
    if not b then
      b={context=ctx,side=side,trainers=S.trainers,serial=0,cycleActive=false,
        throwSeen=false,lastActiveAt=nil,graceUntil=nil,revealAt=nil,revealPlan=nil,
        revealPose=nil,revealComplete=false,lastTrainer=nil,lastStatus=nil}
      S.sides[side]=b
    end
    b.context=ctx;b.trainers=S.trainers
    return b
  end
  local function singles87SuppressLegacyIntro()
    -- Source-owned staged sends supersede the old per-Pokemon Hero intro only.
    -- Full Battle Intro is a separate encounter-level feature and is untouched.
    clearIntro();state.intro.pendingEnemy=false;state.intro.pendingPlayer=false
  end
  local function singles87Resume()
    -- Pre-arm the already-selected Stadium/DW3/Hero passive language. The normal
    -- phase gates still decide when it can draw; this only prevents the old
    -- post-send initial-delay/no-authored-shot dead state.
    state.active=true;state.blend=1;state.idle=0;state.time=0
    state.intro.openingChainHold=false;state.intro.openingBridgeActive=false
    state.geomDiag.phaseHandoffRC3="SINGLES_SOURCE_SEND_TO_PASSIVE"
  end
  local function singles87Finish(S,b)
    b.cycleActive=false;b.throwSeen=false;b.lastActiveAt=nil;b.graceUntil=nil
    b.revealAt=nil;b.revealPlan=nil;b.revealPose=nil;b.revealComplete=false
    b.lastTrainer=nil;b.lastStatus=nil
    if S.currentSide==b.side then S.currentSide=nil end
    singles87SuppressLegacyIntro();singles87Resume()
  end
  local function singles87Trainer(ctx,S,side)
    local N=X.doublesNamespace55
    local obj=N and (side=="player" and N.PlayerTrainer or N.Trainer)
    local b=singles87Side(S,ctx,side)
    local pose,why=intro73Trainer(ctx,b,side)
    if not (type(obj)=="table" and type(obj.sendoutStatus)=="function") then
      return nil,pose,why
    end
    local rec=b.trainers[side]
    if not (rec and rec.verified) then return nil,pose,why end
    -- Public provider presentation query. It does not advance TrainerPerformance
    -- or begin/replay the throw; it only reports the already-running action.
    local ok,status=pcall(obj.sendoutStatus,obj)
    if not ok or type(status)~="table" or status.active~=true
        or not finite(tonumber(status.phase)) then return nil,pose,why end
    return status,pose,why
  end
  local function singles87Activity(ctx,side,status)
    if type(status)=="table" and status.active==true then return true end
    local battle=ctx and ctx.battle;if not battle then return false end
    local battler=side=="player" and battle.player or battle.enemy
    local grow=battle.growIn
    local growing=type(grow)=="table" and grow.battler==battler
    local sending=(side=="player" and battle.sendingOut==true)
      or (side=="enemy" and battle.enemySendingOut==true)
    return sending or growing
  end

  -- Late admission of BC's ACTUAL selected full Battle Intro. battle.started can
  -- see the indoor map before Terrarium has exposed the self-contained staged
  -- arena and therefore reject Phenac too early. Once this exact staged route is
