  local function singles87Plan(ctx,S,b,side,subject)
    local actor=subject and subject.actor
    local N=X.doublesNamespace55;local W=N and N.WazaCameraParams
    if not (actor and type(W)=="table" and type(W.calculate)=="function"
        and type(W.sampleMotion)=="function" and type(W.motionOptionsForPokemonDex)=="function") then
      return nil,"singles source helpers unavailable"
    end
    local dex=tonumber(actor.dex);local sm=actor.sourceMetadata
    local selector=sm and tonumber(sm.scaleSelector~=nil and sm.scaleSelector or sm.sequenceKind) or nil
    local md=dex and Retail59.meta[dex]
    if selector==nil then selector=md and tonumber(md[1]) end
    local f=subject.forward
    local yaw=f and Retail59.atan2(tonumber(f[1]) or 0,tonumber(f[3]) or 0) or nil
    if not (dex and selector~=nil and finite(yaw)) then return nil,"singles source metadata unavailable" end
    local _,bound,timing,cameraEnd,retailHeight=Retail59.bound(dex,0)
    if not (bound and timing and finite(cameraEnd) and cameraEnd>0) then return nil,"singles source timing unavailable" end
    local params,why=W.calculate(4,selector,bound,yaw)
    if not (type(params)=="table" and params.exact==true) then
      return nil,"singles CalculateParams: "..tostring(why)
    end
    local key=table.concat({tostring(actor),side,tostring(dex),tostring(selector),tostring(b.serial or 0)},":")
    if b.revealPlan and b.revealPlan.key==key then return b.revealPlan end
    local options=W.motionOptionsForPokemonDex(4,dex)
    if type(options)~="table" or #options<1 then return nil,"singles source motion set unavailable" end
    local pool={}
    for _,mode in ipairs(options) do if #options==1 or mode~=S.lastMode then pool[#pool+1]=mode end end
    if #pool==0 then pool=options end
    local idx=math.min(#pool,math.floor(Retail59.rand(key,"single87-owner-mode")*#pool)+1)
    local mode=pool[idx]
    local sample,whyMotion=W.sampleMotion(mode,params,
      function(drawKey)return Retail59.rand(key,"single87-owner:"..tostring(drawKey))end,
      {rotationBase=yaw,reverse=side=="player"})
    if not (type(sample)=="table" and sample.scalarFormulaExact==true) then
      return nil,"singles DoPosition: "..tostring(whyMotion)
    end
    local plan={key=key,dex=dex,selector=selector,mode=mode,sample=sample,params=params,
      timing=timing,cameraEnd=cameraEnd,retailHeight=retailHeight}
    b.revealPlan=plan;S.lastMode=mode
    return plan
  end
  local function singles87Reveal(ctx,S,b,side)
    local subject,whySubject=subject23(ctx,side,S.subjectR)
    if not subject then return nil,whySubject,false end
    local plan,why=singles87Plan(ctx,S,b,side,subject)
    if not plan then return nil,why,false end
    if not b.revealAt then b.revealAt=now() end
    local frame=math.min(math.max(0,(now()-b.revealAt)*60),math.max(1,plan.cameraEnd))
    local raw=math.max(0,math.min(1,frame/math.max(1,plan.cameraEnd)))
    local sample=plan.sample;local focus={subject.center[1],subject.center[2],subject.center[3]}
    local k=tonumber((ctx.services or {}).figureScale) or tonumber(ctx.arena and ctx.arena.figureScale)
    if not (finite(k) and k>0) then return nil,"singles figureScale unavailable",false end
    local distance=(tonumber(sample.distance0) or tonumber(plan.params.distanceMin) or 40)
    if sample.mode==0 and tonumber(sample.distance1) then
      distance=distance+(sample.distance1-distance)*raw
    end
    local height=(tonumber(sample.height) or tonumber(plan.params.heightMin) or 6)
    local fx,fz=tonumber(subject.forward[1]) or 0,tonumber(subject.forward[3]) or 0
    local fl=math.sqrt(fx*fx+fz*fz);if fl<.001 then return nil,"singles resident facing unavailable",false end
    fx,fz=fx/fl,fz/fl;local rx,rz=-fz,fx
    local eye
    if sample.mode==1 and tonumber(sample.lateral0) and tonumber(sample.lateral1) then
      local lateral=sample.lateral0+(sample.lateral1-sample.lateral0)*raw
      eye={focus[1]+fx*distance*k+rx*lateral*k,focus[2]+height*k,
        focus[3]+fz*distance*k+rz*lateral*k}
    elseif tonumber(sample.worldRotation0) and tonumber(sample.worldRotation1) then
      local theta=sample.worldRotation0+(sample.worldRotation1-sample.worldRotation0)*raw
      eye={focus[1]+math.sin(theta)*distance*k,focus[2]+height*k,
        focus[3]+math.cos(theta)*distance*k}
    else
      return nil,"singles source rotation unavailable",false
    end
    -- Send-in presentation is always front/front-three-quarter. Preserve source
    -- radius, height and chosen lateral sign; only reflect/clamp a translated
    -- profile/rear result into the <=45-degree front quarter-plane.
    local vx,vz=eye[1]-focus[1],eye[3]-focus[3];local flat=math.sqrt(vx*vx+vz*vz)
    local front=vx*fx+vz*fz;local lateral=vx*rx+vz*rz
    if flat>.001 then
      local minFront=flat*math.cos(math.pi*.25)
      if front<minFront then
        front=minFront;local lat=math.sqrt(math.max(0,flat*flat-front*front))
        if lateral<0 then lat=-lat end
        eye[1]=focus[1]+fx*front+rx*lat;eye[3]=focus[3]+fz*front+rz*lat
      end
    end
    local fov=math.rad(39.090270996)
    local fovFn=N and N.WazaHandlers and N.WazaHandlers._test and N.WazaHandlers._test.sourceCameraFov
    if type(fovFn)=="function" then
      local decision={retailParams=plan.params,sequenceKind=0,paramsFlags=4,
        motion=plan.mode,motionSample=sample}
      local okF,value=pcall(fovFn,decision,plan.retailHeight,sample.fovRange or distance,
        Retail59.hash(plan.key),frame,plan.timing)
      if okF and finite(value) then fov=value end
    end
    local complete=frame>=math.max(1,plan.cameraEnd)-.01
    return {eye=eye,focus=focus,fov=fov,curve=0},
      "RETAIL SINGLES RESIDENT REVEAL M"..tostring(plan.mode).." "..side
        .." F"..string.format("%.1f",frame),complete
  end

  local function singles88Basic(ctx,S)
    -- Test87 wild staged battles are already runtime-good. Preserve their native/
    -- existing BC opponent opening unless Phenac itself owns the full-intro slot.
    if singles87Wild(ctx) then return nil end
    if S.started or S.fullOwned or S.bossSeen
        or state.battleOpening.pending or state.battleOpening.active then return nil end
    if not S.basicStart then S.basicStart=now();S.basicWide={} end
