    -- Reuse the exact Test75/77 BASIC author: same stage-relative master range,
    -- low lateral orbit and bounded movement already runtime-accepted in doubles.
    return Opening74.wide(ctx,clock,S.basicWide)
  end

  local SinglesPassive89={battle=nil,preset=nil,time=0,last=nil}
  local function singles89Passive(ctx,basePose)
    if not singles87Staged(ctx) or state.battleOpening.pending or state.battleOpening.active
        or state.intro.active or state.attack.active or state.faint.active then return nil end
    if Singles87.currentSide~=nil then return nil end
    for _,row in pairs(Singles87.sides or {}) do if row.cycleActive then return nil end end
    local preset=selectedPreset()
    if preset~="stadium" and preset~="dw3" and preset~="portrait_test" then return nil end
    local t=now()
    if SinglesPassive89.battle~=ctx.battle or SinglesPassive89.preset~=preset then
      SinglesPassive89.battle=ctx.battle;SinglesPassive89.preset=preset
      SinglesPassive89.time=0;SinglesPassive89.last=t
