    if preset=="stadium" then ok,p,whyPitch,w=pcall(stadiumClassicPose,ctx.arena,ctx.groundY,DoublesPresetCamera77)
    elseif preset=="dw3" then ok,p,whyPitch,w=pcall(cinematicPose,ctx.arena,ctx.groundY,DoublesPresetCamera77)
    else ok,p,whyPitch,w=pcall(portraitTestPose,ctx.arena,ctx.groundY,DoublesPresetCamera77) end
    state.apb=savedApb
    local out,why,handled=nil,nil,false
    if ok and poseOK(p) then
      local okS,a,b,c=pcall(subjectPreset39,ctx,p)
      if okS then out,why,handled=a,b,c else why="subject adapter: "..tostring(a) end
      if not handled then out=p;why="AUTHORED "..string.upper(preset) end
    elseif not ok then why="preset author: "..tostring(p)
