  function Singles87.pose(ctx)
    if not (enabled() and state.cameraAuthority.priority() and attackCameraStyle()=="colosseum"
        and singles87Staged(ctx)) then return nil end
    local S=singles87Reset(ctx);local owner=nativeOwner(ctx)
    if owner=="CBE DOUBLES" or owner=="CBE HUB" then return nil end
    if singles87FullIntro(ctx,S,owner) then return nil end

    local wild=singles87Wild(ctx)
    local enemyStatus,enemyTrainer,enemyWhy=singles87Trainer(ctx,S,"enemy")
    local playerStatus,playerTrainer,playerWhy=singles87Trainer(ctx,S,"player")
    local enemyActive=singles87Activity(ctx,"enemy",enemyStatus)
    local playerActive=singles87Activity(ctx,"player",playerStatus)
    local side,status,trainerPose,trainerWhy
    if wild then
      if playerActive then side,status,trainerPose,trainerWhy="player",playerStatus,playerTrainer,playerWhy end
    elseif enemyActive then
      side,status,trainerPose,trainerWhy="enemy",enemyStatus,enemyTrainer,enemyWhy
    elseif playerActive then
      side,status,trainerPose,trainerWhy="player",playerStatus,playerTrainer,playerWhy
    end

    -- A send can publish its resident actor on the same frame native flags clear.
    -- Keep a CAMERA-ONLY acquisition grace, but never claim the lens while no
    -- drawable subject exists. This closes the wild-first-send race without a
    -- ball-flight/empty-slot state that can get stuck.
    if not side and S.currentSide then
      local b=singles87Side(S,ctx,S.currentSide)
      if b.cycleActive and b.revealAt then
        side=S.currentSide
      elseif b.cycleActive and finite(b.graceUntil) and now()<=b.graceUntil then
        local p,why,complete=singles87Reveal(ctx,S,b,S.currentSide)
        if poseOK(p) then
          b.revealPose=copyPose(p);S.revealClaims=S.revealClaims+1
          if complete then singles87Finish(S,b) end
          return p,why
        end
        return nil
      elseif b.cycleActive then
        singles87Finish(S,b)
      end
    end

    if not side then
      if not S.started then
        local basic,whyBasic=singles88Basic(ctx,S)
        if poseOK(basic) then return basic,whyBasic end
      end
      return nil
    end
    local b=singles87Side(S,ctx,side)
    if not b.cycleActive then
      b.cycleActive=true;b.serial=(b.serial or 0)+1;b.throwSeen=false
      b.revealAt=nil;b.revealPlan=nil;b.revealPose=nil;b.revealComplete=false
      singles87SuppressLegacyIntro();clearAttack();clearFaint()
    end
    S.started=true;S.currentSide=side;b.lastActiveAt=now();b.graceUntil=now()+.55
    if type(status)=="table" then b.throwSeen=true;b.lastStatus=status end

    local trainerExpected=(side=="player") or not wild
    local phase=type(status)=="table" and tonumber(status.phase) or nil
    if trainerExpected and poseOK(trainerPose)
        and ((phase~=nil and phase<.76) or (phase==nil and not b.throwSeen)) then
      b.lastTrainer=copyPose(trainerPose);S.trainerClaims=S.trainerClaims+1
      return trainerPose,phase~=nil
        and ("BC SINGLES TRAINER THROW / "..tostring(trainerWhy or side))
        or ("BC SINGLES TRAINER HOLD -> NATIVE THROW / "..tostring(side))
    end

    -- Once the throw/follow-through is finished, only a REAL resident subject can
    -- make BC claim the lens. If it is not ready, yield to Terrarium's own camera
    -- for the transient ball/release frames. No BC ball-flight owner exists.
    if not b.revealAt then
      local p,why=singles87Reveal(ctx,S,b,side)
      if not poseOK(p) then return nil end
      b.revealPose=copyPose(p);S.revealClaims=S.revealClaims+1
      return p,why
    end
    local p,why,complete=singles87Reveal(ctx,S,b,side)
    if poseOK(p) then
      b.revealPose=copyPose(p);S.revealClaims=S.revealClaims+1
      if complete then singles87Finish(S,b) end
      return p,why
    end
    -- A resident actor disappearing mid-reveal is a hard camera boundary, not a
    -- reason to hold stale photography through the rest of the battle.
    singles87Finish(S,b)
    return nil
  end
