  -- Test91: staged singles first-enemy manual-flow reveal hold ----------------
  -- Runtime Test90 proved the remaining opening residual is not trainer timing:
  -- the first enemy resident reveal starts correctly, but native singles advances
  -- into the player's "Go!" send almost immediately even with Terrarium AUTO
  -- BATTLE FLOW disabled. Doubles already has an acknowledgement beat here, so
  -- its exact owner reveal can finish and continue as a gentle moving hold.
  --
  -- Translate only that presentation ownership into staged singles. Once the
  -- FIRST trainer-owned enemy resident reveal is drawable and the user's saved
  -- AUTO BATTLE FLOW is OFF, freeze only BattleState.update after that rendered
  -- frame. The resident source camera continues on BC wall time to its finite
  -- endpoint, then uses the same accepted moving optical owner hold as doubles.
  -- Logical A continues; logical B skips. Both are consumed by BC so the release
  -- edge cannot double-trigger native input. AUTO FLOW ON is completely unchanged.
  -- No trainer/body/ball/Pokemon/provider clock is written or replayed.
  local SinglesHold91={active=false,release=false,button=nil,screen=nil,battle=nil,
    side=nil,b=nil,lastPose=nil,lastWhy=nil,sourceComplete=false,holdAt=nil,
    updateInstalled=false,updateClass=nil,updateOld=nil,claims=0,holds=0,releases=0,
    used=setmetatable({},{__mode="k"})}
  state.singlesSendHold91=SinglesHold91

  local function singles91Screen(ctx)
    local battle=ctx and ctx.battle or nil
    -- Gen2's presentation facade keeps the actual BattleState screen in _view;
    -- Gen1/Gen3 use the battle screen itself. Keep the hold owner identity exact
    -- across generations without altering GenerationCompat.
    return type(battle)=="table" and type(battle._view)=="table" and battle._view or battle
  end

  local function singles91ManualFlow(ctx)
    local battle=ctx and ctx.battle or nil
    local game=(battle and battle.game) or (ctx and ctx.game) or mod.game
    local save=game and game.save
    local prefs=type(save)=="table" and (type(save.terrariumBattle)=="table" and save.terrariumBattle
      or (type(save.colosseumBattle)=="table" and save.colosseumBattle or nil)) or nil
    return type(prefs)=="table" and prefs.autoProgressEnabled==false
  end

  local function installSingles91UpdateGate()
    if SinglesHold91.updateInstalled then return true end
    local req=require
    local V=X.exports and X.exports.lib
    if V and type(V.engineRequire)=="function" then req=V.engineRequire end
    local ok,class=pcall(req,"src.battle.BattleState")
    if not (ok and type(class)=="table" and type(class.update)=="function") then return false end
    if class.__bcSinglesHold91Installed then
      SinglesHold91.updateInstalled=true;SinglesHold91.updateClass=class
      return true
    end
    local old=class.update
    local wrapper
    wrapper=function(screen,dt,...)
      local G=SinglesHold91
      if G.active and G.screen==screen then
        if not G.release then
          G.holds=G.holds+1
          -- Deliberately do not call the wrapped BattleState update. This is the
          -- same camera-ownership principle already accepted for BC full intros;
          -- render/input continue and the provider is resumed untouched.
          return
        end
        -- One update is now allowed through; camera-side cleanup happens on the
        -- next solve. The input edge itself was consumed by the Game wrapper.
        G.active=false;G.releases=G.releases+1
      end
      return old(screen,dt,...)
    end
    class.update=wrapper;class.__bcSinglesHold91Installed=true
    SinglesHold91.updateInstalled=true;SinglesHold91.updateClass=class;SinglesHold91.updateOld=old
    return true
  end

  local function singles91Release(button)
    local G=SinglesHold91
    if not G.active then return false end
    G.release=true;G.button=button or "continue"
    return true
  end

  -- Reuse the established logical-input seam instead of reading raw Android keys.
  -- This is intentionally a second, narrowly-scoped wrapper around Game methods;
  -- the existing Phenac/BC-Hero gates remain byte-identical underneath it.
  local function installSingles91Input()
    local function wrap(tbl,name)
      local inner=tbl and tbl[name];local flag="__bcSinglesHold91_"..tostring(name)
      if type(inner)~="function" or tbl[flag] then return end
      tbl[name]=function(self,...)
        local input=self and self.input
        local q=input and input.pressQueue
        local before=type(q)=="table" and #q or 0
        local result=inner(self,...)
        if SinglesHold91.active and type(q)=="table" then
          for i=#q,before+1,-1 do
            local key=q[i]
            if key=="a" or key=="b" then
              table.remove(q,i);singles91Release(key);break
            end
          end
        end
        return result
      end
      tbl[flag]=true
    end
    wrap(Game,"keypressed");wrap(Game,"gamepadpressed");wrap(Game,"joystickpressed");wrap(Game,"touchpressed")
  end
  installSingles91Input()

  -- Minimal visible affordance. A mirrors the manual doubles acknowledgement;
  -- B is the familiar BC skip. It exists only while this exact hold owns input.
  pcall(function()
    mod.hooks:wrap("render.hud",function(nextFn,game,viewport)
      local result=nextFn(game,viewport)
      if SinglesHold91.active and love and love.graphics then
        local g=love.graphics
        local ok=pcall(function()
          local w,h=g.getDimensions();local label="A  CONTINUE    B  SKIP"
          local font=g.getFont();local tw=(font and font.getWidth and font:getWidth(label)) or 150
          local th=(font and font.getHeight and font:getHeight()) or 14
          local px,py=10,5;local x=math.max(10,w-tw-px*2-12);local y=math.max(10,h-th-py*2-12)
          g.push("all");g.origin();g.setColor(.02,.025,.035,.78)
          g.rectangle("fill",x,y,tw+px*2,th+py*2,5,5);g.setColor(1,1,1,.96)
          g.print(label,x+px,y+py);g.pop()
        end)
        if not ok then pcall(g.setColor,1,1,1,1) end
      end
      return result
    end)
  end)

  local singles87Pose90=Singles87.pose
  Singles87.pose=function(ctx)
    local G=SinglesHold91
    if G.battle~=ctx.battle and G.active then
      G.active=false;G.release=false;G.screen=nil;G.battle=nil;G.b=nil;G.lastPose=nil
    end

    -- While the manual first-enemy hold owns the camera, continue the already
    -- source-derived reveal on wall time until it naturally ends. Do not ask
    -- native BattleState to advance underneath it. Once finite source motion is
    -- complete, continue the accepted doubles owner-hold optical pan.
    if G.active and G.battle==ctx.battle then
      local p,why=nil,nil
      if not G.sourceComplete then
        p,why=singles87Pose90(ctx)
        if poseOK(p) then G.lastPose=copyPose(p);G.lastWhy=why end
        if not (G.b and G.b.cycleActive) then
          G.sourceComplete=true;G.holdAt=now()
        end
      end
      if poseOK(p) then
        G.claims=G.claims+1
        return p,tostring(why or "RETAIL SINGLES RESIDENT REVEAL").." / MANUAL FIRST-ENEMY HOLD"
      end
      if poseOK(G.lastPose) then
        if not G.sourceComplete then G.sourceComplete=true;G.holdAt=now() end
        local held=Opening74.pan(G.lastPose,math.max(0,now()-(G.holdAt or now())),1.1,8.2)
        G.claims=G.claims+1
        return held or G.lastPose,"BC SINGLES FIRST ENEMY OWNER HOLD / A CONTINUE B SKIP"
      end
      -- A missing held pose must fail open; never make a new latch state.
      G.active=false;G.release=true
    end

    if G.release and G.battle==ctx.battle then
      G.release=false;G.button=nil;G.screen=nil;G.battle=nil;G.b=nil;G.lastPose=nil
      G.sourceComplete=false;G.holdAt=nil
    end

    local p,why=singles87Pose90(ctx)
    if not (poseOK(p) and type(why)=="string" and why:find("RETAIL SINGLES RESIDENT REVEAL",1,true)) then
      return p,why
    end
    local S=Singles87;local b=S.sides and S.sides.enemy
    local firstEnemy=b and b.side=="enemy" and tonumber(b.serial)==1
      and not singles87Wild(ctx) and not G.used[ctx.battle]
    if not (firstEnemy and singles91ManualFlow(ctx)) then return p,why end

    -- Start only once the real enemy resident reveal already exists. Pausing on
    -- the next BattleState tick therefore cannot strand a hidden Pokemon/trainer
    -- release. AUTO FLOW ON never reaches this branch.
    if not installSingles91UpdateGate() then return p,why end
    G.used[ctx.battle]=true;G.active=true;G.release=false;G.button=nil
    G.screen=singles91Screen(ctx);G.battle=ctx.battle;G.side="enemy";G.b=b
    G.lastPose=copyPose(p);G.lastWhy=why;G.sourceComplete=not b.cycleActive;G.holdAt=nil
    G.claims=G.claims+1
    return p,why.." / MANUAL FIRST-ENEMY HOLD ARMED"
  end
  -- End Test91 staged singles first-enemy manual-flow reveal hold -------------

  local function direct(ctx,value)
    if type(value)~="table" or not poseOK(value.pose) then return value end
    local s68,e68,r68,send68,providerPhase68,opening68=RetailIntro68.state(ctx)
    local opening74=Opening74.scope(s68)
    local introLive=(opening68 or opening74) and type(ctx)=="table" and type(ctx.services)=="table"
      and ctx.services.cbeStandalone==true and type(ctx.arena)=="table"
    if not liveStandalone(ctx) and not introLive then return value end
    X.writes=X.writes+1;X.lastWriteAt=now();X.lastPhase=tostring(ctx.phase or "?")
    if opening74 then
      -- The new default only photographs provider-owned opening states. It
      -- never clears the encounter/full-intro gate, acknowledges text, writes
