      g.push("all");pushed=true;g.origin();g.setScissor();g.setShader();g.setFont(font)
      local line=string.format("BC T35 %s RAW:%d/%d/%d/%d ns:%s ctx:%s err:%d/%d",
        X.state,X.rawDamageEvents,X.rawDamageHeld,X.rawDamageReleased,X.rawDamagePassed,
        X.CurrentSprites and "Y" or "N",X.live and "Y" or "N",X.errors,C and C.errors or 0)
      local detail=(tostring(X.rawDamageLast or "-").." | SEM:"..tostring(X.lastSemantic or "-").." | "..tostring(X.lastClock or "-").." | "..tostring(X.reason or "-")):sub(1,124)
      local panelW=math.max(220,math.min(w-20,math.max(font:getWidth(line),font:getWidth(detail))+18))
      local panelH=font:getHeight()*2+14
      local x=10
      local y=math.max(8,math.min(h-panelH-8,math.floor(h*0.58)))
      g.setColor(0,0,0,.82);g.rectangle("fill",x,y,panelW,panelH,4,4)
      g.setColor(1,1,1,1);g.print(line,x+7,y+4)
      g.print(detail,x+7,y+5+font:getHeight())
      g.pop();pushed=false
    end)
    if pushed then pcall(g.pop) end
    if not ok then X.hudError=tostring(err) end
  end
  if mod.hooks and type(mod.hooks.wrap)=="function" then
    local ok,err=pcall(function()
      mod.hooks:wrap("render.hud",function(nextFn,...)
        local r=pack(nextFn(...));hud();return unpack_(r,1,r.n)
      end)
    end)
    if not ok then X.hudError=tostring(err) end
  end
  if mod.events and type(mod.events.on)=="function" then
    mod.events:on("mods.loaded",install)
    mod.events:on("game.ready",function() detach("game reset");install() end)
    mod.events:on("battle.started",function(ev)
      local game=ev and ev.battle and ev.battle.game
      local prefs=game and game.save and game.save.colosseumBattle
      if type(prefs)=="table" and prefs.arenasEnabled==false then detach("CBE arenas OFF") end
      -- The provider's begin listener may already have bound the new context.
      -- Do not detach it here; it is the very context this battle will render.
      X.hudUntil=now()+12;install()
    end)
  end
  -- Preserve late CBE presentation past logical battle.ended. Release the
  -- context only when the EXISTING CBE visual-end detector reports completion.
  if C and type(C.checkVisualEnd)=="function" then
    local previous=C.checkVisualEnd
    C.checkVisualEnd=function(...)
      local r=pack(previous(...))
      if r[1] then detach("CBE visual presentation ended") end
      return unpack_(r,1,r.n)
    end
  end
  install()
end)()
